app.put('/api/permissions', authMiddleware, requirePermission('rechteverwaltung', 'write'), kartenAdmin.bestaetigungVerlangen, async (req, res) => {
  const { permissions } = req.body; // [{ group_name, page, access }]
  if (!Array.isArray(permissions)) return res.status(400).json({ error: 'permissions Array erforderlich' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // Befund W15: festhalten, wer welches Recht geändert hat (nur echte Änderungen)
    const vorher = await client.query('SELECT group_name, page, access FROM permissions');
    const aenderungen = adminProtokoll.rechteAenderungen(vorher.rows, permissions);
    for (const p of permissions) {
      if (!p.group_name || !p.page || !['none', 'read', 'write'].includes(p.access)) continue;
      if (p.access === 'none') {
        await client.query('DELETE FROM permissions WHERE group_name = $1 AND page = $2', [p.group_name, p.page]);
      } else {
        await client.query(
          `INSERT INTO permissions (group_name, page, access) VALUES ($1, $2, $3)
           ON CONFLICT (group_name, page) DO UPDATE SET access = EXCLUDED.access`,
          [p.group_name, p.page, p.access]
        );
      }
    }
    await adminProtokoll.eintragen(pool, client, req, aenderungen.map(a => ({
      bereich: 'rechte', aktion: 'geaendert', ziel: `${a.group_name} · ${a.page}`, alt: a.alt, neu: a.neu,
    })));
    await client.query('COMMIT');
    if (aenderungen.length) console.log(`[rechte] ${req.user?.email || '?'}: ${aenderungen.map(a => `${a.group_name}/${a.page} ${a.alt}->${a.neu}`).join(', ')}`);
    const result = await pool.query('SELECT group_name, page, access FROM permissions ORDER BY group_name, page');
    res.json({ success: true, permissions: result.rows, geaendert: aenderungen.length });
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Permission update error:', err);
    res.status(500).json({ error: 'Fehler beim Speichern' });
  } finally {
    client.release();
  }
});

// Get current user from session token
app.get('/api/auth/me', authMiddleware, async (req, res) => {
  try {
  const userId = req.user.user_id || req.user.id;
  const result = await pool.query(
    'SELECT id, email, name, username, wohnung, stweg, role, phone, strasse, plz, ort, groups_json, avatar_url FROM users WHERE id = $1',
    [userId]
  );
  const u = result.rows[0] || req.user;
  const groups = (() => { try { return JSON.parse(u.groups_json || '[]'); } catch { return []; } })();

  // Fetch user's assigned meters from energy-db (direct + group-based)
  let meters = [];
  try {
    const userEmail = u.email?.toLowerCase();
    const lowerGroups = groups.map(g => g.toLowerCase());
    if (userEmail || lowerGroups.length > 0) {
      const meterResult = await energyPool.query(
        `SELECT DISTINCT m.id as zaehler_id, m.name as bezeichnung, m.type as typ
         FROM meters m
         LEFT JOIN meter_users mu ON mu.meter_id = m.id AND LOWER(mu.user_email) = $1
         LEFT JOIN meter_groups mg ON mg.meter_id = m.id AND LOWER(mg.group_name) = ANY($2)
         WHERE mu.id IS NOT NULL OR mg.id IS NOT NULL
         ORDER BY m.name`,
        [userEmail || '', lowerGroups]
      );
      meters = meterResult.rows;
    }
  } catch { /* energy-db may not be available */ }

  // Fetch user's effective permissions
  const permissions = await getUserPermissions(groups);

  // Auto-grant energie-monitor access if user has assigned meters
  if (meters.length > 0 && !permissions['energie-monitor']) {
    permissions['energie-monitor'] = 'read';
  }
  // Abgeleitet (L6): dokumente = write, wenn das Konto irgendwo in der Ablage
  // schreiben darf (docSchreibtIrgendwo). Kein Seitenrecht in MANAGED_PAGES.
  if (docSchreibtIrgendwo(groups, permissions['projekte'])) permissions['dokumente'] = 'write';

  // Rechte fuer die Energie-App (L4): dieselben Pruefungen wie die Routen
  // (routes/energie-lesen.js energieRechte). Abgeleitete Schluessel, nicht in der
  // Rechteverwaltung: energie-stweg (STWEG-Sicht greift: Ausschuss/Verwaltung mit
  // vergebenem energie-monitor, NICHT das automatische oben), zaehler-technik
  // (requireZaehlerTechnik liesse durch).
  let energie = { stweg_sicht: [], technik: null, verwalten: null, anlagen_eigen: [] };
  try { energie = await energieLesen.energieRechte(req); } catch (e) { console.error('[auth/me] energie:', e.message); }
  if (energie.stweg_sicht.length && !permissions['energie-stweg']) permissions['energie-stweg'] = 'read';
  if (energie.technik && !permissions['zaehler-technik']) permissions['zaehler-technik'] = 'read';

  // Abgeleitet (Rosenweg Projekte, Farbe): projekte-bearbeiten = write, wer irgendein
  // Projekt anlegen oder bearbeiten darf (Ausschuss, Verwaltung mit projekte = schreiben, T/P)
  if (projekteRechte.projekteBearbeitenRecht(groups, permissions['projekte'])) permissions['projekte-bearbeiten'] = 'write';

  // WhatsApp-Opt-In aus personen-Tabelle (via email lookup)
  let whatsappOptIn = false;
  try {
    const pRes = await pool.query(
      `SELECT whatsapp_opt_in FROM personen WHERE LOWER(email) = LOWER($1) LIMIT 1`,
      [u.email || '']
    );
    whatsappOptIn = !!pRes.rows[0]?.whatsapp_opt_in;
  } catch { /* personen table may not exist yet */ }

  res.json({
    user: {
      id: u.id,
      username: u.username,
      name: u.name,
      email: u.email,
      role: u.role,
      wohnung: u.wohnung,
      stweg: u.stweg,
      phone: u.phone,
      strasse: u.strasse,
      plz: u.plz,
      ort: u.ort,
      avatar_url: u.avatar_url,
      isAdmin: u.role === 'admin',
      groups: groups,
      meters: meters,
      permissions: permissions,
      energie,
      whatsapp_opt_in: whatsappOptIn,
    },
    // Wie ist diese Anfrage angemeldet (lib/stufen.js)? Nur Auskunft, sperrt nichts.
    // stufe: karte | konto | frisch; art: website | otp | app | authentik | pat | karte | qr | handy | anlage | bestaetigt
    anmeldung: { ...(req.auth || { stufe: 'karte', art: 'unbekannt', auth_time: null }), frisch_min: STUFE_FRISCH_MIN },
  });
  } catch (err) {
    console.error('[auth/me] Error:', err.message);
    res.status(500).json({ error: 'Benutzerdaten konnten nicht geladen werden' });
  }
});

// Name als Ausweis fuer "Meine Wohnung": Viele Kontakte haben eine abweichende oder
// Platzhalter-E-Mail, darum zaehlt auch der Name — aber nur, solange die Person ihn
// nicht selbst geaendert hat (sonst traegt man den Namen eines fremden Eigentuemers ein).
async function wohnungsAbgleichName(req) {
  const id = req.user?.user_id || req.user?.id;
  if (!id) return req.user?.name || '';
  const r = await pool.query('SELECT name, name_selbst_geaendert_am FROM users WHERE id = $1', [id]).catch(() => ({ rows: [] }));
  if (r.rows[0]?.name_selbst_geaendert_am) return '';
  return req.user?.name || '';
}

// SQL-Bedingung "Kontakt passt per Name". Der Name ist kein sicherer Ausweis (in
// Authentik u. U. selbst aenderbar) -> Namensgleichheit zaehlt nur fuer Kontakte
// ohne E-Mail oder mit einer E-Mail, die zu keinem Konto gehoert. Kontakte einer
// Person mit eigenem Konto lassen sich so nicht per Namensgleichheit uebernehmen.
function kontaktNameTreffer(alias, param) {
  return `(${param} <> '' AND LOWER(${alias}name) = LOWER(${param})
    AND (COALESCE(${alias}email, '') = '' OR NOT EXISTS (SELECT 1 FROM users ux WHERE LOWER(ux.email) = LOWER(${alias}email))))`;
}

// GET /api/me/wohnungen — finds apartments where the logged-in user is a contact
app.get('/api/me/wohnungen', authMiddleware, async (req, res) => {
  try {
    const email = (req.user.email || '').toLowerCase();
    const name = await wohnungsAbgleichName(req);
    if (!email && !name) return res.json({ wohnungen: [] });

    // Match by email (case-insensitive) OR by exact name
    const result = await pool.query(
      `SELECT k.id AS kontakt_id, k.name, k.email, k.telefon, k.adresse, k.rolle,
              w.id AS wohnung_id, w.bezeichnung, w.stockwerk, w.zimmer, w.flaeche_m2,
              w.typ, w.besonderheiten, w.bewohnt_von, w.stweg, w.notizen,
              w.waschkueche_berechtigt, w.wertquote_zaehler, w.wertquote_nenner
       FROM wohnungen_kontakte k JOIN wohnungen w ON k.wohnung_id = w.id
       WHERE ($1 <> '' AND LOWER(k.email) = $1) OR ${kontaktNameTreffer('k.', '$2')}
       ORDER BY w.stweg, w.bezeichnung`,
      [email, name]
    );
    res.json({ wohnungen: result.rows });
  } catch (err) {
    console.error('[me/wohnungen] error:', err.message);
    res.status(500).json({ error: 'Fehler' });
  }
});

// PUT /api/me/kontakt/:id — user can edit their own contact entry (email, telefon, adresse)
// Wenn der Kontakt eine person_id hat, wird die Person aktualisiert → Trigger
// propagiert auf alle Wohnungen der Person. Dadurch ist die Änderung "sticky"
// für den User: er sieht sie ueberall.
// Einfache Formatpruefung fuer selbst gepflegte E-Mail-Adressen: die Werte landen
// in Frontends (u. a. Inline-Handler) und in Mail-Empfaengerlisten.
function emailFormatOk(v) {
  return typeof v === 'string' && v.length <= 254 && /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(v);
}

// R3-S1b: Gemeinsame Pruefung fuer selbst gepflegte Kontaktdaten (wie /me/emails, /me/phones).
// E-Mail und Telefon dienen der Zuordnung (Login per E-Mail, WhatsApp/Anruf -> Person,
// Gruppen/Broadcasts). Eine Adresse, die einem Konto oder einer ANDEREN Person gehoert,
// oder eine Nummer einer anderen Person (Vergleich: letzte 9 Ziffern) wuerde deren
// Identitaet uebernehmen. Liefert eine Fehlermeldung oder null. eigeneIds = Personen,
// die der Anfragende ohnehin ist bzw. die gerade bearbeitet wird.
async function fremdeKennung(db, { email, telefon, eigeneIds = [], ichEmail = '' }) {
  const ids = eigeneIds.map(Number).filter(Number.isInteger);
  const e = String(email || '').trim().toLowerCase();
  // Eigene Konto-Adresse: das eigene Konto ist kein Konflikt, eine ANDERE Person mit dieser
  // Adresse schon (sonst zweite Person mit der eigenen Kennung, R4b-S1d) -> nur users-Teil auslassen.
  if (e) {
    const r = await db.query(
      `SELECT 1 WHERE ($3 AND EXISTS (SELECT 1 FROM users u WHERE LOWER(u.email) = $1))
          OR EXISTS (SELECT 1 FROM personen p WHERE NOT (p.id = ANY($2::int[]))
                       AND (LOWER(p.email) = $1
                            OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(p.emails,'[]'::jsonb)) x WHERE LOWER(x) = $1)))`,
      [e, ids, e !== ichEmail]);
    if (r.rows.length) return 'Diese E-Mail-Adresse gehört bereits zu einem Konto oder einer anderen Person. Bitte bei der Verwaltung melden.';
  }
  const ziffern = String(telefon || '').replace(/\D/g, '');
  if (ziffern.length >= 9) {
    const r = await db.query(
      `SELECT 1 FROM personen p
        WHERE NOT (p.id = ANY($2::int[]))
          AND (RIGHT(regexp_replace(COALESCE(p.telefon,''), '\\D', '', 'g'), 9) = $1
            OR RIGHT(regexp_replace(COALESCE(p.mobile,''), '\\D', '', 'g'), 9) = $1
            OR EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(p.telefone, '[]'::jsonb)) x
                        WHERE RIGHT(regexp_replace(COALESCE(x->>'nummer',''), '\\D', '', 'g'), 9) = $1))
        LIMIT 1`, [ziffern.slice(-9), ids]);
    if (r.rows.length) return 'Diese Telefonnummer ist bereits bei einer anderen Person hinterlegt. Bitte bei der Verwaltung melden.';
  }
  return null;
}

// Personen-IDs des Anfragenden (Primaer-E-Mail oder Alias).
async function meinePersonenIds(db, ichEmail) {
  if (!ichEmail) return [];
  const r = await db.query(
    `SELECT id FROM personen WHERE LOWER(email) = $1
        OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(emails,'[]'::jsonb)) e WHERE LOWER(e) = $1)`, [ichEmail]);
  return r.rows.map(x => x.id);
}

// Nur Ziffern-Ende vergleichen: "079 …" und "+41 79 …" sind dieselbe Nummer.
function telefonGleich(a, b) {
  return String(a || '').replace(/\D/g, '').slice(-9) === String(b || '').replace(/\D/g, '').slice(-9);
}

app.put('/api/me/kontakt/:id', authMiddleware, async (req, res) => {
  try {
    {
      const b = req.body || {};
      if (b.email !== undefined && b.email !== null && b.email !== '' && !emailFormatOk(b.email)) return res.status(400).json({ error: 'Ungültige E-Mail-Adresse' });
      for (const f of ['telefon', 'adresse']) {
        // Adresse darf mehrzeilig sein, sonst keine Steuerzeichen und keine spitzen Klammern
        if (b[f] !== undefined && b[f] !== null && (typeof b[f] !== 'string' || b[f].length > 300 || /[\u0000-\u0009\u000B\u000C\u000E-\u001F\u007F<>]/.test(b[f]) || (f === 'telefon' && /[\r\n]/.test(b[f])))) return res.status(400).json({ error: `Ungültiger Wert: ${f}` });
      }
    }
    const email = (req.user.email || '').toLowerCase();
    const name = await wohnungsAbgleichName(req);
    const own = await pool.query(
      `SELECT wk.id, wk.name, wk.email, wk.telefon, wk.person_id, wk.wohnung_id FROM wohnungen_kontakte wk
        WHERE wk.id = $1 AND wk.archiviert_am IS NULL AND (($2 <> '' AND LOWER(wk.email) = $2) OR ${kontaktNameTreffer('wk.', '$3')})`,
      [req.params.id, email, name]
    );
    if (own.rows.length === 0) return res.status(403).json({ error: 'Du kannst nur deine eigenen Kontaktdaten bearbeiten' });
    const cur = own.rows[0];

    const { email: newEmail, telefon, adresse } = req.body;
    if (newEmail && newEmail.toLowerCase() !== email && newEmail.toLowerCase() !== (cur.email || '').toLowerCase()) {
      // Konfliktcheck nur gegen andere Personen, nicht gegen Family-Sharing
      const conflict = await pool.query(
        `SELECT k.id FROM wohnungen_kontakte k
          WHERE LOWER(k.email) = $1 AND k.id != $2
            AND (k.person_id IS NULL OR k.person_id != $3)`,
        [newEmail.toLowerCase(), req.params.id, cur.person_id || -1]
      );
      if (conflict.rows.length > 0) return res.status(400).json({ error: 'Email wird bereits von einer anderen Person verwendet' });
    }
    // R3-S1b: neue E-Mail/Nummer darf keinem Konto und keiner anderen Person gehoeren.
    {
      const neueMail = newEmail && newEmail.toLowerCase() !== (cur.email || '').toLowerCase() ? newEmail : null;
      const neueNr = telefon && !telefonGleich(telefon, cur.telefon) ? telefon : null;
      if (neueMail || neueNr) {
        const eigene = [...(await meinePersonenIds(pool, email)), ...(cur.person_id ? [cur.person_id] : [])];
        const grund = await fremdeKennung(pool, { email: neueMail, telefon: neueNr, eigeneIds: eigene, ichEmail: email });
        if (grund) return res.status(409).json({ error: grund });
      }
    }

    if (cur.person_id) {
      // Sauberer Pfad: Person aktualisieren → Trigger propagiert auf alle Wohnungen
      const updates = [];
      const params = [];
      if (newEmail !== undefined) { params.push(newEmail || null); updates.push(`email = $${params.length}`); }
      if (telefon !== undefined)  { params.push(normalizePhone(telefon));  updates.push(`telefon = $${params.length}`); }
      if (adresse !== undefined)  { params.push(adresse || null);  updates.push(`adresse = $${params.length}`); }
      if (updates.length > 0) {
        params.push(cur.person_id);
        await pool.query(`UPDATE personen SET ${updates.join(', ')}, updated_at = NOW() WHERE id = $${params.length}`, params);
      }
    } else {
      // Legacy: keine person_id → direkt Kontakt aktualisieren
      await pool.query(
        `UPDATE wohnungen_kontakte SET email = COALESCE($1, email), telefon = COALESCE($2, telefon), adresse = COALESCE($3, adresse)
          WHERE id = $4`,
        [newEmail || null, normalizePhone(telefon), adresse || null, req.params.id]
      );
    }
    const r = await pool.query(`SELECT id, name, email, telefon, adresse, wohnung_id, person_id FROM wohnungen_kontakte WHERE id = $1`, [req.params.id]);
    res.json(r.rows[0]);
    // Verwaltung informieren — pro betroffenem STWEG einmal
    try {
      const wRes = cur.person_id
        ? await pool.query(
            `SELECT DISTINCT w.stweg, w.bezeichnung FROM wohnungen_kontakte k JOIN wohnungen w ON w.id = k.wohnung_id
              WHERE k.person_id = $1 AND k.archiviert_am IS NULL`, [cur.person_id])
        : await pool.query(`SELECT stweg, bezeichnung FROM wohnungen WHERE id = $1`, [cur.wohnung_id]);
      const changes = [];
      if (newEmail !== undefined) changes.push('E-Mail → ' + (newEmail || '∅'));
      if (telefon !== undefined) changes.push('Tel → ' + (telefon || '∅'));
      if (adresse !== undefined) changes.push('Adresse → ' + String(adresse || '∅').slice(0, 80));
      if (changes.length > 0) {
        const where = wRes.rows.length === 1
          ? wRes.rows[0].bezeichnung
          : `${wRes.rows.length} Wohnungen der Person`;
        for (const row of wRes.rows) {
          recordObjektChange(row.stweg, `${cur.name} (${where}) hat Kontaktdaten aktualisiert: ${changes.join(', ')}`, req.user.email).catch(() => {});
        }
      }
    } catch {}
  } catch (err) {
    console.error('[me/kontakt] error:', err.message);
    res.status(500).json({ error: 'Fehler' });
  }
});

// GET /api/me/wohnung/:id — full apartment with kontakte (like /api/wohnungen/:stweg/:id)
app.get('/api/me/wohnung/:id', authMiddleware, async (req, res) => {
  try {
    const email = (req.user.email || '').toLowerCase();
    const name = await wohnungsAbgleichName(req);
    const own = await pool.query(
      `SELECT w.* FROM wohnungen w JOIN wohnungen_kontakte k ON k.wohnung_id = w.id
       WHERE w.id = $1 AND k.archiviert_am IS NULL AND (($2 <> '' AND LOWER(k.email) = $2) OR ${kontaktNameTreffer('k.', '$3')}) LIMIT 1`,
      [req.params.id, email, name]
    );
    if (own.rows.length === 0) return res.status(403).json({ error: 'Du kannst nur deine eigenen Wohnungen sehen' });
    const w = own.rows[0];
    // Nur aktive (und vorgemerkte) Kontakte wie in der Objektverwaltung: profil.html sendet die
    // Liste beim Speichern zurueck, archivierte Eintraege kaemen sonst wieder als aktiv zurueck.
    const k = await pool.query("SELECT * FROM wohnungen_kontakte WHERE wohnung_id = $1 AND archiviert_am IS NULL ORDER BY rolle, sort_order, id", [w.id]);
    w.kontakte = k.rows;
    res.json(w);
  } catch (err) {
    res.status(500).json({ error: 'Fehler' });
  }
});

// R2-S1a: Nach saveKontakte im Self-Service (person_sync ist dort 'on'):
//  1. Ein Kontakt darf nur mit einer Person verknuepft werden, die er schon hatte, die
//     eben neu angelegt wurde oder die der Anfragende selbst ist. Alles andere (bestehende
//     fremde Person per Name/E-Mail gefunden) wird wieder geloest.
//  2. Aenderungen an Name/E-Mail/Telefon/Adresse eines bestehend verknuepften Kontakts
//     gehen wie bisher an die Person — ausser die Person haengt an weiteren Wohnungen
//     oder hat ein eigenes Konto (dann pflegt sie das selbst bzw. die Verwaltung).
// Pruefung auf der tatsaechlich gespeicherten Zeile, damit Normalisierung (Telefon,
// Platzhalter-Adressen) keine Fehlalarme ausloest.
async function meWohnungPersonenAbgleichen(client, wohnungId, bisherWerte, ichEmail) {
  const nachher = (await client.query(
    `SELECT k.id, k.person_id, k.name, k.email, k.telefon, k.adresse,
            (p.created_at >= NOW()) AS person_neu, LOWER(COALESCE(p.email, '')) AS person_email
       FROM wohnungen_kontakte k LEFT JOIN personen p ON p.id = k.person_id
      WHERE k.wohnung_id = $1 AND k.archiviert_am IS NULL`, [wohnungId])).rows;
  const istIch = (mail) => !!ichEmail && String(mail || '').toLowerCase() === ichEmail;
  const meineIds = await meinePersonenIds(client, ichEmail);
  // In diesem Speichern neu angelegte Personen zaehlen nicht als "bisher eigene" (R4b-S1d)
  const neuIds = new Set(nachher.filter(r => r.person_neu && r.person_id).map(r => r.person_id));
  // R3-S1d: Personen, die schon an einem aktiven Kontakt DIESER Wohnung hingen (Miteigentuemer,
  // Mieter). Kommt ein solcher Kontakt als neue Zeile zurueck (Frontend ohne id, Zeile ersetzt),
  // bleibt die Verknuepfung — eine fremde Person kommt so nicht herein.
  const bisherPersonen = new Map();
  for (const r of bisherWerte.values()) if (r.person_id && !bisherPersonen.has(r.person_id)) bisherPersonen.set(r.person_id, r);
  for (const n of nachher) {
    let alt = bisherWerte.get(n.id);
    const altPid = alt ? alt.person_id : null;
    if (n.person_id && n.person_id !== altPid) {
      if (!alt && bisherPersonen.has(n.person_id)) {
        alt = bisherPersonen.get(n.person_id); // weiter unten wie ein bestehender Kontakt behandeln
      } else {
        if (n.person_neu) {
          // R4b-S1d: Neue Karte mit der EIGENEN E-Mail (aber anderem Namen) hat eine zweite
          // Person mit der eigenen Kennung angelegt -> an die bestehende eigene Person haengen.
          const meineAlt = meineIds.filter(id => !neuIds.has(id)).sort((x, y) => x - y);
          if (istIch(n.email) && meineAlt.length) {
            await client.query('UPDATE wohnungen_kontakte SET person_id = $1 WHERE person_id = $2 AND wohnung_id = $3', [meineAlt[0], n.person_id, wohnungId]);
            await client.query('DELETE FROM personen WHERE id = $1 AND created_at >= NOW()', [n.person_id]);
            neuIds.delete(n.person_id);
            continue;
          }
          // R3-S1b: Die neue Person traegt E-Mail/Telefon, die der Eigentuemer eingegeben hat.
          // Gehoeren sie einem Konto oder einer anderen Person, die neue Person wieder entfernen
          // (Kontakt bleibt ohne Verknuepfung gespeichert) — sonst zwei Personen mit derselben
          // Kennung, und Zuordnungen per E-Mail/Nummer treffen u. U. die falsche.
          const grund = await fremdeKennung(client, { email: n.email, telefon: n.telefon, eigeneIds: [n.person_id, ...meineIds], ichEmail });
          if (grund) {
            console.warn(`[me/wohnung] Wohnung ${wohnungId}: neue Person ${n.person_id} nicht angelegt (fremde Kennung)`);
            await client.query('UPDATE wohnungen_kontakte SET person_id = NULL WHERE person_id = $1 AND wohnung_id = $2', [n.person_id, wohnungId]);
            await client.query('DELETE FROM personen WHERE id = $1 AND created_at >= NOW()', [n.person_id]);
          }
        } else if (!istIch(n.person_email)) {
          await client.query('UPDATE wohnungen_kontakte SET person_id = $1 WHERE id = $2', [altPid, n.id]);
        }
        continue; // neue Verknuepfung: Werte stammen aus der Anlage, nichts weiterzugeben
      }
    }
    if (!alt || !n.person_id) continue;
    if (n.name === alt.name && n.email === alt.email && n.telefon === alt.telefon && n.adresse === alt.adresse) continue;
    const eigenerKontakt = istIch(alt.email) || istIch(n.person_email) || meineIds.includes(n.person_id);
    if (!eigenerKontakt) {
      const schutz = await client.query(
        `SELECT EXISTS (SELECT 1 FROM wohnungen_kontakte WHERE person_id = $1 AND wohnung_id <> $2 AND archiviert_am IS NULL) AS geteilt,
                EXISTS (SELECT 1 FROM users u JOIN personen p ON p.id = $1
                         WHERE u.active = true AND u.email <> '' AND LOWER(u.email) IN (LOWER(COALESCE(p.email, '')), LOWER(COALESCE($3, '')))) AS konto`,
        [n.person_id, wohnungId, alt.email]);
      if (schutz.rows[0]?.geteilt || schutz.rows[0]?.konto) {
        const e = new Error(`Die Kontaktdaten von «${String(alt.name || alt.email || '').slice(0, 80)}» gehören zu einer Person mit eigenem Konto oder weiteren Wohnungen. Name, E-Mail, Telefon und Adresse ändert die Person selbst im Profil oder die Verwaltung.`);
        e.status = 409; throw e;
      }
    }
    // Eine Adresse oder Nummer, die zu einem fremden Konto oder einer anderen Person gehoert,
    // nicht in eine Person schreiben (sonst gilt die Person in Zuordnungen als diese) (R3-S1b).
    {
      const neueMail = n.email && String(n.email).toLowerCase() !== String(alt.email || '').toLowerCase() ? n.email : null;
      const neueNr = n.telefon && !telefonGleich(n.telefon, alt.telefon) ? n.telefon : null;
      if (neueMail || neueNr) {
        const grund = await fremdeKennung(client, { email: neueMail, telefon: neueNr, eigeneIds: [n.person_id, ...(eigenerKontakt ? meineIds : [])], ichEmail });
        if (grund) { const e = new Error(grund); e.status = 409; throw e; }
      }
    }
    // Wie der Trigger kontakte_propagate_to_person (der hier wegen person_sync schweigt).
    // R3-S5a: Den Namen der EIGENEN Person nicht ueberschreiben — personen.name ist u. a. der
    // Name in Vollmacht-Signaturen; den aendert die Verwaltung (bzw. kommt aus dem Konto).
    await client.query(
      `UPDATE personen SET name = COALESCE($1, name), email = $2, telefon = $3, adresse = $4, updated_at = NOW() WHERE id = $5`,
      [eigenerKontakt ? null : n.name, n.email, n.telefon, n.adresse, n.person_id]);
  }
}

// PUT /api/me/wohnung/:id — full update of own apartment (all fields + kontakte)
// Same shape as PUT /api/wohnungen/:stweg/:id but ownership-checked instead of permission-checked
app.put('/api/me/wohnung/:id', authMiddleware, async (req, res) => {
  const client = await pool.connect();
  try {
    const email = (req.user.email || '').toLowerCase();
    const name = await wohnungsAbgleichName(req);
    // Ganze Wohnung (Wertquote, Kontaktliste) aendern nur Eigentuemer/Verwalter —
    // Mieter pflegen ihre eigenen Daten ueber /api/me/kontakt.
    const own = await client.query(
      `SELECT w.id, w.stweg, w.typ, w.bezeichnung, w.besonderheiten, w.notizen FROM wohnungen w JOIN wohnungen_kontakte k ON k.wohnung_id = w.id
       WHERE w.id = $1 AND k.archiviert_am IS NULL AND k.rolle IN ('eigentuemer','verwalter')
         AND (($2 <> '' AND LOWER(k.email) = $2) OR ${kontaktNameTreffer('k.', '$3')}) LIMIT 1`,
      [req.params.id, email, name]
    );
    if (own.rows.length === 0) return res.status(403).json({ error: 'Nur Eigentümer oder Verwalter dieser Wohnung können sie bearbeiten' });
    const stweg = own.rows[0].stweg;
    const b = req.body || {};
    // typ/bezeichnung/Kontakte erscheinen in Objektverwaltung und STWEG-Seiten ->
    // typ nur aus der bekannten Liste (oder unveraendert), Texte ohne HTML-Zeichen.
    const WOHNUNG_TYPEN = ['Wohnung', 'Hobbyraum', 'Tiefgarage-Platz', 'Parkplatz'];
    if (b.typ != null && b.typ !== '' && b.typ !== own.rows[0].typ && !WOHNUNG_TYPEN.includes(b.typ)) return res.status(400).json({ error: 'Ungültiger Typ' });
    if (b.bezeichnung != null && b.bezeichnung !== own.rows[0].bezeichnung
        && (typeof b.bezeichnung !== 'string' || b.bezeichnung.length > 100 || /[<>"'&]/.test(b.bezeichnung) || hatSteuerzeichen(b.bezeichnung))) {
      return res.status(400).json({ error: 'Bezeichnung enthält unzulässige Zeichen' });
    }
    // Freitexte erscheinen in Objektverwaltung/STWEG-Seiten: keine HTML-Zeichen, keine
    // Steuerzeichen (Zeilenumbruch/Tab in Notizen erlaubt). Unveraenderte Altwerte bleiben speicherbar.
    for (const f of ['besonderheiten', 'notizen']) {
      const v = b[f];
      if (v == null || v === '' || v === own.rows[0][f]) continue;
      if (typeof v !== 'string' || v.length > 5000 || /[<>]/.test(v) || /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/.test(v)) {
        return res.status(400).json({ error: `Ungültiger Wert: ${f}` });
      }
    }
    // Wertquote: nur ganze Zahlen (sie fliesst in Abrechnungen und wird in Seiten angezeigt).
    for (const f of ['wertquote_zaehler', 'wertquote_nenner']) {
      const v = b[f];
      if (v == null || v === '') continue;
      if (!Number.isInteger(v) || v < 1 || v > 1000000) return res.status(400).json({ error: 'Wertquote muss eine ganze Zahl sein' });
    }
    // person_id nie aus der Anfrage: bestehende Kontakte behalten ihre Verknuepfung,
    // neue bekommt saveKontakte per find/create (vorher liess sich eine fremde Person anhaengen).
    // Nur aktive Kontakte: archivierte Zeilen geben keine Verknuepfung weiter (R3-S1d).
    const bisherZeilen = (await client.query('SELECT id, person_id, name, email, telefon, adresse, rolle FROM wohnungen_kontakte WHERE wohnung_id = $1 AND archiviert_am IS NULL', [req.params.id])).rows;
    const bisher = new Map(bisherZeilen.map(r => [r.id, r.person_id]));
    const bisherWerte = new Map(bisherZeilen.map(r => [r.id, r]));
    for (const k of (Array.isArray(b.kontakte) ? b.kontakte : [])) {
      if (!k || typeof k !== 'object') return res.status(400).json({ error: 'Ungültiger Kontakt' });
      // Unveraenderte Altwerte nicht neu pruefen, sonst blockiert ein alter Eintrag das Speichern
      const alt = bisherWerte.get(Number(k.id)) || {};
      if (k.email != null && k.email !== '' && k.email !== alt.email && !emailFormatOk(k.email)) return res.status(400).json({ error: 'Ungültige E-Mail-Adresse bei einem Kontakt' });
      for (const f of ['name', 'telefon', 'adresse', 'rolle']) {
        if (k[f] != null && k[f] !== alt[f] && (typeof k[f] !== 'string' || k[f].length > 300 || /[<>]/.test(k[f]) || hatSteuerzeichen(k[f]))) return res.status(400).json({ error: `Ungültiger Wert bei einem Kontakt: ${f}` });
      }
      // R4b-S1c: unbekannte Rolle nicht stillschweigend zu 'eigentuemer' machen (gaebe
      // Bewohner/Sonstigen Eigentuemer-Rechte). Fehlt sie, bleibt die bisherige Rolle.
      if (k.rolle == null || k.rolle === '') { if (alt.rolle) k.rolle = alt.rolle; }
      else if (!['eigentuemer', 'mieter', 'verwalter', 'bewohner', 'sonstige'].includes(k.rolle) && k.rolle !== alt.rolle) return res.status(400).json({ error: 'Ungültige Rolle bei einem Kontakt' });
      if (k.id && bisher.has(Number(k.id))) k.person_id = bisher.get(Number(k.id)); else delete k.person_id;
    }
    await client.query('BEGIN');
    // R2-S1a: Waehrend des Speicherns nichts automatisch in personen zurueckschreiben
    // (Trigger kontakte_propagate_to_person prueft dieses Setting). Sonst liess sich ein
    // neuer Kontakt per Name an eine fremde Person haengen und deren E-Mail/Telefon
    // im zweiten Schritt auf eigene Werte umschreiben (= fremde Identitaet uebernehmen).
    // Die erlaubte Weitergabe macht unten personenAbgleichen() von Hand.
    await client.query("SELECT set_config('rosenweg.person_sync', 'on', true)");
    const result = await client.query(
      `UPDATE wohnungen SET bezeichnung=COALESCE($1,bezeichnung), stockwerk=$2, zimmer=$3, flaeche_m2=$4,
        typ=COALESCE($5,typ), besonderheiten=$6, bewohnt_von=COALESCE($7,bewohnt_von),
        waschkueche_berechtigt=COALESCE($8,waschkueche_berechtigt), notizen=$9,
        wertquote_zaehler=$10, wertquote_nenner=$11, updated_at=NOW()
       WHERE id=$12 RETURNING *`,
      [b.bezeichnung, b.stockwerk, b.zimmer, b.flaeche_m2, b.typ || 'Wohnung', b.besonderheiten,
       b.bewohnt_von || 'eigentuemer', b.waschkueche_berechtigt !== false, b.notizen,
       b.wertquote_zaehler || null, b.wertquote_nenner || null, req.params.id]
    );
    await saveKontakte(client, result.rows[0].id, b.kontakte, stweg);
    await meWohnungPersonenAbgleichen(client, result.rows[0].id, bisherWerte, email);
    await client.query('COMMIT');
    const w = await loadWohnungMitKontakte(result.rows[0].id);
    res.json(w);
    recordObjektChange(stweg, `Eigentümer-Self-Service: Wohnung "${w.bezeichnung}" aktualisiert`, req.user.email).catch(() => {});
  } catch (err) {
    await client.query('ROLLBACK').catch(()=>{});
    console.error('[me/wohnung PUT] error:', err.message);
    if (err.status === 400 || err.status === 409) return res.status(err.status).json({ error: err.message });
    res.status(500).json({ error: 'Fehler' });
  } finally {
    client.release();
  }
});

// Change password (sets in both Authentik and AD)
// Kein Fallback-Geheimnis im Code: ohne AD_PASSWORD_API_SECRET wird das AD nicht
// mitgesetzt (Authentik schon), die Admin-Funktionen melden es.
// Passwort-API auf dc1: lib/adpasswort.js (AD_PASSWORD_API_URL, AD_PASSWORD_API_SECRET).
const adPasswort = require('./lib/adpasswort');
if (!adPasswort.eingerichtet()) console.warn('[ad-password] AD_PASSWORD_API_SECRET fehlt — Passwoerter werden nicht ins AD uebernommen');

// Passwortwechsel nur aus einer frischen Anmeldung mit dem Rosenweg-Konto: ein
// gestohlenes Sitzungstoken (oder eine OTP-Sitzung) allein reicht nicht, um das
// Konto zu uebernehmen. Das alte Passwort laesst sich nicht verlangen — viele Konten
// melden sich per Passkey/Einladung an und kennen keins.
//
// Frisch (lib/stufen.js, passwortWechselErlaubt): Website-Sitzung mit id_token oder
// Access-Token der Rosenweg-Apps, deren auth_time hoechstens STUFE_FRISCH_MIN (15)
// Minuten alt ist. Die Apps holen das mit prompt=login/max_age=0 (rosenweg_basis:
// 403 reauth -> bestaetigen()), die Website mit reauth=1. Bisher ging es nur mit der
// Website-Sitzung; App-Tokens bekamen immer 403. Karte, QR, Anlage und PAT sperrt
// PAT_GESPERRT schon in authMiddleware (unveraendert).
app.post('/api/change-password', authMiddleware, async (req, res) => {
  const new_password = req.body?.new_password;
  if (!new_password || typeof new_password !== 'string') {
    return res.status(400).json({ error: 'Neues Passwort erforderlich' });
  }
  if (new_password.length < 8) {
    return res.status(400).json({ error: 'Neues Passwort muss mindestens 8 Zeichen haben' });
  }
  if (new_password.length > 256) {
    return res.status(400).json({ error: 'Neues Passwort ist zu lang' });
  }
  const userId = req.user.user_id || req.user.id;
  const sitzungsToken = (req.headers.authorization || '').replace(/^Bearer /, '');
  if (!passwortWechselErlaubt(req.auth)) {
    return res.status(403).json({
      error: `Bitte zur Bestätigung neu anmelden und das Passwort danach innert ${STUFE_FRISCH_MIN} Minuten ändern.`,
      reauth: true, fehler: 'frisch',
    });
  }
  // Limit erst nach der Frische-Pruefung: sonst verbrauchten die 403-Runden (Seite
  // fragt, wird zur Neuanmeldung geschickt) die Versuche und sperrten den Wechsel (R2-S1f).
  if (!rateLimitGuard('change-password', userId || req.user.email, 5, 60 * 60 * 1000).ok) {
    return res.status(429).json({ error: 'Zu viele Versuche. Bitte später erneut versuchen.' });
  }

  const email = req.user.email;
  console.log(`[change-password] Request from user: ${email}`);

  // Step 1: Find user in Authentik and set new password
  let akUsername;
  try {
    const userSearch = await authentikAPI('GET', `/core/users/?search=${encodeURIComponent(email)}`);
    const akUser = (userSearch.results || []).find(u => u.email?.toLowerCase() === email.toLowerCase());
    if (!akUser) {
      console.error(`[change-password] User not found in Authentik: ${email}`);
      return res.status(404).json({ error: 'Benutzer nicht gefunden' });
    }
    akUsername = akUser.username;
    await authentikAPI('POST', `/core/users/${akUser.pk}/set_password/`, {
      password: new_password,
    });
    console.log(`[change-password] Authentik password set for ${akUsername}`);
  } catch (err) {
    console.error('Authentik password change error:', err.message);
    return res.status(500).json({ error: 'Passwort konnte in Authentik nicht geändert werden' });
  }

  // Alle anderen Sitzungen des Kontos beenden (wer das alte Passwort/Token hatte, ist draussen)
  try {
    const weg = await pool.query('DELETE FROM sessions WHERE user_id = $1 AND token <> $2 RETURNING token', [userId, sitzungsToken]);
    for (const r of weg.rows) tokenCache.delete(r.token);
  } catch (err) {
    console.error('[change-password] Sitzungen beenden fehlgeschlagen:', err.message);
  }

  // Step 2: Set new password in AD
  if (!adPasswort.eingerichtet()) {
    console.error('[change-password] AD_PASSWORD_API_SECRET fehlt — AD-Passwort nicht gesetzt');
    return res.json({ status: 'ok', message: 'Passwort wurde geändert (Windows-Anmeldung wird nicht mitgeführt)' });
  }
  // Scheitert es, bleibt der Wechsel trotzdem gueltig: Authentik ist schon gesetzt.
  const ad = await adPasswort.setzen(akUsername, new_password);
  if (ad.ok) console.log(`[change-password] AD password set for ${akUsername}`);
  else console.error('AD password change failed:', ad.fehler);

  res.json({ status: 'ok', message: 'Passwort wurde geändert' });
});

// Update own profile
app.put('/api/auth/profile', authMiddleware, async (req, res) => {
  const userId = req.user.user_id || req.user.id;
  const { name, wohnung, phone, strasse, plz, ort } = req.body || {};
  let { stweg } = req.body || {};
  // Name/Wohnung erscheinen in Admin-Seiten (Waschkueche u. a.) -> keine HTML-/Steuerzeichen.
  const textOk = (v, max, verbot) => v == null || v === '' || (typeof v === 'string' && v.length <= max && !hatSteuerzeichen(v) && !verbot.test(v));
  if (!textOk(name, 200, /[<>]/)) return res.status(400).json({ error: 'Name enthält unzulässige Zeichen' });
  if (!textOk(wohnung, 100, /[<>"'&]/)) return res.status(400).json({ error: 'Wohnung enthält unzulässige Zeichen' });
  for (const [f, v] of Object.entries({ phone, strasse, plz, ort })) {
    if (!textOk(v, 200, /[<>]/)) return res.status(400).json({ error: `Ungültiger Wert: ${f}` });
  }
  try {
    // STWEG nur eine, der die Person per Gruppe angehoert (oder unveraendert/leer);
    // sie steuert u. a., an welche Verwaltung Selbstmutationen gemeldet werden.
    if (stweg != null && stweg !== '') {
      const nr = parseStweg(stweg);
      const cur = (await pool.query('SELECT stweg FROM users WHERE id = $1', [userId])).rows[0];
      if (!nr) return res.status(400).json({ error: 'Ungültige STWEG' });
      if (String(cur?.stweg ?? '') !== String(nr) && !req.user.isAdmin && !getUserStwegs(req.user.groups || []).has(nr)) {
        return res.status(403).json({ error: 'Diese STWEG passt nicht zu deinen Gruppen' });
      }
      stweg = nr;
    }
    const result = await pool.query(
      `UPDATE users SET name = COALESCE($1, name), wohnung = $2, stweg = $3,
       phone = $4, strasse = $5, plz = $6, ort = $7, updated_at = NOW(),
       name_selbst_geaendert_am = CASE WHEN $1 IS NOT NULL AND $1 IS DISTINCT FROM name THEN NOW() ELSE name_selbst_geaendert_am END
       WHERE id = $8
       RETURNING id, email, name, wohnung, stweg, role, phone, strasse, plz, ort`,
      [name, wohnung || null, stweg || null, phone || null, strasse || null, plz || null, ort || null, userId]
    );
    res.json({ user: result.rows[0] });
  } catch (err) {
    console.error('Profile update error:', err);
    res.status(500).json({ error: 'Profil konnte nicht gespeichert werden' });
  }
});

// GET /api/me/person-data — liefert das personen-Datenset des eingeloggten Users
// (zusätzliche Telefonnummern + Email-Aliasse, die nicht in users gepflegt sind)
app.get('/api/me/person-data', authMiddleware, async (req, res) => {
  const email = (req.user.email || '').toLowerCase();
  if (!email) return res.json({ found: false, telefone: [], emails: [] });
  try {
    const r = await pool.query(
      `SELECT id, name, email, telefon, mobile, telefone, emails, whatsapp_opt_in
         FROM personen
        WHERE LOWER(email) = $1
           OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(emails,'[]'::jsonb)) e WHERE LOWER(e) = $1)
        LIMIT 1`,
      [email],
    );
    if (!r.rows[0]) return res.json({ found: false, telefone: [], emails: [] });
    const p = r.rows[0];
    res.json({
      found: true,
      person_id: p.id,
      person_name: p.name,
      person_email: p.email,
      primary_phone: p.mobile || p.telefon || null,
      telefone: Array.isArray(p.telefone) ? p.telefone : [],
      emails: Array.isArray(p.emails) ? p.emails : [],
      whatsapp_opt_in: !!p.whatsapp_opt_in,
    });
  } catch (err) {
    console.error('[me/person-data] error:', err.message);
    res.status(500).json({ error: 'Fehler' });
  }
});

// PUT /api/me/phones — Zusatznummern (telefone JSONB) verwalten
// Body: { telefone: [{ typ, label?, nummer, whatsapp? }, ...] }
app.put('/api/me/phones', authMiddleware, async (req, res) => {
  const email = (req.user.email || '').toLowerCase();
  if (!email) return res.status(400).json({ error: 'Keine E-Mail' });
  const raw = Array.isArray(req.body?.telefone) ? req.body.telefone : [];
  // Validierung + Normalisierung
  const cleaned = [];
  for (const t of raw.slice(0, 10)) {
    const nummer = String(t?.nummer || '').trim();
    if (!nummer) continue;
    cleaned.push({
      typ: String(t?.typ || 'sonstige').slice(0, 30),
      label: t?.label ? String(t.label).slice(0, 50) : undefined,
      nummer,
      whatsapp: !!t?.whatsapp,
    });
  }
  try {
    // Nummern sind unbestaetigt, werden aber fuer Zuordnung (WhatsApp/Anruf -> Person)
    // genutzt (S1-2-1): eine NEUE Nummer, die schon bei einer anderen Person steht, ablehnen.
    const meine = await pool.query(
      `SELECT id, telefone FROM personen WHERE LOWER(email) = $1
          OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(emails,'[]'::jsonb)) e WHERE LOWER(e) = $1)`, [email]);
    const meineIds = meine.rows.map(r => r.id);
    const ohneLeer = (v) => String(v || '').replace(/\s/g, '');
    const bisher = new Set(meine.rows.flatMap(r => (Array.isArray(r.telefone) ? r.telefone : []).map(t => ohneLeer(t?.nummer))));
    for (const t of cleaned) {
      if (bisher.has(ohneLeer(t.nummer))) continue;
      const varianten = [...new Set([ohneLeer(t.nummer), ohneLeer(normalizePhone(t.nummer))].filter(Boolean))];
      const fremd = await pool.query(
        `SELECT 1 FROM personen
          WHERE NOT (id = ANY($2::int[]))
            AND (REPLACE(COALESCE(telefon,''), ' ', '') = ANY($1::text[])
              OR REPLACE(COALESCE(mobile,''), ' ', '') = ANY($1::text[])
              OR EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(telefone, '[]'::jsonb)) x
                          WHERE REPLACE(COALESCE(x->>'nummer',''), ' ', '') = ANY($1::text[])))
          LIMIT 1`, [varianten, meineIds]);
      if (fremd.rows.length) return res.status(409).json({ error: `Die Nummer ${t.nummer.slice(0, 40)} ist bereits bei einer anderen Person hinterlegt. Bitte bei der Verwaltung melden.` });
    }
    const r = await pool.query(
      `UPDATE personen SET telefone = $1::jsonb, updated_at = NOW()
         WHERE LOWER(email) = $2
            OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(emails,'[]'::jsonb)) e WHERE LOWER(e) = $2)
      RETURNING id, telefone`,
      [JSON.stringify(cleaned), email],
    );
    if (!r.rows[0]) return res.status(404).json({ error: 'Kein personen-Eintrag für diese E-Mail' });
    res.json({ ok: true, telefone: r.rows[0].telefone });
  } catch (err) {
    console.error('[me/phones] error:', err.message);
    res.status(500).json({ error: 'Fehler beim Speichern' });
  }
});

// PUT /api/me/emails — Email-Aliasse verwalten (emails JSONB)
// Body: { emails: ["alias1@x.com", ...] }
app.put('/api/me/emails', authMiddleware, async (req, res) => {
  const email = (req.user.email || '').toLowerCase();
  if (!email) return res.status(400).json({ error: 'Keine E-Mail' });
  const raw = Array.isArray(req.body?.emails) ? req.body.emails : [];
  // Validierung: nur korrekt aussehende Emails behalten
  const emailRe = /^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)+$/;
  const cleaned = [];
  for (const e of raw.slice(0, 10)) {
    const s = String(e || '').trim().toLowerCase();
    if (!s || !emailRe.test(s)) continue;
    if (cleaned.includes(s)) continue;
    cleaned.push(s);
  }
  try {
    // Aliase sind unbestaetigt, zaehlen aber fuer Gruppen-/Broadcast-Aufloesung und
    // Zuordnung (S1-2-1): ein NEUER Alias, der Konto-E-Mail oder Adresse einer anderen
    // Person ist, wuerde deren Identitaet uebernehmen -> ablehnen.
    const meine = await pool.query(
      `SELECT id, emails FROM personen WHERE LOWER(email) = $1
          OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(emails,'[]'::jsonb)) e WHERE LOWER(e) = $1)`, [email]);
    const meineIds = meine.rows.map(r => r.id);
    const bisher = new Set(meine.rows.flatMap(r => (Array.isArray(r.emails) ? r.emails : []).map(e => String(e).toLowerCase())));
    const neu = cleaned.filter(a => a !== email && !bisher.has(a));
    if (neu.length) {
      const fremd = await pool.query(
        `SELECT a FROM unnest($1::text[]) a
          WHERE EXISTS (SELECT 1 FROM users u WHERE LOWER(u.email) = a)
             OR EXISTS (SELECT 1 FROM personen p WHERE NOT (p.id = ANY($2::int[]))
                          AND (LOWER(p.email) = a
                               OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(p.emails,'[]'::jsonb)) e WHERE LOWER(e) = a)))
          LIMIT 1`, [neu, meineIds]);
      if (fremd.rows.length) return res.status(409).json({ error: `Die Adresse ${fremd.rows[0].a} gehört bereits zu einem anderen Konto oder einer anderen Person.` });
    }
    const r = await pool.query(
      `UPDATE personen SET emails = $1::jsonb, updated_at = NOW()
         WHERE LOWER(email) = $2
            OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(emails,'[]'::jsonb)) e WHERE LOWER(e) = $2)
      RETURNING id, emails`,
      [JSON.stringify(cleaned), email],
    );
    if (!r.rows[0]) return res.status(404).json({ error: 'Kein personen-Eintrag für diese E-Mail' });
    res.json({ ok: true, emails: r.rows[0].emails });
  } catch (err) {
    console.error('[me/emails] error:', err.message);
    res.status(500).json({ error: 'Fehler beim Speichern' });
  }
});

// ─── Selbstmutation: eigene Stammdaten (Name/Adresse/Telefon) selbst aendern ──
// GET liefert den aktuellen Stand; POST speichert + meldet die Aenderung an die
// Verwaltung (recordObjektChange -> verwaltung_mail_queue, Technik-Freigabe).
// wohnung/stweg sind NICHT selbst-mutierbar (Eigentums-/Mietverhaeltnis -> Verwaltung).
app.get('/api/me/mutation', authMiddleware, async (req, res) => {
  try {
    const id = req.user.user_id || req.user.id;
    const r = await pool.query(
      'SELECT name, email, wohnung, stweg, phone, strasse, plz, ort FROM users WHERE id = $1', [id]);
    const u = r.rows[0] || {};
    const email = (req.user.email || '').toLowerCase();
    let telefone = [];
    if (email) {
      const pr = await pool.query('SELECT telefone FROM personen WHERE LOWER(email) = $1 LIMIT 1', [email]);
      telefone = Array.isArray(pr.rows[0]?.telefone) ? pr.rows[0].telefone : [];
    }
    res.json({ ...u, telefone });
  } catch (e) { console.error('[me/mutation GET]', e); res.status(500).json({ error: 'Fehler' }); }
});

app.post('/api/me/mutation', authMiddleware, async (req, res) => {
  try {
    const id = req.user.user_id || req.user.id;
    const b = req.body || {};
    const cur = (await pool.query('SELECT name, wohnung, stweg, phone, strasse, plz, ort FROM users WHERE id = $1', [id])).rows[0] || {};
    const f = {
      name: b.name != null ? String(b.name).trim().slice(0, 200) : (cur.name || ''),
      phone: b.phone != null ? (String(b.phone).trim().slice(0, 60) || null) : cur.phone,
      strasse: b.strasse != null ? (String(b.strasse).trim().slice(0, 200) || null) : cur.strasse,
      plz: b.plz != null ? (String(b.plz).trim().slice(0, 20) || null) : cur.plz,
      ort: b.ort != null ? (String(b.ort).trim().slice(0, 120) || null) : cur.ort,
    };
    if (!f.name) return res.status(400).json({ error: 'Name erforderlich' });
    // Gleiche Regel wie /api/auth/profile: keine HTML-/Steuerzeichen (Anzeige in Admin-Seiten)
    if (Object.values(f).some(v => v != null && (/[<>]/.test(v) || hatSteuerzeichen(v)))) return res.status(400).json({ error: 'Unzulässige Zeichen' });
    const labels = { name: 'Name', phone: 'Telefon', strasse: 'Strasse', plz: 'PLZ', ort: 'Ort' };
    const changes = [];
    for (const k of Object.keys(labels)) {
      const oldV = String(cur[k] || ''), newV = String(f[k] || '');
      if (oldV !== newV) changes.push(`${labels[k]}: "${oldV || '–'}" → "${newV || '–'}"`);
    }
    await pool.query(
      `UPDATE users SET name=$1, phone=$2, strasse=$3, plz=$4, ort=$5, updated_at=NOW(),
         name_selbst_geaendert_am = CASE WHEN $1 IS DISTINCT FROM name THEN NOW() ELSE name_selbst_geaendert_am END
       WHERE id=$6`,
      [f.name, f.phone, f.strasse, f.plz, f.ort, id]);
    if (changes.length) {
      const wohnLabel = cur.wohnung ? ` (Whg ${cur.wohnung})` : '';
      const line = `${f.name}${wohnLabel}: ${changes.join('; ')}`;
      recordObjektChange(cur.stweg, line, req.user.email).catch(() => {});
    }
    res.json({ ok: true, changed: changes });
  } catch (e) { console.error('[me/mutation POST]', e); res.status(500).json({ error: 'Fehler beim Speichern' }); }
});

// PUT /api/me/whatsapp-optin — Toggle WhatsApp-Opt-In am Personen-Datensatz
// Body: { enabled: bool }
// Liefert Status zurück: { ok, enabled, phone, reason? }
app.put('/api/me/whatsapp-optin', authMiddleware, async (req, res) => {
  const email = (req.user.email || '').toLowerCase();
  if (!email) return res.status(400).json({ error: 'Keine E-Mail' });
  const enabled = !!req.body?.enabled;
  try {
    const person = await pool.query(
      `SELECT id, name, telefon, mobile, telefone, whatsapp_opt_in
         FROM personen WHERE LOWER(email) = $1 LIMIT 1`,
      [email]
    );
    if (!person.rows[0]) {
      return res.status(404).json({
        error: 'Kein Personen-Eintrag für diese E-Mail gefunden',
        hint: 'Bitte zuerst Telefonnummer in der Objektverwaltung hinterlegen lassen.',
      });
    }
    const p = person.rows[0];
    // Pick a usable phone: mobile -> telefon -> telefone[0].nummer
    let phone = p.mobile || p.telefon || null;
    if (!phone && Array.isArray(p.telefone) && p.telefone.length > 0) {
      phone = p.telefone[0]?.nummer || null;
    }
    if (enabled && !phone) {
      return res.status(400).json({
        error: 'Keine Telefonnummer hinterlegt',
        hint: 'WhatsApp-Benachrichtigungen benötigen eine Telefonnummer im Profil.',
      });
    }
    await pool.query(
      `UPDATE personen SET whatsapp_opt_in = $1, updated_at = NOW() WHERE id = $2`,
      [enabled, p.id]
    );
    res.json({ ok: true, enabled, phone });
  } catch (err) {
    console.error('[whatsapp-optin] error:', err.message);
    res.status(500).json({ error: 'Fehler beim Speichern' });
  }
});

// WiFi info for authenticated users (PPSK from UniFi)
const UNIFI_API_KEY = process.env.UNIFI_API_KEY || ''; // aus /root/.env (env_file); KEIN hardcoded Fallback
const UNIFI_HOST = process.env.UNIFI_HOST || 'https://100.64.2.1';

app.get('/api/wifi', authMiddleware, async (req, res) => {
  try {
    // Get network configs (ID → name/vlan mapping)
    const netResp = await fetch(`${UNIFI_HOST}/proxy/network/api/s/default/rest/networkconf`, {
      headers: { 'X-API-Key': UNIFI_API_KEY },
      signal: AbortSignal.timeout(5000),
    });
    const nets = (await netResp.json()).data || [];
    const netMap = {};
    for (const n of nets) {
      netMap[n._id] = { name: n.name, vlan: n.vlan || null, subnet: n.ip_subnet || null };
    }

    // Get WLAN config with PPSKs
    const wlanResp = await fetch(`${UNIFI_HOST}/proxy/network/api/s/default/rest/wlanconf`, {
      headers: { 'X-API-Key': UNIFI_API_KEY },
      signal: AbortSignal.timeout(5000),
    });
    const wlans = (await wlanResp.json()).data || [];
    const rosenweg = wlans.find(w => w.name === 'Rosenweg' && w.enabled);
    if (!rosenweg) return res.status(404).json({ error: 'WLAN nicht gefunden' });

    // Haus-WLAN nur fuer Personen, die dort WOHNEN, und erst ab dem Einzugsdatum
    // (Entscheid Stefan 28.11.2026, lib/isp-zugang.js). Massgebend sind allein die
    // Wohnungs-Kontakte mit Rolle und gueltig_ab: nicht die Authentik-Gruppen (die
    // bleiben nach dem Auszug noch bis zur Kontoloeschung) und nicht mehr die selbst
    // gepflegte Strasse (Befund R6). Nicht bewohnende Eigentuemer und Wohnungs-
    // Verwalter sehen kein Haus-WLAN. Wohnung oder Hobbyraum in einem Haus -> dessen
    // Clients-WLAN (Wohnung RW9 + Hobbyraum RW2 -> RW9 und RW2).
    const hausNummern = new Set();
    const userEmailForHaus = (req.user.email || '').toLowerCase();
    let userWohnungen = [];
    try {
      userWohnungen = await getUserVlanOptions(userEmailForHaus);
      for (const opt of userWohnungen) {
        if (opt.kind === 'wohnung' || opt.kind === 'hobbyraum') {
          const haus = ispZugang.hausAusVlan(opt.vlan);
          if (haus) hausNummern.add(haus);
        }
      }
    } catch {}

    // Find PPSKs for all user's houses (still nur falls vorhanden — nicht jedes
    // Haus muss eine eigene PPSK-Konfiguration haben).
    const userWlans = [];
    if (rosenweg.private_preshared_keys_enabled) {
      for (const hausNr of hausNummern) {
        const targetNet = `RW${hausNr}-Clients`;
        for (const ppsk of rosenweg.private_preshared_keys || []) {
          const net = netMap[ppsk.networkconf_id];
          if (net && net.name === targetNet) {
            userWlans.push({
              hausNr,
              password: ppsk.password,
              network: net.name,
              vlan: net.vlan,
              subnet: net.subnet,
              rolle: 'bewohner',
            });
            break;
          }
        }
      }

      // RK-Clients-WLAN nur für reine Parkplatz-User (kein wohnung/hobbyraum
      // bezogen). Wer auch eine Wohnung oder Hobbyraum hat, sieht stattdessen
      // sein normales Haus-WLAN — die brauchen RK-Clients nicht.
      const kinds = new Set(userWohnungen.map(o => o.kind));
      const showRk = kinds.has('parkplatz') && !kinds.has('wohnung') && !kinds.has('hobbyraum');
      if (showRk) {
        for (const ppsk of rosenweg.private_preshared_keys || []) {
          const net = netMap[ppsk.networkconf_id];
          if (net && net.name === 'RK-Clients') {
            userWlans.push({
              hausNr: null,
              isRkClients: true,
              password: ppsk.password,
              network: net.name,
              vlan: net.vlan,
              subnet: net.subnet,
              rolle: 'parkplatz',
            });
            break;
          }
        }
      }

      // Plus alle user-VLANs aus isp_vlan_requests wo der User Antragsteller
      // oder Mitnutzer ist UND with_wlan=true UND status=deployed.
      const email = (req.user.email || '').toLowerCase();
      const myVlans = await pool.query(`
        SELECT vlan_id, gewuenschter_name, subnet_v4, with_wlan, wlan_password,
               unifi_network_id, antragsteller_email,
               LOWER(antragsteller_email) = $1 AS is_owner
          FROM isp_vlan_requests
         WHERE status = 'deployed'
           AND with_wlan = true
           AND wlan_password IS NOT NULL
           AND (LOWER(antragsteller_email) = $1
                OR $1 = ANY(COALESCE(mitnutzer_emails, ARRAY[]::TEXT[])))
      `, [email]);
      for (const row of myVlans.rows) {
        const net = row.unifi_network_id ? netMap[row.unifi_network_id] : null;
        userWlans.push({
          hausNr: null,
          isUserVlan: true,
          password: row.wlan_password,
          network: net?.name || row.gewuenschter_name || `vlan-${row.vlan_id}`,
          vlan: row.vlan_id,
          subnet: row.subnet_v4,
          rolle: row.is_owner ? 'antragsteller' : 'mitnutzer',
          ownerEmail: row.is_owner ? null : row.antragsteller_email,
        });
      }
    }

    // Alle PPSKs (Haeuser und private Netze) nur fuer Technik/Praesident und nur auf
    // ausdrueckliche Anfrage (?alle=1, Knopf auf wlan.html) - jedes Ansehen steht im
    // Protokoll, auch mit der Karte (Befund R4, Regel "Karte wie Schluessel").
    const admin = ispIsAdmin(req);
    let allPpsks = null;
    if (admin && /^(1|ja|true)$/i.test(String(req.query.alle || ''))) {
      allPpsks = (rosenweg.private_preshared_keys || []).map(ppsk => {
        const net = netMap[ppsk.networkconf_id] || {};
        return { network: net.name, vlan: net.vlan, password: ppsk.password };
      });
      await ispAdminSichtProtokoll(req, 'wlan-passwoerter-angesehen', 'alle WLAN-Passwörter (PPSK)',
        `${allPpsks.length} Passwörter: ${allPpsks.map(p => p.network || '?').join(', ').slice(0, 1500)}`,
        'Internet (ISP): alle WLAN-Passwörter angesehen');
    }

    res.json({
      ssid: 'Rosenweg',
      wlans: userWlans,
      guest: { ssid: 'Rosenweg-Guest', password: null, security: 'open' },
      allPpsks,
      kann_alle_sehen: admin,
    });
  } catch (err) {
    console.error('WiFi info error:', err.message);
    res.status(500).json({ error: 'WiFi-Daten konnten nicht geladen werden' });
  }
});

// ─── TV7 (Init7 IPTV) ────────────────────────────────────────────────
//
// Architektur (Stand 2026-06-11):
//   Browser → /api/tv/channels       (API, Authentik-Session)
//   Browser → /api/tv/stream/<id>    (API, Authentik-Session)
//             ↓ pipe MPEG-TS
//          tv7-streamer (LXC 250, 100.64.9.23:3000)
//             ↓ spawn ffmpeg
//          api.tv.init7.net (HLS, AC-3 audio)
//
// Warum eigener LXC: ffmpeg-Transcode (AC-3 → AAC) ist CPU-intensiv und
// gehört nicht in den rosenweg_api-Container.
//
// udpxy für Multicast laeuft in LXC 109 (100.64.9.200:4022) — aktuell
// blockiert die UDM-Firewall den Init7-Multicast-Inflow, deshalb HLS-Pfad.
const tvEpg = require('./lib/tv-epg');
const TV7_PLAYLIST_URL = 'https://api.init7.net/tvchannels.m3u?rp=true';
const UDPXY_HOST = process.env.UDPXY_HOST || 'http://100.64.9.24:4022';
// gleiche Quelle wie /api/tv/playlist.m3u (dort wird UDPXY_BASE gelesen)
const UDPXY_BASE_URL = process.env.UDPXY_BASE || 'http://100.64.9.24:4022';
const TV7_STREAMER_URL = process.env.TV7_STREAMER_URL || 'http://100.64.9.23:3000';
// Public-Pfad den der Browser für den Stream anspricht. Default ist ein
// relativer Pfad — die nginx der ISP-Seite proxyt /tv-stream/* direkt zum
// LXC 250, kein API-Hop. Wenn ein voller URL gesetzt ist (z.B. via CF
// Tunnel auf tv.rosenweg9.ch), wird der genommen.
const TV7_PUBLIC_URL = process.env.TV7_PUBLIC_URL || '/tv-stream';
const TV7_HMAC_SECRET = process.env.TV7_HMAC_SECRET || '';
const TV7_TOKEN_TTL = 3600; // 1 hour

let tv7ChannelsCache = null;
let tv7CacheTime = 0;

// Multicast-only-Sender (kein HTTP-channel-id) bekommen eine stabile hex+bindestrich-
// ID aus der Gruppe (233.50.230.57 -> e9-32-e6-39) — passt durch die id-Regex und
// IDENTISCH zur Logik im tv7-streamer (mcastId), damit /stream/<id> dort aufgeht.
function mcastIdFromGroup(group) {
  return group.split('.').map(o => parseInt(o, 10).toString(16).padStart(2, '0')).join('-');
}

function parseTV7Playlist(text) {
  const out = [];
  const lines = (text || '').split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    if (!lines[i].startsWith('#EXTINF')) continue;
    const url = (lines[i + 1] || '').trim();
    if (!url || url.startsWith('#')) continue;
    out.push({
      logo: (lines[i].match(/tvg-logo="([^"]*)"/) || [])[1] || '',
      tvg: (lines[i].match(/tvg-name="([^"]*)"/) || [])[1] || '',
      group: (lines[i].match(/group-title="([^"]*)"/) || [])[1] || '',
      name: ((lines[i].match(/,\s*(.+)$/) || [])[1] || '').trim(),
      url,
    });
  }
  return out;
}

// Alle 242 Sender aus der Multicast-Liste, gemerged mit HTTP-channel-ids (fuer den
// H.264-Pfad). Spiegelt getChannels() im tv7-streamer (gleiche IDs).
async function fetchTV7Channels() {
  if (tv7ChannelsCache && Date.now() - tv7CacheTime < 3600000) return tv7ChannelsCache;
  const [httpResp, mcResp] = await Promise.all([
    fetch('https://api.init7.net/tvchannels.m3u?rp=true', { signal: AbortSignal.timeout(10000) }),
    fetch('https://api.init7.net/tvchannels.m3u', { signal: AbortSignal.timeout(10000) }),
  ]);
  const httpEntries = parseTV7Playlist(await httpResp.text());
  const mcEntries = parseTV7Playlist(await mcResp.text());
  const httpMap = {};
  for (const e of httpEntries) {
    const id = (e.url.match(/channel=([a-f0-9-]+)/i) || [])[1];
    if (id) httpMap[e.tvg] = id;
  }
  const channels = [];
  for (const e of mcEntries) {
    const u = e.url.match(/udp:\/\/@?([\d.]+):(\d+)/i);
    if (!u) continue;
    const httpId = httpMap[e.tvg] || null;
    channels.push({
      id: httpId || mcastIdFromGroup(u[1]),
      name: e.name || e.tvg || 'Unknown',
      logo: e.logo,
      group: e.group,
      hevc: true,
      h264: !!httpId,
      // additiv fuer die App Rosenweg TV: Schluessel fuers EPG und der Direktweg im Haus
      tvg: e.tvg || '',
      udpxy_url: `${UDPXY_BASE_URL}/udp/${u[1]}:${u[2]}`,
    });
  }
  tv7ChannelsCache = channels;
  tv7CacheTime = Date.now();
  return channels;
}

app.get('/api/tv/channels', authMiddleware, async (req, res) => {
  try {
    const channels = await fetchTV7Channels();
    res.json(channels);
  } catch (err) {
    console.error('TV7 channels error:', err.message);
    res.status(500).json({ error: 'TV7-Kanäle konnten nicht geladen werden' });
  }
});

// Browser holt sich hier nur den Token + die public Stream-URL — keine
// MPEG-TS-Bytes mehr durch die API. Player verbindet sich direkt mit dem
// LXC via CF Tunnel.
// Multicast-Playlist (alle Sender als udpxy-HTTP-URLs, cross-VLAN) fuer native
// Player. Wird hier (statt im Streamer) ausgeliefert, weil die ISP-nginx den
// Streamer im RK-Clients-VLAN nicht erreicht, die API ueber das Overlay aber schon.
// Kein Auth — sind nur udpxy-URLs, abspielbar nur im Hausnetz.
app.get('/api/tv/playlist.m3u', async (req, res) => {
  try {
    const udpxy = process.env.UDPXY_BASE || 'http://100.64.9.24:4022';
    const r = await fetch('https://api.init7.net/tvchannels.m3u', {
      signal: AbortSignal.timeout(8000),
    });
    if (!r.ok) throw new Error('init7 HTTP ' + r.status);
    let body = await r.text();
    // EPG-Referenz (Apps laden xmltv automatisch) + tvg-id (=tvg-name) fuers Mapping
    body = body.replace(/^#EXTM3U.*/m, '#EXTM3U url-tvg="https://tv.rosenweg4303.ch/epg.xml" x-tvg-url="https://tv.rosenweg4303.ch/epg.xml"');
    body = body.replace(/(#EXTINF:[^\n]*?)tvg-name="([^"]+)"/g, (m, pre, name) => m.includes('tvg-id=') ? m : `${pre}tvg-id="${name}" tvg-name="${name}"`);
    // Live-Kanaele: Dauer 0 -> -1 (sonst behandeln viele Player den Kanal als
    // 0-Sekunden-Clip und spielen ihn nicht, z.B. TiviMate).
    body = body.replace(/^#EXTINF:0([ ,])/gm, '#EXTINF:-1$1');
    // udp://@<gruppe>:<port> -> http://<udpxy>/udp/<gruppe>:<port>
    body = body.replace(/^udp:\/\/@?([\d.]+):(\d+).*$/gm, (_m, g, p) => `${udpxy}/udp/${g}:${p}`);
    res.set('Content-Type', 'audio/x-mpegurl; charset=utf-8');
    res.set('Cache-Control', 'public, max-age=1800');
    res.send(body);
  } catch (e) {
    res.status(502).json({ error: fehlerFuerClient(e, 'Senderliste nicht verfügbar') });
  }
});

// ─── TV7 EPG (XMLTV) ─────────────────────────────────────────────────
// Init7-EPG-API (api.tv.init7.net/api/epg/) ist zeitsortiert + paginiert.
// Wir holen nur den Zukunfts-Tail (now-3h .. Ende) und bauen XMLTV.
// channel id = canonical_name (= tvg-name in der Playlist). Cache 6h.
let _tv7EpgCache = null;
const TV7_EPG_TTL = 6 * 3600 * 1000;
function tv7XmlEsc(s) {
  return String(s == null ? '' : s).replace(/[<>&'"]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', "'": '&apos;', '"': '&quot;' }[c]));
}
function tv7XmltvTime(iso) {
  const d = new Date(iso); const p = n => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}${p(d.getUTCHours())}${p(d.getUTCMinutes())}${p(d.getUTCSeconds())} +0000`;
}
async function buildTV7Epg() {
  const BASE = 'https://api.tv.init7.net/api/epg/';
  const head = await (await fetch(`${BASE}?limit=1`, { signal: AbortSignal.timeout(15000) })).json();
  const total = head.count || 0;
  const minTs = Date.now() - 3 * 3600 * 1000; // ab 3h vor jetzt
  const LIMIT = 20000;
  let offset = Math.max(0, total - 90000); // Zukunfts-Tail (~letzte ~7 Tage)
  const channels = new Map();
  const programmes = [];
  const roh = [];   // fuer den JSON-Index (lib/tv-epg.js)
  while (offset < total) {
    const page = await (await fetch(`${BASE}?limit=${LIMIT}&offset=${offset}`, { signal: AbortSignal.timeout(30000) })).json();
    for (const r of (page.results || [])) {
      if (new Date(r.timeslot.lower).getTime() < minTs) continue;
      const ch = r.channel || {}; const id = ch.canonical_name;
      if (!id) continue;
      if (!channels.has(id)) channels.set(id, { name: ch.name || id, logo: ch.logo || '' });
      programmes.push({ id, start: r.timeslot.lower, stop: r.timeslot.upper, title: r.title, sub: r.sub_title, desc: r.desc });
      roh.push(r);
    }
    offset += LIMIT;
  }
  let xml = '<?xml version="1.0" encoding="UTF-8"?>\n<tv generator-info-name="rosenweg-tv">\n';
  for (const [id, c] of channels) {
    xml += `  <channel id="${tv7XmlEsc(id)}"><display-name>${tv7XmlEsc(c.name)}</display-name>${c.logo ? `<icon src="${tv7XmlEsc(c.logo)}"/>` : ''}</channel>\n`;
  }
  for (const p of programmes) {
    xml += `  <programme start="${tv7XmltvTime(p.start)}" stop="${tv7XmltvTime(p.stop)}" channel="${tv7XmlEsc(p.id)}">`;
    xml += `<title>${tv7XmlEsc(p.title)}</title>`;
    if (p.sub) xml += `<sub-title>${tv7XmlEsc(p.sub)}</sub-title>`;
    if (p.desc) xml += `<desc>${tv7XmlEsc(p.desc)}</desc>`;
    xml += `</programme>\n`;
  }
  xml += '</tv>\n';
  return { xml, index: tvEpg.indexBauen(roh, minTs), channels: channels.size, programmes: programmes.length };
}
// Ein Aufbau fuer alle gleichzeitigen Anfragen (S1-2-4): die Route ist offen, und
// jeder Aufbau laedt ~90'000 Eintraege von Init7 — parallele Abrufe vervielfachten
// Last und Speicher. Nach einem Fehlschlag eine Minute Pause statt Dauerversuchen.
let _tv7EpgBau = null;
let _tv7EpgFehlerTs = 0;
function tv7EpgHolen() {
  if (_tv7EpgCache && (Date.now() - _tv7EpgCache.ts) <= TV7_EPG_TTL) return Promise.resolve(_tv7EpgCache);
  if (_tv7EpgBau) return _tv7EpgBau;
  if (Date.now() - _tv7EpgFehlerTs < 60 * 1000) return Promise.reject(new Error('EPG-Aufbau kurz pausiert'));
  _tv7EpgBau = buildTV7Epg()
    .then(built => {
      _tv7EpgCache = { xml: built.xml, index: built.index, ts: Date.now() };
      console.log(`[TV7-EPG] gebaut: ${built.channels} Kanaele, ${built.programmes} Sendungen`);
      return _tv7EpgCache;
    })
    .catch(e => { _tv7EpgFehlerTs = Date.now(); throw e; })
    .finally(() => { _tv7EpgBau = null; });
  return _tv7EpgBau;
}
app.get('/api/tv/epg.xml', async (req, res) => {
  try {
    const cache = await tv7EpgHolen();
    res.set('Content-Type', 'application/xml; charset=utf-8');
    res.set('Cache-Control', 'public, max-age=3600');
    res.send(cache.xml);
  } catch (e) {
    if (_tv7EpgCache) { res.set('Content-Type', 'application/xml; charset=utf-8'); return res.send(_tv7EpgCache.xml); }
    console.error('[TV7-EPG] error:', e.message);
    res.status(502).json({ error: 'EPG derzeit nicht verfügbar' });
  }
});

// JSON-Programm fuer die App Rosenweg TV, aus demselben Cache wie epg.xml.
//   GET /api/tv/jetzt                      Jetzt und Danach aller Sender, Schluessel = tvg
//   GET /api/tv/epg?kanal=<tvg>&von=&bis=  Programm eines Senders (ISO-Zeit; Standard: ab jetzt 24 h)
async function tvEpgIndex(res) {
  try {
    return (await tv7EpgHolen()).index;
  } catch (e) {
    if (_tv7EpgCache) return _tv7EpgCache.index;
    console.error('[TV7-EPG] error:', e.message);
    res.status(502).json({ error: 'Programm derzeit nicht verfügbar' });
    return null;
  }
}
app.get('/api/tv/jetzt', authMiddleware, async (req, res) => {
  const index = await tvEpgIndex(res);
  if (!index) return;
  res.set('Cache-Control', 'private, max-age=60');
  res.json({ erzeugt: new Date().toISOString(), sender: tvEpg.jetztUndDanach(index) });
});
app.get('/api/tv/epg', authMiddleware, async (req, res) => {
  const index = await tvEpgIndex(res);
  if (!index) return;
  const r = tvEpg.programm(index, req.query.kanal, req.query.von, req.query.bis);
  if (r.fehler) return res.status(400).json({ error: r.fehler });
  if (r.unbekannt) return res.status(404).json({ error: 'Sender nicht im Programm' });
  res.set('Cache-Control', 'private, max-age=300');
  res.json(r);
});

app.get('/api/tv/stream-url/:channelId', authMiddleware, (req, res) => {
  const id = req.params.channelId;
  if (!/^[a-f0-9-]+$/i.test(id)) return res.status(400).json({ error: 'Invalid channel id' });
  if (!TV7_HMAC_SECRET) return res.status(500).json({ error: 'TV7 streamer secret nicht konfiguriert' });
  const token = createTv7StreamerToken(req.user.id || req.user.user_id || 0);
  // Pfad-Variante (default /tv-stream): nginx rewrite haengt /<id> direkt
  // an, also Endpunkt ist `${TV7_PUBLIC_URL}/<id>?token=...`.
  // Full-URL-Variante (z.B. https://tv.rosenweg9.ch): LXC erwartet
  // `/stream/<id>?token=...`.
  const isFullUrl = /^https?:\/\//i.test(TV7_PUBLIC_URL);
  const url = isFullUrl
    ? `${TV7_PUBLIC_URL}/stream/${id}?token=${encodeURIComponent(token)}`
    : `${TV7_PUBLIC_URL}/${id}?token=${encodeURIComponent(token)}`;
  res.json({ url, expires_in: TV7_TOKEN_TTL });
});

// HMAC-Token kompatibel mit tv7-streamer/server.js verifyToken().
// Format: base64url(payload).hex16(sig)   payload = {user, exp}
function createTv7StreamerToken(userId) {
  if (!TV7_HMAC_SECRET) throw new Error('TV7_HMAC_SECRET nicht konfiguriert');
  const payloadObj = { user: userId, exp: Math.floor(Date.now() / 1000) + TV7_TOKEN_TTL };
  const payload = Buffer.from(JSON.stringify(payloadObj)).toString('base64url');
  const sig = crypto.createHmac('sha256', TV7_HMAC_SECRET).update(payload).digest('hex').slice(0, 16);
  return `${payload}.${sig}`;
}

// Stream-Endpoint: Browser holt sich hier den MPEG-TS via API,
// API proxyt durch zum tv7-streamer im LXC. Doppel-Hop ist akzeptabel
// (~12 Mbps pro Zuschauer), spart aber CORS/DNS-Komplexitaet im Browser.
// Ohne Authorization-Header nur mit dem kurzlebigen Stream-Token aus
// /api/tv/stream-url (?token=): ein Sitzungstoken in der URL landet in Logs,
// Verlauf und Referer und gaebe dort vollen Kontozugriff.
function verifyTv7StreamerToken(token) {
  if (!TV7_HMAC_SECRET || typeof token !== 'string') return null;
  const [payload, sig] = token.split('.');
  if (!payload || !sig) return null;
  const soll = crypto.createHmac('sha256', TV7_HMAC_SECRET).update(payload).digest('hex').slice(0, 16);
  if (!geheimnisGleich(sig, soll)) return null;
  try {
    const p = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
    return p && p.exp > Math.floor(Date.now() / 1000) ? p : null;
  } catch { return null; }
}
app.get('/api/tv/stream/:channelId', (req, res, next) => {
  if (!req.headers.authorization && req.query.token) {
    const p = verifyTv7StreamerToken(String(req.query.token));
    if (!p) return res.status(401).json({ error: 'Stream-Token ungültig oder abgelaufen' });
    req.user = { id: p.user, user_id: p.user };
    return next('route');
  }
  next();
}, authMiddleware, tvStreamHandler);
app.get('/api/tv/stream/:channelId', tvStreamHandler);
async function tvStreamHandler(req, res) {
  if (!req.user) return res.status(401).json({ error: 'Nicht angemeldet' });
  const id = req.params.channelId;
  if (!/^[a-f0-9-]+$/i.test(id)) return res.status(400).json({ error: 'Invalid channel id' });
  if (!TV7_HMAC_SECRET) return res.status(500).json({ error: 'TV7 streamer secret nicht konfiguriert' });
  const token = createTv7StreamerToken(req.user.id || req.user.user_id || 0);
  const streamUrl = `${TV7_STREAMER_URL}/stream/${id}?token=${encodeURIComponent(token)}`;
  // Connection-Timeout nur für die initialen Headers — danach soll der Stream
  // beliebig lange laufen. AbortSignal.timeout() wuerde auch den Body killen.
  const ctrl = new AbortController();
  const connTimer = setTimeout(() => ctrl.abort(), 10000);
  let upstream;
  try {
    upstream = await fetch(streamUrl, { signal: ctrl.signal });
  } catch (err) {
    clearTimeout(connTimer);
    console.error('TV7 stream fetch failed:', err.message);
    if (!res.headersSent) res.status(502).json({ error: 'Streamer nicht erreichbar' });
    return;
  }
  clearTimeout(connTimer);
  if (!upstream.ok) {
    console.error('TV7 streamer status:', upstream.status);
    return res.status(502).json({ error: 'Streamer nicht erreichbar' });
  }
  res.setHeader('Content-Type', upstream.headers.get('content-type') || 'video/MP2T');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Access-Control-Allow-Origin', '*');
  const reader = upstream.body.getReader();
  req.on('close', () => { try { reader.cancel(); } catch {} });
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (!res.write(Buffer.from(value))) await new Promise(r => res.once('drain', r));
    }
  } catch (err) {
    // Client hat abgebrochen — normal bei Channel-Wechsel
    if (err.code !== 'ABORT_ERR' && err.name !== 'AbortError') {
      console.error('TV7 stream pipe error:', err.message);
    }
  }
  try { res.end(); } catch {}
}

// ─── TV7 Extern (udpxy-Playlist fuer Ferien/Reisen, token-geschuetzt) ─────────
// udpxy relayt den Multicast als HTTP (alle 242 Sender, kein Transcode). Die nginx
// auf isp.rosenweg4303.ch proxyt /tv-udp/<grp>:<port> via auth_request an
// /api/tv/extern/validate und dann an udpxy. Token = DB-Eintrag (verlaengerbar/
// widerrufbar im Interface), KEIN stateless HMAC.
const TV_EXTERN_BASE = process.env.TV_EXTERN_BASE || 'https://isp.rosenweg4303.ch';
const TV_EXTERN_TTL_DAYS = 30;
async function ensureTvExternTable() {
  await pool.query(`CREATE TABLE IF NOT EXISTS tv_extern_tokens (
    id SERIAL PRIMARY KEY,
    token TEXT UNIQUE NOT NULL,
    user_email TEXT NOT NULL,
    label TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL,
    last_used_at TIMESTAMPTZ,
    revoked BOOLEAN DEFAULT FALSE)`);
  await pool.query('CREATE INDEX IF NOT EXISTS idx_tv_extern_token ON tv_extern_tokens(token)');
}
setTimeout(() => ensureTvExternTable().catch(e => console.warn('[tv-extern] init:', e.message)), 12000);

async function tvExternValidate(token) {
  if (!token) return false;
  const r = await pool.query('SELECT id FROM tv_extern_tokens WHERE token = $1 AND revoked = FALSE AND expires_at > NOW() LIMIT 1', [String(token)]);
  if (!r.rows[0]) return false;
  pool.query('UPDATE tv_extern_tokens SET last_used_at = NOW() WHERE id = $1', [r.rows[0].id]).catch(() => {});
  return true;
}

// nginx auth_request-Ziel: schnell 200/403 (kein Auth — der Token IST die Auth).
app.get('/api/tv/extern/validate', async (req, res) => {
  try { res.status((await tvExternValidate(req.query.token)) ? 200 : 403).end(); }
  catch { res.status(403).end(); }
});

// Token erstellen
app.post('/api/tv/extern/token', authMiddleware, async (req, res) => {
  try {
    const email = (req.user.email || '').toLowerCase();
    const label = String(req.body?.label || 'Ferien').slice(0, 80);
    const token = crypto.randomBytes(18).toString('base64url');
    const exp = new Date(Date.now() + TV_EXTERN_TTL_DAYS * 86400000);
    await pool.query('INSERT INTO tv_extern_tokens (token, user_email, label, expires_at) VALUES ($1,$2,$3,$4)', [token, email, label, exp]);
    res.json({ ok: true, token, m3u_url: `${TV_EXTERN_BASE}/api/tv/extern.m3u?token=${token}`, expires_at: exp });
  } catch (e) { console.error('[tv-extern-create]', e); res.status(500).json({ error: 'Fehler' }); }
});

