// WASCHKÜCHE - RESERVIERUNGEN (minutengenau)
// ═══════════════════════════════════════════════════════════════════

// Get all reservations (optionally filter by ?room_id=X and ?from=ISO&to=ISO)
app.get('/api/wasch/reservations', authMiddleware, async (req, res) => {
  try {
    const { room_id, from, to } = req.query;
    let query = `SELECT r.*, u.name as user_name, u.wohnung, rm.name as room_name
       FROM wasch_reservations r
       JOIN users u ON u.id = r.user_id
       JOIN wasch_rooms rm ON rm.id = r.room_id
       WHERE r.cancelled = false`;
    const params = [];
    // Mandantentrennung (S1-2-3): Nicht-Admins sehen Reservationen (mit Namen) nur
    // in Raeumen ihrer STWEG(s), wie beim Reservieren; lesen auch die Hausverwaltung.
    if (!req.user.isAdmin) {
      params.push([...getStwegsMitVerwaltung(req.user.groups || [])]);
      query += ` AND (rm.stweg = ANY($${params.length}::int[]) OR (rm.stweg IS NULL AND cardinality($${params.length}::int[]) > 0))`;
    }
    if (room_id) { params.push(room_id); query += ` AND r.room_id = $${params.length}`; }
    if (from) { params.push(from); query += ` AND r.end_time >= $${params.length}::timestamp`; }
    if (to) { params.push(to); query += ` AND r.start_time <= $${params.length}::timestamp`; }
    if (!from && !to) { query += ' AND r.end_time >= NOW()'; }
    query += ' ORDER BY r.start_time';
    const result = await pool.query(query, params);
    res.json(result.rows);
  } catch (err) {
    res.status(500).json({ error: 'Fehler beim Laden der Reservierungen' });
  }
});

// Create reservation (one-time or recurring weekly)
app.post('/api/wasch/reservations', authMiddleware, async (req, res) => {
  const { room_id, start_time, end_time, recurring, recurring_until } = req.body;
  if (!room_id || !start_time || !end_time) {
    return res.status(400).json({ error: 'room_id, start_time und end_time erforderlich' });
  }

  const startDt = new Date(start_time);
  const endDt = new Date(end_time);
  if (typeof start_time !== 'string' || typeof end_time !== 'string' || isNaN(startDt) || isNaN(endDt)) {
    return res.status(400).json({ error: 'Ungültige Zeitangabe' });
  }
  if (endDt <= startDt) return res.status(400).json({ error: 'end_time muss nach start_time liegen' });

  // Duration in minutes
  const durationMin = (endDt - startDt) / 60000;
  if (durationMin < 30) return res.status(400).json({ error: 'Mindestdauer: 30 Minuten' });
  if (durationMin > 720) return res.status(400).json({ error: 'Maximaldauer: 12 Stunden' });

  // Eine Reservation oeffnet die Waschkuechen-Tuer (manageDoorAccess) -> nur fuer
  // Angehoerige der STWEG des Raums, nicht rueckwirkend, nicht beliebig weit voraus.
  const roomNr = parseInt(room_id, 10);
  if (!Number.isInteger(roomNr) || roomNr <= 0) return res.status(400).json({ error: 'Ungültiger Raum' });
  const istAdmin = !!req.user.isAdmin;
  // Grenzen aus den Einstellungen (Verwalten): reservation_max_days, reservation_max_per_user
  const einst = await waschEinstellungen();
  if (!istAdmin) {
    if (startDt.getTime() < Date.now() - 10 * 60 * 1000) return res.status(400).json({ error: 'Reservationen in der Vergangenheit sind nicht möglich' });
    if (startDt.getTime() > Date.now() + einst.maxTage * 86400000) return res.status(400).json({ error: `Höchstens ${einst.maxTage} Tage im Voraus` });
  }
  let untilDt = null;
  if (recurring && recurring_until) {
    untilDt = new Date(recurring_until);
    if (isNaN(untilDt)) return res.status(400).json({ error: 'Ungültiges Enddatum der Serie' });
    if (!istAdmin && untilDt.getTime() > Date.now() + 366 * 86400000) return res.status(400).json({ error: 'Serien höchstens ein Jahr im Voraus' });
  }
  try {
    const raum = (await pool.query('SELECT stweg, active FROM wasch_rooms WHERE id = $1', [roomNr])).rows[0];
    if (!raum || raum.active === false) return res.status(404).json({ error: 'Raum nicht gefunden' });
    if (!istAdmin) {
      const meine = getUserStwegs(req.user.groups || []);
      if (raum.stweg ? !meine.has(Number(raum.stweg)) : meine.size === 0) {
        return res.status(403).json({ error: 'Keine Berechtigung für diese Waschküche' });
      }
      const offen = await pool.query('SELECT COUNT(*)::int AS n FROM wasch_reservations WHERE user_id = $1 AND cancelled = false AND end_time >= NOW()', [req.user.user_id]);
      if (offen.rows[0].n >= einst.maxOffen) return res.status(429).json({ error: `Höchstens ${einst.maxOffen} offene Reservationen je Person` });
    }
  } catch (err) {
    return res.status(500).json({ error: fehlerFuerClient(err, 'Fehler beim Erstellen der Reservierung') });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // Lock on room_id to prevent concurrent overlapping reservations
    await client.query('SELECT pg_advisory_xact_lock($1)', [roomNr]);

    if (recurring && recurring_until) {
      // Generate weekly recurring reservations (same weekday, same time)
      const created = [];
      const until = untilDt;
      let curStart = new Date(startDt);
      let curEnd = new Date(endDt);

      let runden = 0;
      while (curStart <= until && runden++ < 60) { // hoechstens 60 Wochen pro Serie
        // Check overlap with existing reservations
        const conflict = await client.query(
          `SELECT id FROM wasch_reservations
           WHERE room_id=$1 AND cancelled=false
           AND start_time < $3::timestamp AND end_time > $2::timestamp`,
          [room_id, curStart.toISOString(), curEnd.toISOString()]
        );
        const gesperrt = await client.query(
          `SELECT id FROM wasch_sperrzeiten
           WHERE room_id=$1 AND start_time < $3::timestamp AND end_time > $2::timestamp LIMIT 1`,
          [room_id, curStart.toISOString(), curEnd.toISOString()]
        );
        if (conflict.rows.length === 0 && gesperrt.rows.length === 0) {
          const result = await client.query(
            `INSERT INTO wasch_reservations (user_id, room_id, start_time, end_time, recurring, recurring_until)
             VALUES ($1, $2, $3, $4, true, $5) RETURNING *`,
            [req.user.user_id, room_id, curStart.toISOString(), curEnd.toISOString(), recurring_until]
          );
          created.push(result.rows[0]);
        }
        curStart.setDate(curStart.getDate() + 7);
        curEnd.setDate(curEnd.getDate() + 7);
      }
      await client.query('COMMIT');
      res.json({ created: created.length, reservations: created });
    } else {
      // One-time reservation - check overlap
      const conflict = await client.query(
        `SELECT id FROM wasch_reservations
         WHERE room_id=$1 AND cancelled=false
         AND start_time < $3::timestamp AND end_time > $2::timestamp`,
        [room_id, start_time, end_time]
      );
      if (conflict.rows.length > 0) {
        await client.query('ROLLBACK');
        return res.status(409).json({ error: 'Zeitraum überschneidet sich mit bestehender Reservierung' });
      }
      const sperre = await client.query(
        `SELECT grund FROM wasch_sperrzeiten
         WHERE room_id=$1 AND start_time < $3::timestamp AND end_time > $2::timestamp
         ORDER BY start_time LIMIT 1`,
        [room_id, start_time, end_time]
      );
      if (sperre.rows.length > 0) {
        await client.query('ROLLBACK');
        return res.status(409).json({ error: `Gesperrt: ${sperre.rows[0].grund}`, sperrzeit: true });
      }

      const result = await client.query(
        `INSERT INTO wasch_reservations (user_id, room_id, start_time, end_time)
         VALUES ($1, $2, $3, $4) RETURNING *`,
        [req.user.user_id, room_id, start_time, end_time]
      );
      await client.query('COMMIT');
      res.json(result.rows[0]);
    }
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    res.status(500).json({ error: 'Fehler beim Erstellen der Reservierung' });
  } finally {
    client.release();
  }
});

