app.get('/api/kontakte/:stweg', authMiddleware, async (req, res) => {
  const stweg = parseStweg(req.params.stweg);
  if (!stweg) return res.status(400).json({ error: 'Ungültige STWEG-Nummer' });
  // Nur die eigene STWEG (Gruppenzugehoerigkeit), die Verwaltung dieser STWEG oder Admin
  if (!req.user.isAdmin && !getStwegsMitVerwaltung(req.user.groups || []).has(stweg)) return res.status(403).json({ error: 'Keine Berechtigung für diese STWEG' });
  try {
    const result = await pool.query(
      `SELECT * FROM kontakte WHERE stweg = $1 ORDER BY sort_order, name`,
      [stweg]
    );
    const sicht = await nummernSicht(req, pool);
    res.json({ kontakte: result.rows.map(k => sicht(k, { email: k.email, name: k.name, stweg })) });
  } catch (err) {
    res.status(500).json({ error: 'Fehler' });
  }
});

app.put('/api/kontakte', authMiddleware, adminOnly, async (req, res) => {
  const { kontakte } = req.body;
  if (!Array.isArray(kontakte)) return res.status(400).json({ error: 'Ungültige Daten' });

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // Wer die echten Nummern nicht sieht (GET liefert sie leer), loescht sie
    // beim Speichern nicht: leeres telefon heisst dann "unveraendert".
    const telefonSql = istTechnikOderPraesident(req.user) ? '$3' : "COALESCE(NULLIF($3, ''), telefon)";
    for (const k of kontakte) {
      if (k.id) {
        await client.query(
          `UPDATE kontakte SET name=$1, email=$2, telefon=${telefonSql}, funktion=$4, wohnung=$5, sort_order=$6, updated_at=NOW()
           WHERE id=$7`,
          [k.name, k.email, k.telefon, k.funktion, k.wohnung, k.sort_order || 0, k.id]
        );
      } else {
        await client.query(
          `INSERT INTO kontakte (name, email, telefon, funktion, wohnung, stweg, sort_order)
           VALUES ($1, $2, $3, $4, $5, $6, $7)`,
          [k.name, k.email, k.telefon, k.funktion, k.wohnung, k.stweg, k.sort_order || 0]
        );
      }
    }
    await client.query('COMMIT');
    res.json({ success: true });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Fehler beim Speichern' });
  } finally {
    client.release();
  }
});

// ═══════════════════════════════════════════════════════════════════
// EMAIL VERTEILER (replaces n8n stweg3-email-verteiler)
// ═══════════════════════════════════════════════════════════════════

// Resolve all email addresses for a group (including all descendant groups)
// Holt die beiden teuren Authentik-Volllisten (Gruppen + aktive User).
// Teuer (~je mehrere Sekunden, kalt) — daher kurzer Cross-Request-Cache (TTL)
// PLUS In-Flight-Coalescing (gleichzeitige Aufrufer teilen sich einen Fetch).
// Glaettet u.a. den Cold-Start von GET /api/verteiler. Tradeoff: Gruppen-
// Mitgliedschaften koennen bis zu AUTH_GU_TTL veraltet angezeigt werden — fuer
// Member-Counts/Versand-Vorschau unkritisch (Authentik-Gruppen aendern selten).
const AUTH_GU_TTL = 60 * 1000;
let _authGUCache = null;      // { ts, data }
let _authGUInflight = null;   // Promise waehrend ein Fetch laeuft
async function fetchAuthentikGroupsUsers(force = false) {
  if (!force && _authGUCache && (Date.now() - _authGUCache.ts) < AUTH_GU_TTL) {
    return _authGUCache.data;
  }
  if (_authGUInflight) return _authGUInflight;
  _authGUInflight = (async () => {
    try {
      const groupsData = await authentikAPI('GET', '/core/groups/?page_size=500');
      const allGroups = groupsData.results || groupsData;
      const usersData = await authentikAPI('GET', '/core/users/?page_size=500');
      const allUsers = (usersData.results || usersData).filter(u => u.is_active && u.email);
      const data = { allGroups, allUsers };
      _authGUCache = { ts: Date.now(), data };
      return data;
    } finally {
      _authGUInflight = null;
    }
  })();
  return _authGUInflight;
}

// Gruppen/Rolle/Aktiv aus Authentik nach users nachziehen. groups_json schrieb bisher
// nur der OAuth-Callback; Sessions (30 Tage gleitend), PATs und /api/ssh lesen es —
// wer aus 'technik' flog, behielt Admin-Rechte und sudo, bis er sich neu anmeldete.
// Konten, die es in Authentik nicht gibt (nur E-Mail-Code), bleiben unberuehrt.
async function syncAuthentikUserRechte() {
  try {
    const liste = [];
    let page = 1;
    for (; page <= 20; page++) {
      const d = await authentikAPI('GET', `/core/users/?page_size=500&page=${page}`);
      liste.push(...(d.results || []));
      if (!d.pagination?.next) break;
    }
    if (page > 20 || liste.length === 0) return; // unvollstaendig/leer -> nichts entziehen
    if (!usersSubSpalte) usersSubSpalte = pool.query('ALTER TABLE users ADD COLUMN IF NOT EXISTS authentik_sub TEXT').catch(e => { usersSubSpalte = null; throw e; });
    await usersSubSpalte;
    const lokal = new Map((await pool.query('SELECT id, LOWER(email) AS email, role, groups_json, active, authentik_sub FROM users')).rows.map(r => [r.email, r]));
    // Mehrere Authentik-Konten mit derselben E-Mail (R3-S2b): nicht das zuletzt
    // gelistete Konto die Rechte der users-Zeile bestimmen lassen. Nur das an die
    // Zeile gebundene Konto (uid == authentik_sub) zaehlt; sonst nichts aendern.
    const proEmail = new Map();
    for (const au of liste) {
      const e = String(au.email || '').toLowerCase();
      if (e) proEmail.set(e, (proEmail.get(e) || 0) + 1);
    }
    let geaendert = 0;
    for (const au of liste) {
      const u = lokal.get(String(au.email || '').toLowerCase());
      if (!u) continue;
      if (proEmail.get(u.email) > 1 && !(u.authentik_sub && au.uid && au.uid === u.authentik_sub)) {
        if (!syncDoppelGemeldet.has(u.email)) { syncDoppelGemeldet.add(u.email); console.warn(`[authentik-sync] ${u.email}: mehrere Authentik-Konten mit dieser E-Mail – Konto ${au.pk} nicht uebernommen`); }
        continue;
      }
      const gruppen = (au.groups_obj || []).map(g => g.name).filter(Boolean);
      const istAdmin = gruppen.some(g => ['technik', 'präsident', 'praesident'].includes(g.toLowerCase()));
      let alt = []; try { alt = JSON.parse(u.groups_json || '[]'); } catch {}
      const gleich = alt.length === gruppen.length && [...alt].sort().join('\n') === [...gruppen].sort().join('\n');
      // 'admin' haengt an technik/praesident; andere lokale Rollen (eigentuemer, verwalter …) bleiben
      const rolle = istAdmin ? 'admin' : (u.role === 'admin' ? 'bewohner' : u.role);
      const aktiv = au.is_active !== false;
      if (gleich && u.role === rolle && u.active === aktiv) continue;
      await pool.query('UPDATE users SET groups_json = $2, role = $3, active = $4, updated_at = NOW() WHERE id = $1',
        [u.id, JSON.stringify(gruppen), rolle, aktiv]);
      geaendert++;
      const weg = alt.filter(g => !gruppen.includes(g));
      if (weg.length || u.active !== aktiv) console.log(`[authentik-sync] ${u.email}: ${!aktiv ? 'deaktiviert, ' : ''}${weg.length ? 'entzogen: ' + weg.join(',') : ''}`);
    }
    // Direkt in Authentik geloeschte Konten (S2-3-2): Zeilen, die an ein Authentik-
    // Konto gebunden waren (authentik_sub gesetzt), dessen E-Mail es nicht mehr
    // gibt, deaktivieren -> Sitzungen und PATs greifen nicht mehr. Reine E-Mail-
    // Code-Konten haben kein authentik_sub und bleiben unberuehrt.
    // Abgleich vor allem ueber die gebundene Kennung (sub = uid, bzw. username je nach
    // sub-Modus): Konten ohne E-Mail in Authentik (users.email = sub) waeren sonst alle
    // 10 min deaktiviert worden. E-Mail-Treffer zaehlt weiter als "vorhanden" (fail-safe).
    const kennungen = new Set();
    for (const au of liste) { if (au.uid) kennungen.add(String(au.uid)); if (au.username) kennungen.add(String(au.username)); }
    for (const u of lokal.values()) {
      if (!u.authentik_sub || u.active === false || proEmail.has(u.email) || kennungen.has(String(u.authentik_sub))) continue;
      await pool.query('UPDATE users SET active = false, updated_at = NOW() WHERE id = $1', [u.id]);
      await pool.query('DELETE FROM sessions WHERE user_id = $1', [u.id]);
      console.log(`[authentik-sync] ${u.email}: Authentik-Konto nicht mehr vorhanden, deaktiviert`);
      geaendert++;
    }
    if (geaendert) console.log(`[authentik-sync] ${geaendert} Konto/Konten aktualisiert`);
  } catch (e) { console.warn('[authentik-sync]', e.message); }
}
const syncDoppelGemeldet = new Set(); // Doppelkonten nur einmal je Prozess melden
setTimeout(syncAuthentikUserRechte, 2 * 60 * 1000);
setInterval(syncAuthentikUserRechte, 10 * 60 * 1000);

// Pure: loest Gruppe (inkl. Untergruppen-Hierarchie) gegen vorgeladene Listen auf.
function resolveGroupEmailsFromData(groupName, allGroups, allUsers) {
  const target = allGroups.find(g => g.name.toLowerCase() === groupName.toLowerCase());
  if (!target) return [];
  // Collect target + all descendant group PKs
  const groupPks = new Set([target.pk]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const g of allGroups) {
      if (g.parent && groupPks.has(g.parent) && !groupPks.has(g.pk)) {
        groupPks.add(g.pk);
        changed = true;
      }
    }
  }
  const emails = new Set();
  for (const u of allUsers) {
    const userGroupPks = u.groups_obj ? u.groups_obj.map(g => g.pk) : (u.groups || []);
    if (userGroupPks.some(pk => groupPks.has(pk))) {
      emails.add(u.email.toLowerCase());
    }
  }
  return [...emails];
}

async function resolveGroupEmails(groupName) {
  try {
    const { allGroups, allUsers } = await fetchAuthentikGroupsUsers();
    return resolveGroupEmailsFromData(groupName, allGroups, allUsers);
  } catch (err) {
    console.error('resolveGroupEmails error:', err.message);
    return [];
  }
}

// Resolve a Verwaltungs-Gruppe (live from wohnungen_kontakte / wohnungen).
// Spec: "verwaltung:<rolle>[:stweg=N][:include_drucker]"
//   rolle: eigentuemer | verwalter | mieter | bewohner (= eigentuemer if bewohnt_von='eigentuemer' else mieter, per wohnung)
//   stweg=N optional: scope to one STWEG
//   include_drucker optional: include druckerr9+ tags as fallback when no real email
async function resolveVerwaltungsGroup(spec) {
  const parts = spec.split(':').slice(1); // strip "verwaltung:"
  const rolle = parts[0];
  let stwegFilter = null;
  let includeDrucker = false;
  let alleKontakte = false;
  for (const opt of parts.slice(1)) {
    if (opt.startsWith('stweg=')) stwegFilter = parseInt(opt.slice(6));
    else if (opt === 'include_drucker') includeDrucker = true;
    else if (opt === 'alle_kontakte') alleKontakte = true;
  }
  const emails = new Set();
  const druckerCandidates = [];
  try {
    if (rolle === 'objektverwaltung') {
      // Die beauftragte Verwaltung (aktiv, im Vertragszeitraum): Firmenadresse + Standard-CC-
      // Kontakte. Wechselt die Verwaltung, folgt der Verteiler beim naechsten Sync von selbst.
      // Der Ausschuss-Ersatz von findVerwaltungForStweg (id=null) zaehlt hier nicht.
      // Mit :alle_kontakte alle Mitarbeitenden mit E-Mail, nicht nur die Standard-CC-Kontakte.
      const v = await findVerwaltungForStweg(stwegFilter);
      if (v && v.id) {
        [...v.mailTo, ...v.mailCc].forEach(e => emails.add(String(e).toLowerCase()));
        if (alleKontakte) {
          const k = await pool.query(
            `SELECT email FROM verwaltungs_kontakte WHERE verwaltung_id = $1 AND email IS NOT NULL AND email <> ''`, [v.id]);
          k.rows.forEach(r => emails.add(r.email.trim().toLowerCase()));
        }
      }
    } else if (rolle === 'bewohner') {
      // Per-wohnung: pick the role that actually lives there (bewohnt_von)
      const q = await pool.query(`
        SELECT wk.email FROM wohnungen w
        JOIN wohnungen_kontakte wk ON wk.wohnung_id = w.id AND wk.rolle = w.bewohnt_von
        WHERE wk.email IS NOT NULL AND wk.email <> '' ${stwegFilter ? 'AND w.stweg = $1' : ''}
      `, stwegFilter ? [stwegFilter] : []);
      for (const r of q.rows) {
        const e = r.email.toLowerCase();
        if (e.startsWith('druckerr9+') || e.startsWith('druckerr13+')) druckerCandidates.push(e);
        else emails.add(e);
      }
    } else {
      const q = await pool.query(`
        SELECT wk.email FROM wohnungen_kontakte wk
        JOIN wohnungen w ON w.id = wk.wohnung_id
        WHERE wk.rolle = $1 AND wk.email IS NOT NULL AND wk.email <> '' ${stwegFilter ? 'AND w.stweg = $2' : ''}
      `, stwegFilter ? [rolle, stwegFilter] : [rolle]);
      for (const r of q.rows) {
        const e = r.email.toLowerCase();
        if (e.startsWith('druckerr9+') || e.startsWith('druckerr13+')) druckerCandidates.push(e);
        else emails.add(e);
      }
    }
    if (includeDrucker) druckerCandidates.forEach(e => emails.add(e));
  } catch (err) {
    console.error('resolveVerwaltungsGroup error:', err.message);
  }
  return [...emails];
}

// Resolve members for a verteiler. groupNames entries:
//   "verwaltung:..."  → live from Verwaltungs-DB
//   <other>           → Authentik group (resolveGroupEmails)
async function resolveVerteilerRecipients(verteiler) {
  // Druckeradressen ohne +tag (z.B. "druckerr9@…") sind keine zustellbaren Empfänger —
  // ohne tag weiss das Print-System nicht, an wen → niemals in die Verteiler-Liste lassen.
  const isInvalidDrucker = e => /^druckerr(9|13)@/i.test(e);
  const groupNames = verteiler.group_names?.length ? verteiler.group_names : (verteiler.group_name ? [verteiler.group_name] : []);
  if (groupNames.length > 0) {
    const allEmails = new Set();
    for (const gn of groupNames) {
      const emails = gn.startsWith('verwaltung:')
        ? await resolveVerwaltungsGroup(gn)
        : await resolveGroupEmails(gn);
      emails.forEach(e => { if (!isInvalidDrucker(e)) allEmails.add(e); });
    }
    // Rundmail an Bewohner/Eigentuemer einer STWEG: auch an deren Hausverwaltung
    // (stwegN-verwaltung), die nicht mehr in der Bewohnergruppe steht
    // (lib/verteiler-verwaltung.js).
    const verwGruppe = verteilerVerwaltung.verwaltungsGruppeFuerVerteiler(verteiler);
    if (verwGruppe && !groupNames.some(gn => String(gn).toLowerCase() === verwGruppe)) {
      (await resolveGroupEmails(verwGruppe)).forEach(e => { if (!isInvalidDrucker(e)) allEmails.add(e); });
    }
    // Statische Zusatz-Mitglieder additiv zur Gruppe (z.B. WhatsApp-Bridge-Adressen
    // wie technik@whatsapp.rosenweg4303.ch). Frueher wurden members bei group_names ignoriert.
    for (const m of (verteiler.members || [])) {
      const e = typeof m === 'string' ? m : m.email;
      if (e && !e.endsWith('.invalid') && !isInvalidDrucker(e)) allEmails.add(e);
    }
    return [...allEmails];
  }
  // Fallback: static members list (legacy — for verteilers not yet migrated)
  return (verteiler.members || [])
    .map(m => typeof m === 'string' ? m : m.email)
    .filter(e => e && !e.endsWith('.invalid') && !isInvalidDrucker(e));
}

