// STWEG-Zugriff wie requireStwegAccess, fuer Routen ohne :stweg-Parameter
// (Ruecklaeufe/Historie haengen am Snapshot-Hash bzw. Query-Parameter).
function ulStwegErlaubt(groups, stweg) {
  if (isTechnik(groups) || isPraesident(groups)) return true;
  const m = STWEG_GROUPS[Number(stweg)];
  if (!m) return false;
  if (isVerwaltungFor(groups, stweg)) return true;
  const lower = groups.map(g => String(g).toLowerCase());
  return Object.values(m).some(g => lower.includes(g.toLowerCase()));
}

// GET /api/unterschriftenliste/:hash/rueckläufe — Liste aller Briefe + Rücklauf-Status.
// Ja/Nein mit Name sehen nur Ausschuss und Verwaltung DIESER STWEG sowie
// Technik/Praesident (Entscheid Stefan 28.11.2026, E2/F4; zevAdminFuerStweg).
app.get(encodeURI('/api/unterschriftenliste/:hash/rueckläufe'), authMiddleware, requirePermission('wohnungsverwaltung', 'read'), async (req, res) => {
  try {
    const hash = req.params.hash.toUpperCase();
    const snap = await pool.query(
      'SELECT hash, stweg, datum, anlass_titel, generated_at FROM unterschriftenliste_snapshots WHERE hash = $1',
      [hash]
    );
    if (snap.rows.length === 0) return res.status(404).json({ error: 'Snapshot nicht gefunden' });
    if (!zevAdminFuerStweg(req.user?.groups || [], snap.rows[0].stweg)) return res.status(403).json({ error: 'Rückläufe sehen nur Ausschuss und Verwaltung dieser STWEG' });
    const briefe = await pool.query(`
      SELECT brief_idx, brief_typ, einheit, empfaenger_name, empfaenger_adresse,
             retourniert_am, vote, notiz, erfasst_von, updated_at
      FROM unterschriftenliste_rueckläufe
      WHERE snapshot_hash = $1
      ORDER BY brief_idx
    `, [hash]);
    const stats = {
      total: briefe.rows.length,
      retourniert: briefe.rows.filter(b => b.retourniert_am).length,
      ja: briefe.rows.filter(b => b.vote === 'ja').length,
      nein: briefe.rows.filter(b => b.vote === 'nein').length,
      enthaltung: briefe.rows.filter(b => b.vote === 'enthaltung').length,
      offen: briefe.rows.filter(b => !b.retourniert_am).length,
    };
    res.json({ snapshot: snap.rows[0], briefe: briefe.rows, stats });
  } catch (err) {
    console.error('[UL-Ruecklaeufe]', err.message);
    res.status(500).json({ error: 'Fehler' });
  }
});

// PUT /api/unterschriftenliste/:hash/rueckläufe/:idx — Rücklauf-Eintrag aktualisieren
app.put(encodeURI('/api/unterschriftenliste/:hash/rueckläufe/:idx'), authMiddleware, requirePermission('wohnungsverwaltung', 'write'), ...objSchreibend, async (req, res) => {
  try {
    const hash = req.params.hash.toUpperCase();
    const idx = parseInt(req.params.idx);
    const snap = await pool.query('SELECT stweg FROM unterschriftenliste_snapshots WHERE hash = $1', [hash]);
    if (snap.rows.length === 0) return res.status(404).json({ error: 'Snapshot nicht gefunden' });
    // Schreiben wie requireStwegWrite (nur Ausschuss dieser STWEG / Technik)
    if (!stwegSchreibErlaubt(req.user?.groups || [], snap.rows[0].stweg)) return res.status(403).json({ error: 'Kein Zugriff auf diese STWEG' });
    const { retourniert_am, vote, notiz } = req.body || {};
    const validVote = ['ja', 'nein', 'enthaltung', null].includes(vote) ? vote : null;
    const me = req.user?.email || req.user?.name || 'unknown';
    const vorher = await pool.query('SELECT vote, retourniert_am FROM unterschriftenliste_rueckläufe WHERE snapshot_hash = $1 AND brief_idx = $2', [hash, idx]);
    const r = await pool.query(`
      UPDATE unterschriftenliste_rueckläufe
      SET retourniert_am = $1, vote = $2, notiz = $3, erfasst_von = $4, updated_at = NOW()
      WHERE snapshot_hash = $5 AND brief_idx = $6
      RETURNING *
    `, [retourniert_am || null, validVote, notiz || null, me, hash, idx]);
    if (r.rows.length === 0) return res.status(404).json({ error: 'Brief nicht gefunden' });
    const alt = vorher.rows[0] || {};
    await adminProtokoll.eintragen(pool, null, req, {
      bereich: 'objekte', aktion: 'ruecklauf-erfasst', ziel: `Unterschriftenliste ${hash} · Brief ${idx}`,
      alt: [alt.retourniert_am ? 'retourniert' : 'offen', alt.vote].filter(Boolean).join(' '),
      neu: [r.rows[0].retourniert_am ? 'retourniert' : 'offen', r.rows[0].vote].filter(Boolean).join(' '),
      detail: `STWEG ${snap.rows[0].stweg}`,
    }).catch(e => console.error('[objekte] Protokoll:', e.message));
    res.json(r.rows[0]);
  } catch (err) {
    console.error('[UL-Ruecklauf-PUT]', err.message);
    res.status(500).json({ error: 'Fehler beim Speichern' });
  }
});

// GET /api/unterschriftenliste/history — alle generierten Snapshots auflisten
app.get('/api/unterschriftenliste/history', authMiddleware, requirePermission('wohnungsverwaltung', 'read'), async (req, res) => {
  try {
    const where = [];
    const params = [];
    if (req.query.stweg) { params.push(parseInt(req.query.stweg)); where.push(`stweg = $${params.length}`); }
    // Nicht-Admins sehen nur Snapshots ihrer STWEG(s)
    const g = req.user?.groups || [];
    if (!isTechnik(g) && !isPraesident(g)) {
      const eigene = Object.keys(STWEG_GROUPS).map(Number).filter(nr => ulStwegErlaubt(g, nr));
      params.push(eigene); where.push(`stweg = ANY($${params.length}::int[])`);
    }
    const r = await pool.query(`
      SELECT hash, stweg, datum, anlass_titel, generated_at, generated_by, download_count,
             jsonb_array_length(snapshot_data->'wohnungen') AS unit_count
      FROM unterschriftenliste_snapshots
      ${where.length ? 'WHERE ' + where.join(' AND ') : ''}
      ORDER BY generated_at DESC LIMIT 100
    `, params);
    res.json({ snapshots: r.rows });
  } catch (err) {
    console.error('[UL-History]', err.message);
    res.status(500).json({ error: 'Fehler' });
  }
});

app.get('/api/unterschriftenliste/:stweg.pdf', authMiddleware, requirePermission('wohnungsverwaltung', 'read'), requireStwegAccess, requireStwegWrite, async (req, res) => {
  try {
    const stweg = parseStweg(req.params.stweg);
    if (!stweg) return res.status(400).json({ error: 'Ungültige STWEG' });
    let zeichner = [];
    if (req.query.zeichnungsberechtigte) {
      try { zeichner = JSON.parse(req.query.zeichnungsberechtigte); } catch {}
      if (!Array.isArray(zeichner)) zeichner = [];
    }
    // Optionaler Haus-Filter (kommagetrennt, z.B. "17" oder "13,14")
    let hausFilter = null;
    if (req.query.haus) {
      hausFilter = String(req.query.haus).split(',').map(s => parseInt(s.trim())).filter(n => Number.isFinite(n));
      if (hausFilter.length === 0) hausFilter = null;
    }
    // Datum landet in DB (DATE) und im Gotenberg-HTML – nur ISO-Datum zulassen.
    if (req.query.datum && !/^\d{4}-\d{2}-\d{2}$/.test(String(req.query.datum))) {
      return res.status(400).json({ error: 'Ungültiges Datum (JJJJ-MM-TT)' });
    }
    const opts = {
      datum: req.query.datum || new Date().toISOString().slice(0, 10),
      anlass_titel: req.query.anlass_titel || 'Unterschriftenliste',
      anlass_zweck: req.query.anlass_zweck || '',
      ruecksendung_bis: req.query.ruecksendung_bis || '',
      ruecksendung_an: req.query.ruecksendung_an || '',
      zeichnungsberechtigte: zeichner,
      kollektiv_text: req.query.kollektiv_text || '',
      haus_filter: hausFilter,
      vorschau: req.query.preview === '1',
    };
    opts.generated_by = req.user?.email || req.user?.name || null;
    const html = await buildUnterschriftenlisteHTML(stweg, opts);
    const GOTENBERG = process.env.GOTENBERG_URL || 'http://doc-converter:3000';
    const formData = new FormData();
    formData.append('files', new Blob([html], { type: 'text/html' }), 'index.html');
    formData.append('paperWidth', '8.27');
    formData.append('paperHeight', '11.7');
    formData.append('marginTop', '0.4');
    formData.append('marginBottom', '0.6');
    formData.append('marginLeft', '0.4');
    formData.append('marginRight', '0.4');
    formData.append('preferCssPageSize', 'true');
    const release = await gotenbergSemaphore();
    let pdfResp;
    try {
      pdfResp = await fetch(`${GOTENBERG}/forms/chromium/convert/html`, {
        method: 'POST', body: formData, signal: AbortSignal.timeout(30000),
      });
    } finally { release(); }
    if (!pdfResp.ok) {
      const err = await pdfResp.text();
      console.error('[Unterschriftenliste] Gotenberg error:', err.slice(0, 300));
      return res.status(500).json({ error: 'PDF-Erstellung fehlgeschlagen' });
    }
    const pdfBuf = Buffer.from(await pdfResp.arrayBuffer());
    // PDF persistieren — Original-Datei für späteren Re-Download
    if (opts._hash) {
      try {
        const dir = pathModule.join(DOCS_PATH, 'allgemein', 'unterschriftenlisten');
        await fs.mkdir(dir, { recursive: true });
        const pdfPath = pathModule.join(dir, `${opts._hash}.pdf`);
        await fs.writeFile(pdfPath, pdfBuf);
        await pool.query(
          'UPDATE unterschriftenliste_snapshots SET pdf_path = $1, pdf_size = $2 WHERE hash = $3',
          [`allgemein/unterschriftenlisten/${opts._hash}.pdf`, pdfBuf.length, opts._hash]
        );
      } catch (e) { console.error('[Unterschriftenliste] PDF save error:', e.message); }
    }
    // Gespeicherte Liste (nicht die Vorschau): Protokoll, mit der Karte auch Kartenvermerk
    if (opts._hash) {
      kartenAdmin.vermerken(req, res, { lesend: true, text: 'Unterschriftenliste erzeugt' });
      await objProtokoll(req, 'objekte', 'unterschriftenliste-erzeugt', `STWEG ${stweg}`, [opts._hash, opts.anlass_titel, opts.datum]);
    }
    res.setHeader('Content-Type', 'application/pdf');
    const inline = req.query.preview === '1';
    const fname = `unterschriftenliste-${stwegFolderName(stweg)}-${opts.datum}-${opts._hash || ''}.pdf`;
    res.setHeader('Content-Disposition', `${inline ? 'inline' : 'attachment'}; filename="${fname}"`);
    res.send(pdfBuf);
  } catch (err) {
    console.error('[Unterschriftenliste] error:', err.message);
    res.status(500).json({ error: 'PDF-Erstellung fehlgeschlagen' });
  }
});

// ─── Protokoll der Objekt- und Personenverwaltung (Befund F3/L4/L10) ─────
// Jede Aenderung an Wohnungen, Kontakten, Import, Export, Unterschriftenlisten,
// Ruecklaeufen und Personen steht im admin_protokoll (Bereich 'objekte' bzw.
// 'personen'); mit der Karte zusaetzlich im Kartenprotokoll
// (kartenAdmin.mitKarteProtokollieren – nur protokollieren, nie sperren).
// Ein Fehler beim Eintragen bricht die Aktion nicht ab (nur Log).
async function objProtokoll(req, bereich, aktion, ziel, teile, db = null) {
  try {
    const detail = (Array.isArray(teile) ? teile : [teile]).filter(x => x !== undefined && x !== null && x !== '').join(' · ') || null;
    await adminProtokoll.eintragen(pool, db, req, { bereich, aktion, ziel, detail });
  } catch (e) { console.error(`[${bereich}] Protokoll:`, e.message); }
}
const kontakteKurz = (kontakte) => {
  const n = {};
  for (const k of (Array.isArray(kontakte) ? kontakte : [])) if (k && k.rolle) n[k.rolle] = (n[k.rolle] || 0) + 1;
  const t = Object.entries(n).map(([r, c]) => `${c} ${r}`).join(', ');
  return t ? `Kontakte: ${t}` : null;
};

// POST /api/objekte/export — Export (XLSX/CSV) vor dem Erzeugen im Browser
// anmelden (Entscheid Stefan 28.11.2026, E7): nur Ausschuss/Verwaltung DIESER
// STWEG und Technik/Praesident, mit Protokolleintrag. Ohne stweg (Eigentuemer-
// Uebersicht, Personen ueber die eigene Sicht): Technik/Praesident, Ausschuss
// oder Verwaltung irgendeiner STWEG. Body: { art, stweg?, format?, anzahl? }
const OBJ_EXPORT_ARTEN = { wohnungen: 'objekte', eigentuemer: 'objekte', personen: 'personen' };
app.post('/api/objekte/export', authMiddleware, requirePermission('wohnungsverwaltung', 'read'), ...objSchreibend, async (req, res) => {
  const b = req.body || {};
  const bereich = OBJ_EXPORT_ARTEN[b.art];
  if (!bereich) return res.status(400).json({ error: 'art: wohnungen, eigentuemer oder personen' });
  const g = req.user?.groups || [];
  const stweg = b.stweg === undefined || b.stweg === null || b.stweg === '' ? null : parseStweg(b.stweg);
  if (b.stweg && !stweg) return res.status(400).json({ error: 'Ungültige STWEG-Nummer' });
  const darf = stweg ? zevAdminFuerStweg(g, stweg)
    : (isTechnik(g) || isPraesident(g) || isAusschussForAny(g) || isVerwaltungForAny(g));
  if (!darf) return res.status(403).json({ error: 'Export nur für Ausschuss und Verwaltung dieser STWEG sowie Technik/Präsident' });
  const format = ['xlsx', 'csv'].includes(b.format) ? b.format : null;
  const anzahl = Number.isFinite(Number(b.anzahl)) ? Math.max(0, Math.floor(Number(b.anzahl))) : null;
  await objProtokoll(req, bereich, 'export', stweg ? `STWEG ${stweg}` : 'eigene Sicht', [b.art, format, anzahl !== null ? `${anzahl} Zeilen` : null]);
  res.json({ ok: true });
});

// GET /api/wohnungen/:stweg - List all apartments for a STWEG (admin, with kontakte)
app.get('/api/wohnungen/:stweg', authMiddleware, requirePermission('wohnungsverwaltung', 'read'), requireStwegAccess, async (req, res) => {
  try {
    const stweg = parseStweg(req.params.stweg);
    const wResult = await pool.query('SELECT * FROM wohnungen WHERE stweg = $1', [stweg]);
    const kResult = await pool.query(
      `SELECT k.* FROM wohnungen_kontakte k JOIN wohnungen w ON k.wohnung_id = w.id WHERE w.stweg = $1 AND k.archiviert_am IS NULL ORDER BY k.rolle, k.sort_order, k.id`,
      [stweg]
    );
    // Group kontakte by wohnung_id
    const kontakteMap = {};
    for (const k of kResult.rows) {
      if (!kontakteMap[k.wohnung_id]) kontakteMap[k.wohnung_id] = [];
      kontakteMap[k.wohnung_id].push(k);
    }
    const wohnungen = wResult.rows.map(w => {
      const kontakte = kontakteMap[w.id] || [];
      // Fallback: if no kontakte but flat eigentuemer_name exists, synthesize a kontakt
      if (kontakte.length === 0 && w.eigentuemer_name) {
        kontakte.push({
          rolle: 'eigentuemer', name: w.eigentuemer_name,
          email: w.eigentuemer_email || null, telefon: w.eigentuemer_telefon || null, adresse: null,
        });
      }
      if (kontakte.length === 0 && w.mieter_name) {
        kontakte.push({
          rolle: 'mieter', name: w.mieter_name,
          email: w.mieter_email || null, telefon: w.mieter_telefon || null, adresse: null,
        });
      }
      return { ...w, kontakte };
    });
    wohnungen.sort((a, b) => wohnungSort(a.bezeichnung, b.bezeichnung));
    const sicht = await nummernSicht(req, pool);
    res.json({ stweg, wohnungen: wohnungen.map(w => wohnungFuerSicht(sicht, w)) });
  } catch (err) {
    console.error('Wohnungen list error:', err);
    res.status(500).json({ error: 'Fehler beim Laden der Wohnungen' });
  }
});

// GET /api/stweg/:stweg/overview - Public summary (counts only, no personal data)
app.get('/api/stweg/:stweg/overview', async (req, res) => {
  try {
    const stweg = parseInt(req.params.stweg, 10);
    if (!stweg || stweg < 1 || stweg > 8) return res.status(400).json({ error: 'Ungueltige STWEG' });
    const counts = await pool.query(
      `SELECT typ, COUNT(*) as anzahl FROM wohnungen WHERE stweg = $1 GROUP BY typ`, [stweg]
    );
    const occupancy = await pool.query(
      `SELECT COUNT(*) as total,
              COUNT(*) FILTER (WHERE bewohnt_von = 'eigentuemer') as selbstbewohnt,
              COUNT(*) FILTER (WHERE bewohnt_von = 'mieter') as vermietet,
              COUNT(*) FILTER (WHERE bewohnt_von = 'leer') as leer
       FROM wohnungen WHERE stweg = $1`, [stweg]
    );
    const waschRooms = await pool.query(
      'SELECT COUNT(*) as anzahl FROM wasch_rooms WHERE stweg = $1 AND active = true', [stweg]
    );
    const typCounts = {};
    for (const r of counts.rows) typCounts[r.typ || 'Wohnung'] = parseInt(r.anzahl);
    res.json({
      stweg,
      typen: typCounts,
      belegung: occupancy.rows[0],
      waschkuechen: parseInt(waschRooms.rows[0].anzahl),
    });
  } catch (err) {
    res.status(500).json({ error: 'Fehler beim Laden der Übersicht' });
  }
});

// Wohnung samt Kontakten fuer die Ausgabe: echte Nummern nach lib/nummernsicht.js
// (Portal: eigene STWEG; MCP/geteilte Telefone: nur interne Nummern).
function wohnungFuerSicht(sicht, w) {
  const aus = sicht(w, { emails: [w.eigentuemer_email, w.mieter_email].filter(Boolean), stweg: w.stweg });
  delete aus.interne_nummer;
  if (Array.isArray(w.kontakte)) aus.kontakte = w.kontakte.map(k => sicht(k, { email: k.email, name: k.name, stweg: w.stweg }));
  return aus;
}

