// ─── Personen-API ────────────────────────────────────────────────────
// Personen sind die Single Source of Truth für Kontaktdaten. Änderungen
// werden automatisch via DB-Trigger auf alle verknuepften wohnungen_kontakte
// propagiert.

// Lese-Zugriff: alle die wohnungsverwaltung lesen können
function requireWohnungsverwaltungRead(req, res, next) {
  return requirePermission('wohnungsverwaltung', 'read')(req, res, next);
}
function requireWohnungsverwaltungWrite(req, res, next) {
  return requirePermission('wohnungsverwaltung', 'write')(req, res, next);
}

// H4: Pruefe ob User berechtigt ist, eine Person zu editieren.
// Technik/Präsident: alle Personen. Ausschuss und Verwaltung (stwegN-verwaltung,
// Entscheid Stefan 28.11.2026): nur Personen aus der eigenen STWEG (mind. eine
// aktive wohnungen_kontakte-Zeile zu einer Wohnung dort; lib/personen-rechte.js).
async function userCanEditPerson(user, personId) {
  const groups = user?.groups || [];
  if (isTechnik(groups) || isPraesident(groups)) return true;
  const ausschussStwegs = [...personenRechte.personenSchreibStwegs(groups)];
  if (ausschussStwegs.length === 0) return false;
  const r = await pool.query(
    `SELECT 1 FROM wohnungen_kontakte k
       JOIN wohnungen w ON w.id = k.wohnung_id
      WHERE k.person_id = $1 AND w.stweg = ANY($2::int[]) AND k.archiviert_am IS NULL
      LIMIT 1`,
    [personId, ausschussStwegs],
  );
  return r.rows.length > 0;
}

// Schutz gemeinsamer Personen (Runde 4): Eine Person, die ein eigenes aktives Konto hat
// oder an Wohnungen einer STWEG haengt, in der der Anfragende NICHT Ausschuss bzw.
// Verwaltung ist, darf er nicht umbenennen, umadressieren oder zusammenfuehren - sonst laesst sich
// per neuem Kontakt (findOrCreatePerson) + Personen-Bearbeitung die Identitaet eines
// Bewohners einer fremden STWEG uebernehmen (Trigger personen_propagate_to_kontakte).
async function personGeschuetztFuer(user, personId) {
  const groups = user?.groups || [];
  if (isTechnik(groups) || isPraesident(groups)) return false;
  const eigene = [...personenRechte.personenSchreibStwegs(groups)];
  const r = await pool.query(
    `SELECT EXISTS (SELECT 1 FROM wohnungen_kontakte k JOIN wohnungen w ON w.id = k.wohnung_id
                     WHERE k.person_id = $1 AND k.archiviert_am IS NULL AND NOT (w.stweg = ANY($2::int[]))) AS fremd_stweg,
            EXISTS (SELECT 1 FROM users u JOIN personen p ON p.id = $1
                     WHERE u.active IS NOT FALSE AND COALESCE(p.email, '') <> '' AND LOWER(u.email) = LOWER(p.email)) AS konto`,
    [personId, eigene]);
  const z = r.rows[0] || {};
  return !!(z.fremd_stweg || z.konto);
}

// STWEG-Scope fuer Personen-Lesezugriffe: null = alle (Technik/Praesident), sonst
// die STWEG-Nummern des Users. Sichtbar sind Personen mit Kontakt in einer dieser
// STWEGs sowie Personen ganz ohne Wohnungszuordnung (frisch angelegt, noch zu verknuepfen).
function personenScope(user) {
  const groups = user?.groups || [];
  if (isTechnik(groups) || isPraesident(groups)) return null;
  // inkl. der STWEG(s), die das Konto als Hausverwaltung betreut
  return [...getStwegsMitVerwaltung(groups)];
}
const PERSONEN_SCOPE_SQL = (n) => `(NOT EXISTS (SELECT 1 FROM wohnungen_kontakte k0 WHERE k0.person_id = p.id)
   OR EXISTS (SELECT 1 FROM wohnungen_kontakte k0 JOIN wohnungen w0 ON w0.id = k0.wohnung_id
               WHERE k0.person_id = p.id AND w0.stweg = ANY($${n}::int[])))`;

// Angaben, nach denen lib/nummernsicht.js entscheidet: E-Mail, Name und die
// STWEGs der (aktiven) Wohnungen der Person.
function personFuerSicht(p) {
  const stwegs = (Array.isArray(p?.wohnungen) ? p.wohnungen : [])
    .filter(w => w && !w.archiviert_am).map(w => w.stweg);
  return { email: p?.email, name: p?.name, stwegs };
}
async function darfNummernDerPerson(req, personId) {
  const r = await pool.query(
    `SELECT p.email, p.name, COALESCE(array_agg(DISTINCT w.stweg) FILTER (WHERE w.stweg IS NOT NULL), '{}') AS stwegs
       FROM personen p
       LEFT JOIN wohnungen_kontakte k ON k.person_id = p.id AND k.archiviert_am IS NULL
       LEFT JOIN wohnungen w ON w.id = k.wohnung_id
      WHERE p.id = $1 GROUP BY p.id`, [personId]);
  if (!r.rows[0]) return false;
  return darfEchteNummernSehen(req.user, r.rows[0], { kanal: nummernKanal(req) });
}

// GET /api/personen — Liste aller Personen mit ihren Wohnungen
app.get('/api/personen', authMiddleware, requireWohnungsverwaltungRead, async (req, res) => {
  try {
    const search = String(req.query.search || '').trim().toLowerCase();
    const params = [];
    let where = 'TRUE';
    if (search) {
      params.push(`%${search}%`);
      where = `(LOWER(p.name) LIKE $1 OR LOWER(COALESCE(p.email,'')) LIKE $1)`;
    }
    // Ausschuss/Bewohner nur eigene STWEG(s); Wohnungsliste ebenfalls beschraenkt
    const scope = personenScope(req.user);
    let wScope = '';
    if (scope) {
      params.push(scope);
      where += ` AND ${PERSONEN_SCOPE_SQL(params.length)}`;
      wScope = ` AND w.stweg = ANY($${params.length}::int[])`;
    }
    const r = await pool.query(
      `SELECT p.*,
              (SELECT COUNT(*) FROM wohnungen_kontakte k WHERE k.person_id = p.id AND k.archiviert_am IS NULL) AS n_wohnungen,
              (SELECT json_agg(json_build_object(
                 'wohnung_id', w.id, 'stweg', w.stweg, 'bezeichnung', w.bezeichnung,
                 'rolle', k.rolle, 'kontakt_id', k.id, 'archiviert_am', k.archiviert_am
               ) ORDER BY w.stweg, w.bezeichnung)
                 FROM wohnungen_kontakte k
                 JOIN wohnungen w ON w.id = k.wohnung_id
                WHERE k.person_id = p.id AND k.archiviert_am IS NULL${wScope}) AS wohnungen
         FROM personen p
        WHERE ${where}
        ORDER BY p.name LIMIT 1000`,
      params,
    );
    const sicht = await nummernSicht(req, pool);
    const g = req.user?.groups || [];
    // Geburtsdatum nur T/P, Notiz nur Ausschuss und T/P (lib/personen-rechte.js)
    res.json({ personen: r.rows.map(p => personenRechte.personFuerLeser(g, sicht(p, personFuerSicht(p)))),
      felder: personenRechte.personenFelder(g) });
  } catch (err) {
    console.error('Personen list error:', err);
    res.status(500).json({ error: 'Fehler beim Laden' });
  }
});

// GET /api/personen/:id — eine Person mit Details
app.get('/api/personen/:id', authMiddleware, requireWohnungsverwaltungRead, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isFinite(id)) return res.status(400).json({ error: 'Ungueltige ID' });
    const scope = personenScope(req.user);
    const params = [id];
    let where = 'p.id = $1', wScope = '';
    if (scope) {
      params.push(scope);
      where += ` AND ${PERSONEN_SCOPE_SQL(2)}`;
      wScope = ' AND w.stweg = ANY($2::int[])';
    }
    const r = await pool.query(
      `SELECT p.*,
              (SELECT json_agg(json_build_object(
                 'wohnung_id', w.id, 'stweg', w.stweg, 'bezeichnung', w.bezeichnung,
                 'rolle', k.rolle, 'kontakt_id', k.id, 'archiviert_am', k.archiviert_am
               ) ORDER BY w.stweg, w.bezeichnung)
                 FROM wohnungen_kontakte k JOIN wohnungen w ON w.id = k.wohnung_id
                WHERE k.person_id = p.id${wScope}) AS wohnungen
         FROM personen p WHERE ${where}`,
      params,
    );
    if (r.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const sicht = await nummernSicht(req, pool);
    const g = req.user?.groups || [];
    res.json({ ...personenRechte.personFuerLeser(g, sicht(r.rows[0], personFuerSicht(r.rows[0]))), felder: personenRechte.personenFelder(g) });
  } catch (err) {
    res.status(500).json({ error: fehlerFuerClient(err, 'Fehler beim Laden') });
  }
});

// PUT /api/personen/:id — Person aktualisieren (Trigger propagiert auf alle Kontakte)
app.put('/api/personen/:id', authMiddleware, requireWohnungsverwaltungWrite, kartenAdmin.mitKarteProtokollieren, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isFinite(id)) return res.status(400).json({ error: 'Ungueltige ID' });
    // H4: STWEG-Scope-Check: Ausschuss/Verwaltung nur Personen aus der eigenen STWEG
    const allowed = await userCanEditPerson(req.user, id);
    if (!allowed) return res.status(403).json({ error: 'Diese Person gehört nicht zu einer STWEG, für die du als Ausschuss oder Verwaltung zuständig bist' });
    // Felder, die das Konto nicht sieht (Geburtsdatum, Notiz), nicht ueberschreiben
    let b = personenRechte.personBodyFiltern(req.user?.groups || [], req.body || {});
    // Verborgene Nummern (GET liefert sie leer) beim Speichern nicht ueberschreiben
    if (!(await darfNummernDerPerson(req, id))) b = nummernAusBodyEntfernen(b);
    const IDENT_FELDER = ['name', 'vorname', 'nachname', 'email', 'telefon', 'mobile', 'telefone', 'adresse'];
    if (IDENT_FELDER.some(f => b[f] !== undefined) && await personGeschuetztFuer(req.user, id)) {
      return res.status(409).json({ error: 'Diese Person hat ein eigenes Konto oder Wohnungen in einer anderen STWEG. Name und Kontaktdaten aendert sie selbst im Profil oder die Technik.' });
    }
    if (b.email && !(isTechnik(req.user?.groups || []) || isPraesident(req.user?.groups || []))) {
      const fremd = await fremdeKennung(pool, { email: String(b.email), eigeneIds: [id] });
      if (fremd) return res.status(409).json({ error: fremd });
    }
    const updates = [];
    const params = [];
    const push = (col, val) => { params.push(val); updates.push(`${col} = $${params.length}`); };
    if (b.name !== undefined) push('name', String(b.name).slice(0, 255).trim() || null);
    if (b.vorname !== undefined) push('vorname', b.vorname ? String(b.vorname).slice(0, 120) : null);
    if (b.nachname !== undefined) push('nachname', b.nachname ? String(b.nachname).slice(0, 120) : null);
    if (b.anrede !== undefined) push('anrede', b.anrede ? String(b.anrede).slice(0, 20) : null);
    if (b.email !== undefined) push('email', b.email ? String(b.email).trim().slice(0, 255) : null);
    if (b.telefon !== undefined) push('telefon', normalizePhone(b.telefon ? String(b.telefon).slice(0, 60) : null));
    if (b.mobile !== undefined) push('mobile', normalizePhone(b.mobile ? String(b.mobile).slice(0, 60) : null));
    if (b.telefone !== undefined) {
      const t = Array.isArray(b.telefone) ? b.telefone.map(x => ({
        typ: String(x.typ || 'sonstige').slice(0, 30),
        label: x.label ? String(x.label).slice(0, 80) : null,
        nummer: normalizePhone(String(x.nummer || '').slice(0, 60)),
      })).filter(x => x.nummer) : [];
      push('telefone', JSON.stringify(t));
    }
    if (b.adresse !== undefined) push('adresse', b.adresse || null);
    if (b.geburtsdatum !== undefined) push('geburtsdatum', b.geburtsdatum || null);
    if (b.notiz !== undefined) push('notiz', b.notiz || null);
    if (b.review_needed !== undefined) push('review_needed', !!b.review_needed);
    if (updates.length === 0) return res.status(400).json({ error: 'Keine Änderungen' });
    const vorher = (await pool.query('SELECT * FROM personen WHERE id = $1', [id])).rows[0];
    params.push(id);
    const r = await pool.query(
      `UPDATE personen SET ${updates.join(', ')} WHERE id = $${params.length} RETURNING *`,
      params,
    );
    if (r.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const felder = personenRechte.geaenderteFelder(vorher, r.rows[0],
      ['name', 'vorname', 'nachname', 'anrede', 'email', 'telefon', 'mobile', 'telefone', 'adresse', 'geburtsdatum', 'notiz', 'review_needed']);
    await objProtokoll(req, 'personen', 'geaendert', `Person ${id}`, [r.rows[0].name, felder.length ? `Felder: ${felder.join(', ')}` : 'ohne Änderung']);

    // Verwaltung informieren wenn Email/Telefon/Adresse geaendert
    const relevantChanged = ['email', 'telefon', 'adresse'].some(f => b[f] !== undefined);
    if (relevantChanged) {
      try {
        const wRes = await pool.query(
          `SELECT DISTINCT w.stweg FROM wohnungen_kontakte k
             JOIN wohnungen w ON w.id = k.wohnung_id
            WHERE k.person_id = $1 AND k.archiviert_am IS NULL`,
          [id],
        );
        for (const row of wRes.rows) {
          const summary = `Kontaktdaten von ${r.rows[0].name} aktualisiert (gilt für alle ${wRes.rows.length} Wohnung(en) der Person)`;
          recordObjektChange(row.stweg, summary, req.user.email).catch(() => {});
        }
      } catch {}
    }
    res.json(personenRechte.personFuerLeser(req.user?.groups || [], r.rows[0]));
  } catch (err) {
    console.error('Personen update error:', err);
    res.status(500).json({ error: 'Fehler beim Aktualisieren' });
  }
});

