// GET /api/personen-dedup/kandidaten — moegliche Duplikate vorschlagen.
// Drei Heuristiken:
//   1. 'exakt': gleicher Name (LOWER+TRIM) → klare Dubletten
//   2. 'token': gleicher Token-Set (Vorname Nachname vs Nachname Vorname)
//   3. 'email': gleiche Email aber sehr aehnliche Namen
app.get('/api/personen-dedup/kandidaten', authMiddleware, requireWohnungsverwaltungWrite, async (req, res) => {
  try {
    // Ausschuss: Kandidaten nur aus eigenem STWEG-Scope (wie Liste/Merge)
    const scope = personenScope(req.user);
    const r = await pool.query(`
      WITH normed AS (
        SELECT id, name, email, telefon,
               LOWER(TRIM(name)) AS name_norm,
               -- Token-Set: alphabetisch sortierte Woerter (lower-case)
               (SELECT string_agg(t, ' ' ORDER BY t)
                  FROM unnest(string_to_array(LOWER(TRIM(name)), ' ')) AS t
                 WHERE t <> '') AS token_key
          FROM personen p
         WHERE ${scope ? PERSONEN_SCOPE_SQL(1) : 'TRUE'}
      ),
      exakt AS (
        SELECT 'exakt' AS art, name_norm AS schlüssel, 1 AS sort,
               array_agg(id ORDER BY id) AS ids, COUNT(*) AS n
          FROM normed GROUP BY name_norm HAVING COUNT(*) > 1
      ),
      token AS (
        -- Nur wenn Token-Set duplikat ist UND exakte Form nicht greift (sonst doppelte Anzeige)
        SELECT 'token' AS art, token_key AS schlüssel, 2 AS sort,
               array_agg(id ORDER BY id) AS ids, COUNT(*) AS n
          FROM normed
         WHERE token_key IS NOT NULL
         GROUP BY token_key HAVING COUNT(*) > 1
            AND COUNT(DISTINCT name_norm) > 1
      ),
      gleich_email AS (
        -- Email-Duplikate (Familien) mit unterschiedlichem Namen — kein Merge-Hinweis,
        -- nur als Info ob es echte Dubletten geben könnte (z.B. Tippfehler im Namen)
        SELECT 'email' AS art, LOWER(TRIM(email)) AS schlüssel, 3 AS sort,
               array_agg(id ORDER BY id) AS ids, COUNT(*) AS n
          FROM normed
         WHERE email IS NOT NULL AND email <> ''
         GROUP BY LOWER(TRIM(email))
        HAVING COUNT(*) > 1 AND COUNT(DISTINCT name_norm) > 1
      ),
      all_dups AS (
        SELECT * FROM exakt UNION ALL SELECT * FROM token UNION ALL SELECT * FROM gleich_email
      )
      SELECT art, schlüssel, ids, n,
             (SELECT json_agg(json_build_object(
                'id', p.id, 'name', p.name, 'email', p.email, 'telefon', p.telefon, 'mobile', p.mobile,
                'n_wohnungen', (SELECT COUNT(*) FROM wohnungen_kontakte k
                                  WHERE k.person_id = p.id AND k.archiviert_am IS NULL)
              ) ORDER BY p.id)
                FROM personen p WHERE p.id = ANY(ids)) AS personen
        FROM all_dups
       ORDER BY sort, n DESC, schlüssel
       LIMIT 200
    `, scope ? [scope] : []);
    // Kandidaten liegen im STWEG-Scope der Person (Portal: eigenes Haus); ueber
    // MCP/Apps nur interne Nummern.
    const sicht = await nummernSicht(req, pool);
    const kandidaten = r.rows.map(k => ({
      ...k, personen: (k.personen || []).map(p => sicht(p, { email: p.email, name: p.name, stwegs: scope || [] })),
    }));
    res.json({ kandidaten });
  } catch (err) {
    res.status(500).json({ error: fehlerFuerClient(err) });
  }
});

// POST /api/personen/merge — zwei Personen zusammenfuehren
// body: { keep_id, merge_id } — alle Kontakte von merge_id werden auf keep_id umgehaengt,
// merge_id wird geloescht. Daten aus merge_id ueberschreiben die in keep_id nur wenn keep_id-Feld leer ist.
app.post('/api/personen/merge', authMiddleware, requireWohnungsverwaltungWrite, kartenAdmin.bestaetigungVerlangen, async (req, res) => {
  const client = await pool.connect();
  try {
    const keepId = parseInt(req.body?.keep_id, 10);
    const mergeId = parseInt(req.body?.merge_id, 10);
    if (!Number.isFinite(keepId) || !Number.isFinite(mergeId) || keepId === mergeId) {
      return res.status(400).json({ error: 'keep_id und merge_id (verschieden) erforderlich' });
    }
    // H4: beide Personen müssen im Scope sein
    const [canKeep, canMerge] = await Promise.all([
      userCanEditPerson(req.user, keepId), userCanEditPerson(req.user, mergeId),
    ]);
    if (!canKeep || !canMerge) {
      return res.status(403).json({ error: 'Mindestens eine Person gehört nicht zu deinem STWEG-Scope' });
    }
    const [schutzKeep, schutzMerge] = await Promise.all([
      personGeschuetztFuer(req.user, keepId), personGeschuetztFuer(req.user, mergeId),
    ]);
    if (schutzKeep || schutzMerge) {
      return res.status(409).json({ error: 'Mindestens eine Person hat ein eigenes Konto oder Wohnungen in einer anderen STWEG - Zusammenfuehren nur durch die Technik.' });
    }
    await client.query('BEGIN');
    const k = await client.query('SELECT * FROM personen WHERE id = $1', [keepId]);
    const m = await client.query('SELECT * FROM personen WHERE id = $1', [mergeId]);
    if (k.rows.length === 0 || m.rows.length === 0) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Person(en) nicht gefunden' });
    }
    // Fields aus merge → keep falls keep leer
    const fields = ['vorname','nachname','anrede','email','telefon','mobile','adresse','geburtsdatum','notiz'];
    const updates = [];
    const params = [];
    for (const f of fields) {
      if (!k.rows[0][f] && m.rows[0][f]) {
        params.push(m.rows[0][f]);
        updates.push(`${f} = $${params.length}`);
      }
    }
    if (updates.length > 0) {
      params.push(keepId);
      await client.query(`UPDATE personen SET ${updates.join(', ')}, updated_at = NOW() WHERE id = $${params.length}`, params);
    }
    // Alle Verweise umhaengen: Wohnungs-Kontakte, Vollmachten (Geber, Bevollmaechtigte),
    // Reklamationen, WhatsApp, Rufgruppen-Mitglieder (lib/personen-rechte.js) -
    // sonst setzt das Loeschen sie still auf NULL.
    const umgehaengt = await personenRechte.verweiseUmhaengen(client, keepId, mergeId);
    // Merge-Person löschen
    await client.query('DELETE FROM personen WHERE id = $1', [mergeId]);
    // Protokoll in derselben Transaktion: ohne Eintrag kein Zusammenfuehren
    await adminProtokoll.eintragen(pool, client, req, {
      bereich: 'personen', aktion: 'zusammengefuehrt', ziel: `Person ${keepId}`, alt: `Person ${mergeId}`, neu: `Person ${keepId}`,
      detail: [k.rows[0].name, m.rows[0].name !== k.rows[0].name ? `aus: ${m.rows[0].name}` : null,
        Object.entries(umgehaengt).filter(([, n]) => n > 0).map(([t, n]) => `${t} ${n}`).join(', ') || 'keine Verweise'].filter(Boolean).join(' · '),
    });
    await client.query('COMMIT');
    res.json({ success: true, reassigned_kontakte: umgehaengt['wohnungen_kontakte.person_id'] || 0, umgehaengt });
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    console.error('Personen merge error:', err);
    res.status(500).json({ error: fehlerFuerClient(err, 'Merge fehlgeschlagen') });
  } finally {
    client.release();
  }
});

// ─── Ad-hoc Mail-Composer ─────────────────────────────────────────────
// Erlaubt das Schreiben einer freien Mail an einen beliebigen Empfänger
// (entweder direkt eingegeben oder aus mail_empfaenger-Stammdaten gewaehlt).
// Geht durch den gleichen Genehmigungs-Workflow wie automatische Mails.
// Attachments werden inline base64 in der Queue gespeichert.
app.post('/api/mail-compose', authMiddleware, requirePermission('mail-compose', 'write'), async (req, res) => {
  try {
    // H1: Rate-Limit gegen Mail-Spam-Abuse — 50 Mails / Stunde pro User
    const rl = rateLimitGuard('mail-compose', (req.user.email || 'anon').toLowerCase(), 50, 60 * 60 * 1000);
    if (!rl.ok) {
      return res.status(429).json({ error: `Rate-Limit erreicht (max 50 Mails/h). Bitte ${Math.ceil(rl.retryAfter / 60)} Min warten.` });
    }
    const b = req.body || {};

    // Empfänger entweder direkt (mail_to) oder via Stammdaten (empfaenger_id)
    let mailTo = b.mail_to;
    let mailCc = b.mail_cc;
    let mailReplyTo = b.mail_reply_to;
    // Freigabe-Pflicht bestimmt der Server, nie der Client (requires_approval im Body
    // wird ignoriert): Direktversand nur an einen Stammempfaenger mit Direktversand,
    // dessen Adressen nicht veraendert wurden — auch fuer Technik/Praesident, damit
    // freie Mails immer durchs Vier-Augen-Prinzip (Outbox) gehen.
    let requiresApproval = true;
    let sourceType = 'ad-hoc';
    let sourceId = null;
    let firma = null;

    if (b.empfaenger_id) {
      const empfId = parseInt(b.empfaenger_id, 10);
      const er = await pool.query('SELECT * FROM mail_empfaenger WHERE id = $1 AND aktiv = true', [empfId]);
      if (er.rows.length === 0) return res.status(404).json({ error: 'Empfänger nicht gefunden oder inaktiv' });
      const e = er.rows[0];
      firma = e.name;
      sourceType = `ad-hoc-${e.kategorie}`;
      sourceId = e.id;
      if (!mailTo) mailTo = e.email ? [e.email] : [];
      if (!mailCc) {
        const kontaktEmails = (e.kontakte || []).map(k => k.email).filter(Boolean);
        const def = (e.default_cc || '').split(',').map(s => s.trim()).filter(Boolean);
        mailCc = [...def, ...kontaktEmails].filter((v, i, a) => v && a.indexOf(v) === i);
      }
      if (!mailReplyTo) mailReplyTo = e.default_reply_to || null;
      if (requiresApproval && e.requires_approval === false) {
        // Nur Adressen aus dem Stammdatensatz zulassen, sonst Outbox.
        const adrListe = v => (Array.isArray(v) ? v : String(v || '').split(','))
          .map(s => String(s).trim().toLowerCase()).filter(Boolean);
        const erlaubt = new Set(adrListe([e.email, ...(e.default_cc || '').split(','),
          ...(e.kontakte || []).map(k => k && k.email)].filter(Boolean)));
        const adressenOk = [...adrListe(mailTo), ...adrListe(mailCc)].every(a => erlaubt.has(a));
        // default_reply_to kann mehrere Adressen enthalten -> als Menge vergleichen
        const erlaubtReply = new Set(adrListe(e.default_reply_to));
        const replyOk = adrListe(mailReplyTo).every(a => erlaubtReply.has(a));
        if (adressenOk && replyOk) requiresApproval = false;
      }
    }

    if (!mailTo || (Array.isArray(mailTo) ? mailTo.length === 0 : !String(mailTo).trim())) {
      return res.status(400).json({ error: 'Empfänger (mail_to oder empfaenger_id) erforderlich' });
    }
    if (!b.subject || !String(b.subject).trim()) return res.status(400).json({ error: 'Betreff erforderlich' });
    if (!b.body_text || !String(b.body_text).trim()) return res.status(400).json({ error: 'Text erforderlich' });

    // Attachments: erwarten Liste [{filename, content_base64}]
    const attachments = [];
    for (const a of (b.attachments || [])) {
      if (!a.filename || !a.content_base64) continue;
      const sizeApprox = Math.floor(a.content_base64.length * 0.75);
      if (sizeApprox > 20 * 1024 * 1024) return res.status(400).json({ error: `Anhang ${a.filename} > 20 MB` });
      attachments.push({
        filename: String(a.filename).slice(0, 255),
        size: sizeApprox,
        content_base64: a.content_base64,
        docs_path: null,
      });
    }

    if (requiresApproval) {
      const queueId = await enqueueVerwaltungMail({
        source_type: sourceType,
        source_id: sourceId,
        mailTo, mailCc, mailReplyTo,
        subject: String(b.subject).trim().slice(0, 500),
        bodyText: String(b.body_text).slice(0, 100000),
        attachments,
        createdBy: req.user.email,
        createdById: req.user.id || req.user.user_id || null,
      });
      res.json({ ok: true, queued: true, queue_id: queueId, firma, requires_approval: true });
    } else {
      // Direktversand ohne Freigabe (z.B. an interne Empfänger)
      const toStr = Array.isArray(mailTo) ? mailTo.join(', ') : String(mailTo);
      const ccStr = Array.isArray(mailCc) ? mailCc.join(', ') : (mailCc ? String(mailCc) : undefined);
      const liveAttachments = attachments.map(a => ({
        filename: a.filename,
        content: Buffer.from(a.content_base64, 'base64'),
      }));
      await loggedSendMail({
        from: MAIL_FROM, to: toStr, cc: ccStr, replyTo: mailReplyTo || undefined,
        subject: String(b.subject).trim(),
        text: String(b.body_text),
        attachments: liveAttachments,
      }, sourceType);
      res.json({ ok: true, queued: false, firma, requires_approval: false });
    }
  } catch (err) {
    console.error('Mail-compose error:', err);
    res.status(500).json({ error: fehlerFuerClient(err, 'Fehler beim Einstellen/Versand') });
  }
});

// ─── Mail-Templates ────────────────────────────────────────────────
// Erlaubt es, Subject/Body für ausgehende Mails pro source_type
// (+ optional Empfänger-Kategorie) zu konfigurieren statt hartcodiert.
// Platzhalter-Syntax: {{path.to.field}}, z.B. {{auslage.betrag_chf}}.
// Erweiterte Helpers: {{#if x}}…{{/if}}, {{date x}}, {{chf x}}.

function tplGet(obj, path) {
  if (!path) return '';
  const parts = String(path).split('.');
  let cur = obj;
  for (const p of parts) {
    if (cur == null) return '';
    cur = cur[p];
  }
  return cur == null ? '' : cur;
}

function tplFormat(value, helper) {
  if (value == null) return '';
  switch (helper) {
    case 'chf':
      return 'CHF ' + Number(value).toLocaleString('de-CH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    case 'date':
      try { return new Date(value).toLocaleDateString('de-CH'); } catch { return String(value); }
    case 'datetime':
      try { return new Date(value).toLocaleString('de-CH'); } catch { return String(value); }
    case 'upper':
      return String(value).toUpperCase();
    case 'lower':
      return String(value).toLowerCase();
    default:
      return String(value);
  }
}

function renderTemplate(template, context) {
  if (!template) return '';
  let out = String(template);
  // {{#each path}}…{{/each}} — Array iterieren. Item-Kontext: Objektfelder gemerged
  // ({{feld}}), zusätzlich {{this}} (Primitive), {{@nr}} (1-basiert), {{@index}}.
  out = out.replace(/\{\{#each\s+([^}]+?)\s*\}\}([\s\S]*?)\{\{\/each\}\}/g, (m, path, body) => {
    const arr = tplGet(context, path.trim());
    if (!Array.isArray(arr)) return '';
    return arr.map((item, i) => {
      const itemCtx = (item && typeof item === 'object')
        ? { ...context, ...item, this: item, '@index': i, '@nr': i + 1 }
        : { ...context, this: item, '@index': i, '@nr': i + 1 };
      return renderTemplate(body, itemCtx);
    }).join('');
  });
  // {{#if path}}…{{/if}} — einfacher Bedingungsblock (nur top-level, kein nested)
  out = out.replace(/\{\{#if\s+([^}]+?)\s*\}\}([\s\S]*?)\{\{\/if\}\}/g, (m, path, body) => {
    return tplGet(context, path.trim()) ? body : '';
  });
  // {{helper path}} oder {{path}}
  out = out.replace(/\{\{\s*([^}]+?)\s*\}\}/g, (m, expr) => {
    const parts = expr.trim().split(/\s+/);
    if (parts.length >= 2) {
      // helper path
      return tplFormat(tplGet(context, parts.slice(1).join(' ')), parts[0]);
    }
    return tplFormat(tplGet(context, parts[0]), null);
  });
  return out;
}

// Findet Template-Match. Reihenfolge: source_type + kategorie spezifisch,
// dann source_type allgemein. Returns null wenn kein Template aktiv.
async function findMailTemplate(sourceType, empfaengerKategorie) {
  const r = await pool.query(
    `SELECT * FROM mail_templates
      WHERE aktiv = true
        AND source_type = $1
        AND (empfaenger_kategorie = $2 OR empfaenger_kategorie IS NULL)
      ORDER BY (empfaenger_kategorie = $2) DESC NULLS LAST
      LIMIT 1`,
    [sourceType, empfaengerKategorie || null],
  );
  return r.rows[0] || null;
}

// Versendet eine Mail ueber das Template-System: existiert ein aktives Template fuer den
// Trigger (= source_type) [+ optional context.empfaenger_kategorie], wird Subject/Body daraus
// gerendert; sonst der mitgegebene Inline-Fallback (mailOpts.subject/text). Loggt wie gehabt.
async function sendTemplated(trigger, context, mailOpts, extra = {}) {
  let subject = mailOpts.subject, text = mailOpts.text, html = mailOpts.html;
  try {
    const tpl = await findMailTemplate(trigger, (context && context.empfaenger_kategorie) || null);
    if (tpl) {
      if (tpl.subject_template) subject = renderTemplate(tpl.subject_template, context || {});
      if (tpl.body_template) text = renderTemplate(tpl.body_template, context || {});
      if (tpl.body_html_template) html = renderTemplate(tpl.body_html_template, context || {});
    }
  } catch (e) { console.error('[sendTemplated]', trigger, e.message); }
  const opts = { ...mailOpts, subject, text };
  if (html) opts.html = html; else delete opts.html;
  return loggedSendMail(opts, trigger, extra);
}

