    const r = await pool.query(
      `SELECT id, name, phone, enabled, is_temporary, valid_until, priority, person_id, added_by, notiz, created_at, updated_at
         FROM pbx_ring_members
        ORDER BY priority, name`
    );
    res.json({ members: r.rows });
