// Ob ein Container laeuft, sagt wenig. Am 1. September 2026 stand
// Nextcloud wochenlang im Wartungsmodus — CT 104 lief die ganze Zeit,
// das NOC zeigte "web: gruen", und unbenutzbar war es trotzdem. Darum
// hier die Frage, die zaehlt: Antwortet der Dienst, und ist er brauchbar?
const NEXTCLOUD_URL = process.env.NEXTCLOUD_URL || 'http://100.64.2.36';
async function nextcloudZustand() {
  try {
    const r = await fetch(`${NEXTCLOUD_URL}/status.php`, { signal: AbortSignal.timeout(4000) });
    if (!r.ok) return { erreichbar: false, ok: false, grund: `HTTP ${r.status}` };
    const d = await r.json();
    const ok = d.installed === true && d.maintenance === false && d.needsDbUpgrade === false;
    return {
      erreichbar: true, ok,
      version: d.versionstring || null,
      maintenance: d.maintenance === true,
      needsDbUpgrade: d.needsDbUpgrade === true,
      grund: ok ? null : (d.maintenance ? 'Wartungsmodus' : d.needsDbUpgrade ? 'Datenbank-Migration offen' : 'nicht installiert'),
    };
  } catch (e) { return { erreichbar: false, ok: false, grund: e.message }; }
}

// Was SMTP2GO selbst ueber den laufenden Zyklus sagt — mit kurzem Cache,
// damit der Wandbildschirm die API nicht alle paar Sekunden fragt. Die eigene
// Tabelle isp_outbound_usage ist nur die Aufschluesselung nach Absenderdomaene;
// sie zaehlte bis 5.9.2026 auch Sendungen ueber den eigenen Relay mit und stand
// bei 199, waehrend SMTP2GO 1 meldete. Bei Abweichung gilt SMTP2GO.
const smtp2goZyklusCache = { at: 0, data: null };
async function smtp2goZyklus() {
  if (!SMTP2GO_API_KEY) return null;
  if (Date.now() - smtp2goZyklusCache.at < 5 * 60_000) return smtp2goZyklusCache.data;
  try {
    const r = await fetch(`${SMTP2GO_API_URL}/stats/email_summary`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ api_key: SMTP2GO_API_KEY }), signal: AbortSignal.timeout(8000),
    });
    const d = (await r.json()).data || {};
    smtp2goZyklusCache.data = { used: d.cycle_used || 0, max: d.cycle_max || 0, cycle_start: d.cycle_start, cycle_end: d.cycle_end };
  } catch (e) {
    console.warn('[noc] SMTP2GO-Zyklus nicht abrufbar:', e.message);
    smtp2goZyklusCache.data = null;
  }
  smtp2goZyklusCache.at = Date.now();
  return smtp2goZyklusCache.data;
}

async function nocDashboardHandler(req, res) {
  try {
    const ym = new Date().toISOString().slice(0, 7);
    // Outbound: Aufschluesselung aus der eigenen Tabelle, Gesamtzahl von SMTP2GO
    const [out, zyklus, relayZustand] = await Promise.all([
      pool.query(`SELECT sender_domain, count FROM isp_outbound_usage WHERE year_month=$1 ORDER BY count DESC`, [ym]),
      smtp2goZyklus(),
      pool.query('SELECT host, zeit, queue_total, deferred, active, oldest_s, last_sent_at FROM mail_relay_status ORDER BY host').catch(() => ({ rows: [] })),
    ]);
    const tabelleTotal = out.rows.reduce((a, r) => a + r.count, 0);
    const topSenders = out.rows.slice(0, 5);
    const QUOTA = (zyklus && zyklus.max) || 1000;
    const monthlyTotal = zyklus ? zyklus.used : tabelleTotal;
    const quotaPct = QUOTA > 0 ? Math.min(999, Math.round(monthlyTotal / QUOTA * 100)) : 0;

    // Was die Dienstwacht offen hat — die Zahl gehoert neben die anderen,
    // sonst schaut niemand hin. Ein leeres Feld ist die gute Nachricht.
    let befunde = 0;
    try {
      const b = await pool.query('SELECT count(*)::int AS n FROM dienst_wacht');
      befunde = b.rows[0]?.n || 0;
    } catch {}
    const nc = await nextcloudZustand();

    // Aktive Mail-Relays + Smarthost-Anzahl
    const relays = await pool.query(
      `SELECT COUNT(*) FILTER (WHERE active) AS active_count,
              COUNT(*) FILTER (WHERE outbound_via_smarthost) AS smarthost_count,
              COUNT(*) FILTER (WHERE mailcow_managed) AS managed_count,
              COUNT(*) AS total FROM isp_mail_relays`);
    const relayStats = relays.rows[0];

    // Pending Mailbox-Anträge
    const pending = (await pool.query(
      `SELECT COUNT(*)::int AS n FROM mailbox_requests WHERE status='pending'`)).rows[0].n;

    // Pending VLAN-Anträge
    let pendingVlan = 0;
    try {
      pendingVlan = (await pool.query(
        `SELECT COUNT(*)::int AS n FROM isp_vlan_requests WHERE status='pending'`)).rows[0].n;
    } catch {}

    // Aktive VPN-Konten (active=true) + pending (active=false) + jetzt verbunden
    // (Handshake innerhalb der letzten 3 Min — WireGuard-Standard fuer eine
    // lebende Session, jenseits davon gilt der Peer als idle/disconnected).
    let vpnActive = 0, vpnPending = 0, vpnConnected = 0;
    try {
      const r = await pool.query(
        `SELECT COUNT(*) FILTER (WHERE active) AS act,
                COUNT(*) FILTER (WHERE NOT active AND gesperrt_am IS NULL) AS pen
           FROM isp_vpn_accounts`);
      vpnActive = parseInt(r.rows[0].act, 10) || 0;
      vpnPending = parseInt(r.rows[0].pen, 10) || 0;
    } catch {}
    if (WG_CONTROL_TOKEN) {
      try {
        const r = await wgControl('GET', '/peers');
        const body = await r.json();
        const peers = Array.isArray(body) ? body : (body.peers || []);
        const cutoff = Date.now() - 3 * 60 * 1000;
        vpnConnected = peers.filter(p => {
          const h = p.latest_handshake ? new Date(p.latest_handshake).getTime() : 0;
          return h > cutoff;
        }).length;
      } catch {}
    }

    // Aktive Subscribers (Erschliessungen)
    let subsActive = 0;
    try {
      subsActive = (await pool.query(
        `SELECT COUNT(*)::int AS n FROM isp_subscribers WHERE status='aktiv'`)).rows[0].n;
    } catch {}

    res.json({
      year_month: ym,
      outbound: {
        monthly_total: monthlyTotal,
        quota_limit: QUOTA,
        quota_pct: quotaPct,
        top_senders: topSenders,
        quelle: zyklus ? 'smtp2go' : 'tabelle',
        tabelle_total: tabelleTotal,
        zyklus: zyklus ? { von: zyklus.cycle_start, bis: zyklus.cycle_end } : null,
      },
      // Warteschlangen der Mailhosts, gemeldet vom Usage-Tracker (PMG, Relay-VPS)
      relay_status: relayZustand.rows.map(r => ({ ...r, alter_s: Math.round((Date.now() - new Date(r.zeit).getTime()) / 1000) })),
      relays: relayStats,
      pending: { mailbox_requests: pending, vlan_requests: pendingVlan },
      counts: {
        vpn_active: vpnActive,
        vpn_pending: vpnPending,
        vpn_connected: vpnConnected,
        subscribers_active: subsActive,
        dienst_befunde: befunde,
      },
      nextcloud: nc,
    });
  } catch (err) { res.status(500).json({ error: err.message }); }
}
app.get('/api/isp/noc/dashboard', authMiddleware, requireTechnikOrPraesident, nocDashboardHandler);

// ── Anschluesse: was reserviert ist, trifft auf das, was wirklich da ist ──
// Jeder Anschluss traegt seine Reservierung selbst: fixed_ip und mac_dot1x in
// isp_subscribers. (isp_fixed_ips ist eine andere Sache — Service- und
// Wohnungs-IPs.) Drei Zustaende:
//
//   aktiv         das reservierte Geraet ist da, unter seiner Adresse
//   provisioniert eingetragen, aber nichts zu sehen — oder gesehen und noch
//                 ohne Adresse, was direkt nach einer VLAN-Umstellung vorkommt,
//                 solange die alte Lease laeuft
//   fehler        ein Widerspruch: fremde MAC auf der reservierten Adresse,
//                 oder die reservierte MAC unter einer anderen Adresse
//
// Ohne hinterlegte MAC gibt es keinen Widerspruch und darum nie 'fehler';
// mac_hinterlegt macht diese Luecke sichtbar, statt sie durchgehen zu lassen.
async function anschlussZeilen(nurWohnungen) {
  const r = await pool.query(
    `SELECT s.id, s.status, s.vlan, s.switch_name, s.switch_port, s.anschluss_typ,
            s.bandbreite_down_mbps, s.bandbreite_up_mbps, s.wohnung_id,
            HOST(s.fixed_ip) AS fixed_ip, LOWER(s.mac_dot1x) AS mac,
            w.bezeichnung AS wohnung, w.stweg
       FROM isp_subscribers s LEFT JOIN wohnungen w ON w.id = s.wohnung_id
      ${Array.isArray(nurWohnungen) ? 'WHERE s.wohnung_id = ANY($1::int[])' : ''}
      ORDER BY s.id`,
    Array.isArray(nurWohnungen) ? [nurWohnungen] : []);
  return r.rows;
}

// maske(24) -> '255.255.255.0'
function maskeAusPraefix(p) {
  if (!Number.isFinite(p) || p < 0 || p > 32) return null;
  const b = [0, 0, 0, 0];
  for (let i = 0; i < p; i++) b[Math.floor(i / 8)] |= 1 << (7 - (i % 8));
  return b.join('.');
}

// opt.statisch: nur fuer die eigene Sicht — Gateway, Maske und DNS sind
// Angaben, die man zum Einrichten braucht, nicht fuers Wandbild.
function bewerteAnschluesse(subs, sicht, opt) {
  const clients = (sicht && sicht.clients) || [];
  const devices = (sicht && sicht.devices) || [];
  const netzeNachVlan = new Map();
  for (const n of ((sicht && sicht.networks) || [])) if (n.vlan) netzeNachVlan.set(Number(n.vlan), n);
  const switchName = new Map();
  for (const dev of devices) if (dev.mac) switchName.set(String(dev.mac).toLowerCase(), String(dev.name || dev.mac));
  const vonMac = new Map(), vonIp = new Map();
  for (const cl of clients) {
    if (cl.mac) vonMac.set(String(cl.mac).toLowerCase(), cl);
    if (cl.ip) vonIp.set(String(cl.ip), cl);
  }
  const wo = (cl) => [cl.hostname || cl.name, cl.network, cl.vlan ? 'VLAN ' + cl.vlan : null].filter(Boolean).join(', ');

  return subs.map(sub => {
    const mac = sub.mac ? String(sub.mac).toLowerCase() : null;
    const amPort = clients.filter(cl => {
      if (sub.vlan && Number(cl.vlan) === Number(sub.vlan)) return true;
      if (sub.switch_port && sub.switch_name && String(cl.sw_port) === String(sub.switch_port)) {
        const n = switchName.get(String(cl.sw_mac || '').toLowerCase()) || '';
        if (n && n.toLowerCase() === String(sub.switch_name).toLowerCase()) return true;
      }
      return false;
    });
    const netz = sub.vlan ? netzeNachVlan.get(Number(sub.vlan)) : null;
    // Was man braucht, um das Geraet von Hand einzurichten. Ohne eigenen
    // DNS im Netz verteilt UniFi den Gateway — dann steht der hier auch.
    let statischeAngaben = null;
    if (netz && netz.ip_subnet) {
      const [gw, pr] = String(netz.ip_subnet).split('/');
      const dns = netz.dhcpd_dns_enabled
        ? [netz.dhcpd_dns_1, netz.dhcpd_dns_2, netz.dhcpd_dns_3, netz.dhcpd_dns_4].filter(Boolean)
        : [gw];
      statischeAngaben = {
        ip: sub.fixed_ip || null, praefix: parseInt(pr, 10) || null,
        maske: maskeAusPraefix(parseInt(pr, 10)), gateway: gw, dns,
        domain: netz.domain_name || null, netz: netz.name,
      };
    }
    const meins = mac ? vonMac.get(mac) : null;
    const aufIp = sub.fixed_ip ? vonIp.get(String(sub.fixed_ip)) : null;
    let zustand, grund;
    if (!mac) {
      zustand = amPort.length ? 'aktiv' : 'provisioniert';
      grund = (amPort.length ? amPort.length + ' Gerät(e) im VLAN' : 'kein Gerät gesehen') + ', keine MAC hinterlegt';
    } else if (aufIp && String(aufIp.mac || '').toLowerCase() !== mac) {
      zustand = 'fehler';
      grund = `fremde MAC auf ${sub.fixed_ip}: ${aufIp.mac}${aufIp.hostname ? ' (' + aufIp.hostname + ')' : ''} statt ${mac}`;
    } else if (meins && !meins.ip) {
      zustand = 'provisioniert';
      grund = `Gerät gesehen (${wo(meins)}), aber noch ohne Adresse`
        + (sub.fixed_ip ? `; erwartet ${sub.fixed_ip} — solange die alte Lease läuft, bleibt das so` : '');
    } else if (meins && sub.fixed_ip && meins.ip && String(meins.ip) !== String(sub.fixed_ip)) {
      zustand = 'fehler';
      const fremdesNetz = sub.vlan && meins.vlan && Number(meins.vlan) !== Number(sub.vlan);
      grund = `reservierte MAC läuft unter ${meins.ip} statt ${sub.fixed_ip} (${wo(meins)})`
        + (fremdesNetz ? ` — falsches Netz, erwartet VLAN ${sub.vlan}` : '');
    } else if (meins) {
      zustand = 'aktiv';
      grund = `Gerät da${meins.ip ? ' unter ' + meins.ip : ''}${meins.hostname ? ' (' + meins.hostname + ')' : ''}`;
    } else {
      zustand = 'provisioniert';
      grund = amPort.length ? `reserviertes Gerät fehlt, ${amPort.length} andere(s) im VLAN` : 'kein Gerät gesehen';
    }
    return {
      id: sub.id,
      label: sub.wohnung || sub.switch_name || ('VLAN ' + (sub.vlan ?? '?')),
      stweg: sub.stweg, status: sub.status, vlan: sub.vlan, typ: sub.anschluss_typ,
      switch: sub.switch_name, port: sub.switch_port,
      down_mbps: sub.bandbreite_down_mbps, up_mbps: sub.bandbreite_up_mbps,
      reserviert_ip: sub.fixed_ip, mac_hinterlegt: !!mac,
      netz_name: netz ? netz.name : null,
      clients: amPort.length, zustand, grund,
      ...(opt && opt.statisch ? { statisch: statischeAngaben } : {}),
    };
  });
}

// Die Netze aendern sich selten; fuenf Minuten Cache genuegen.
const unifiNetzeCache = { at: 0, data: [] };
async function unifiNetze() {
  if (Date.now() - unifiNetzeCache.at < 300000) return unifiNetzeCache.data;
  try { unifiNetzeCache.data = (await unifiGet('rest/networkconf')).data || []; }
  catch (e) { console.warn('[isp] unifiNetze:', e.message); }
  unifiNetzeCache.at = Date.now();
  return unifiNetzeCache.data;
}

// Kurz gecachte UniFi-Sicht, damit die Bewohnerseite die UDM nicht bei jedem
// Aufruf erneut befragt — das NOC bringt seine eigene Sicht ohnehin mit.
const unifiSichtCache = { at: 0, data: { clients: [], devices: [] } };
async function unifiSicht() {
  if (Date.now() - unifiSichtCache.at < 20000) return unifiSichtCache.data;
  try {
    const [c, d, n] = await Promise.all([
      unifiGet('stat/sta'),
      unifiGet('stat/device-basic').catch(() => unifiGet('stat/device')),
      unifiNetze(),
    ]);
    unifiSichtCache.data = { clients: c.data || [], devices: d.data || [], networks: n };
  } catch (e) { console.warn('[isp] unifiSicht:', e.message); }
  unifiSichtCache.at = Date.now();
  return unifiSichtCache.data;
}

// UniFi-Metriken für NOC-Cockpit (Geräte, Clients, WAN, WLANs, Top-APs)
async function unifiGet(path, timeoutMs = 4000) {
  const r = await fetch(`${UNIFI_HOST}/proxy/network/api/s/default/${path}`, {
    headers: { 'X-API-Key': UNIFI_API_KEY },
    signal: AbortSignal.timeout(timeoutMs),
  });
  if (!r.ok) throw new Error(`unifi ${path} -> ${r.status}`);
  return r.json();
}

async function unifiCall(method, path, body, timeoutMs = 8000) {
  const opts = {
    method,
    headers: { 'X-API-Key': UNIFI_API_KEY, 'Content-Type': 'application/json' },
    signal: AbortSignal.timeout(timeoutMs),
  };
  if (body !== undefined) opts.body = JSON.stringify(body);
  const r = await fetch(`${UNIFI_HOST}/proxy/network/api/s/default/${path}`, opts);
  const text = await r.text();
  let json;
  try { json = JSON.parse(text); } catch { json = { raw: text }; }
  if (!r.ok) throw new Error(`unifi ${method} ${path} -> ${r.status} ${text.slice(0, 200)}`);
  return json;
}

async function nocUnifiHandler(req, res) {
  const out = {
    reachable: false,
    devices: { total: 0, online: 0, offline: 0, by_type: {} },
    clients: { total: 0, wireless: 0, wired: 0, guest: 0 },
    wlans: { total: 0, enabled: 0 },
    wan: { up: false, ip: null, uptime_s: null, gw_name: null },
    top_aps: [],
    health: [],
    routers: [],
    frontends: [],
    error: null,
  };
  try {
    // Site-Health (subsystems: wlan, lan, wan, www, vpn) — gibt Status pro Subsystem
    try {
      const h = await unifiGet('stat/health');
      out.health = (h.data || []).map(x => ({
        subsystem: x.subsystem,
        status: x.status,
        num_user: x.num_user || 0,
        num_guest: x.num_guest || 0,
        num_ap: x.num_ap || 0,
        num_sw: x.num_sw || 0,
        num_gw: x.num_gw || 0,
        wan_ip: x.wan_ip || null,
        gw_name: x.gw_name || null,
        uptime: x.uptime || null,
        'rx_bytes-r': x['rx_bytes-r'] || 0,
        'tx_bytes-r': x['tx_bytes-r'] || 0,
      }));
      // WAN-Daten aus health-Response — UDM legt uptime in uptime_stats.WAN.uptime,
      // www-subsystem hat top-level uptime (Internet-uplink).
      const rawWan = (h.data || []).find(x => x.subsystem === 'wan');
      if (rawWan) {
        out.wan.up = rawWan.status === 'ok';
        out.wan.ip = rawWan.wan_ip || null;
        out.wan.gw_name = rawWan.gw_name || null;
        out.wan.uptime_s =
          rawWan?.uptime_stats?.WAN?.uptime ||
          rawWan?.['gw_system-stats']?.uptime || null;
      }
      const rawWww = (h.data || []).find(x => x.subsystem === 'www');
      if (rawWww) {
        if (!out.wan.up) out.wan.up = rawWww.status === 'ok';
        if (!out.wan.uptime_s) out.wan.uptime_s = rawWww.uptime || null;
      }
    } catch (e) { /* health-fehler nicht fatal */ }

    // Devices. Gekapselt: ein UniFi-Fehler (z.B. 401 bei ungueltigem API-Key)
    // darf NICHT den ganzen Handler abbrechen — sonst fehlt auch das davon
    // unabhaengige Router- + Frontend-Monitoring. reachable bleibt dann false.
    let alleGeraete = [], alleClients = [];   // fuer den Anschluss-Abgleich weiter unten
    try {
      const d = await unifiGet('stat/device-basic').catch(() => unifiGet('stat/device'));
      const devs = d.data || [];
      alleGeraete = devs;
      out.reachable = true;
      out.devices.total = devs.length;
      for (const dev of devs) {
        const t = (dev.type || 'unknown').toLowerCase(); // uap, usw, ugw, udm, uxg
        const online = (dev.state === 1) || (dev.state === '1');
        if (online) out.devices.online++; else out.devices.offline++;
        const tk = ({uap:'ap', usw:'switch', ugw:'gateway', udm:'gateway', uxg:'gateway'})[t] || t;
        out.devices.by_type[tk] = out.devices.by_type[tk] || { total: 0, online: 0 };
        out.devices.by_type[tk].total++;
        if (online) out.devices.by_type[tk].online++;
      }
    } catch (e) { out.error = 'unifi stat/device -> ' + e.message; }
    // Top-APs nach Client-Count (nur wenn full device-Info verfuegbar)
    try {
      const full = await unifiGet('stat/device');
      const aps = (full.data || []).filter(x => (x.type || '').toLowerCase() === 'uap' && x.state === 1);
      aps.sort((a, b) => (b.num_sta || 0) - (a.num_sta || 0));
      out.top_aps = aps.slice(0, 5).map(a => ({
        name: a.name || a.mac,
        num_sta: a.num_sta || 0,
        model: a.model || null,
      }));
    } catch {}

    // Clients (active)
    try {
      const c = await unifiGet('stat/sta');
      const clients = c.data || [];
      alleClients = clients;
      out.clients.total = clients.length;
      for (const cl of clients) {
        if (cl.is_wired) out.clients.wired++; else out.clients.wireless++;
        if (cl.is_guest) out.clients.guest++;
      }
    } catch {}

    // Anschluesse bewerten — dieselbe Funktion bedient die Bewohnerseite.
    try {
      out.anschluesse = bewerteAnschluesse(await anschlussZeilen(),
        { clients: alleClients, devices: alleGeraete, networks: await unifiNetze() });
    } catch (e) { console.warn('[noc] anschluesse:', e.message); }

    // WLANs
    try {
      const w = await unifiGet('rest/wlanconf');
      const wlans = w.data || [];
      out.wlans.total = wlans.length;
      out.wlans.enabled = wlans.filter(x => x.enabled).length;
    } catch {}

    // Router-LXC-Health: parallel auf alle aktiven Router pingen, pro Router
    // einzelner Eintrag damit das UI granular anzeigen kann welcher down ist.
    try {
      const rr = await pool.query(
        "SELECT id, lxc_id, client_vlan_id, bezeichnung FROM isp_client_vlan_routers WHERE active = true ORDER BY client_vlan_id");
      const token = routerApiToken();
      out.routers = await Promise.all(rr.rows.map(async r => {
        const ip = routerLxcMgmtIp(r.lxc_id);
        let ok = false;
        try {
          const resp = await fetch(`http://${ip}:8080/health`, {
            headers: { 'Authorization': 'Bearer ' + token },
            signal: AbortSignal.timeout(2500),
          });
          ok = resp.ok;
        } catch {}
        // Kurzes Label fuer Dot — "RW9", "RK", etc.
        const labelMatch = (r.bezeichnung || '').match(/^(R[KW]\d*)/);
        const label = labelMatch ? labelMatch[1] : `CT${r.lxc_id}`;
        return { lxc_id: r.lxc_id, client_vlan: r.client_vlan_id, label, ok };
      }));
    } catch (e) { out.routers = []; out.routers_error = e.message; }

    // Frontend-Container-Health: parallel /health auf jeden Service-VIP im
    // Docker-Overlay (interne DNS-Aufloesung ueber rosenweg-net). Granular,
    // damit das NOC-Wallboard pro Container einen Dot zeigt. Internes Probe
    // (Container up?), nicht der WAN-Pfad — das machen Edge/Swarm separat.
    try {
      // De-Swarm: Frontends laufen als native nginx-LXCs (nicht mehr als Swarm-Overlay-
      // Services). /health DIREKT am LXC-IP pruefen statt am toten Swarm-Service-Namen
      // (`http://stweg4/health` war scale=0 -> Dauer-rot trotz laufender Seite).
      const FRONTENDS = [
        { host: '100.64.2.43', label: 'ST1' }, { host: '100.64.2.44', label: 'ST2' },
        { host: '100.64.2.45', label: 'ST3' }, { host: '100.64.2.46', label: 'ST4' },
        { host: '100.64.2.47', label: 'ST5' }, { host: '100.64.2.48', label: 'ST6' },
        { host: '100.64.2.49', label: 'ST7' }, { host: '100.64.2.50', label: 'MEG' },
        { host: '100.64.2.42', label: 'ISP' },
        { host: '100.64.2.41', label: 'WWW' },
      ];
      out.frontends = await Promise.all(FRONTENDS.map(async f => {
        let ok = false;
        try {
          const resp = await fetch(`http://${f.host}/health`, { signal: AbortSignal.timeout(2500) });
          ok = resp.ok;
        } catch {}
        return { label: f.label, ok };
      }));
    } catch (e) { out.frontends = []; out.frontends_error = e.message; }

    // Infrastruktur-LXC-Health aus Proxmox (cluster/resources): kritische CTs als
    // Dot — gestoppte/fehlende sofort sichtbar (haette dc1 gezeigt). Router-CTs (5xx)
    // sind oben schon als out.routers; hier die Infrastruktur-CTs.
    try {
      const INFRA = {
        100: 'PDM', 102: 'NTP', 104: 'NC', 105: 'MQTT', 106: 'FILE', 108: 'DC1',
        109: 'TVPRX', 111: 'CUPS', 113: 'VPN', 114: 'AUTH', 115: 'ZPUSH', 116: 'WA',
        206: 'FILE2', 220: 'PBX', 230: 'PMG',
        240: 'MAIL', 245: 'EDGE', 250: 'TV7', 260: 'NFS',
      };
      const pve = await pveAPI('GET', '/cluster/resources?type=vm'); // gibt .data-Array direkt
      const byId = {};
      for (const x of (Array.isArray(pve) ? pve : [])) if (x.type === 'lxc') byId[x.vmid] = x;
      out.lxcs = Object.entries(INFRA).map(([id, label]) => {
        const x = byId[Number(id)];
        return { vmid: Number(id), label, status: x ? x.status : 'missing', ok: !!x && x.status === 'running' };
      }).sort((a, b) => a.label.localeCompare(b.label));
    } catch (e) { out.lxcs = []; out.lxcs_error = e.message; }

    res.json(out);
  } catch (err) {
    out.error = err.message;
    res.json(out);
  }
}
app.get('/api/isp/noc/unifi', authMiddleware, requireTechnikOrPraesident, nocUnifiHandler);

// ─── Edge-Traefik Dynamic-Config-Provider ──────────────────────────────
// Wird vom Traefik in LXC 245 alle 15s gepollt (HTTP-Provider). Liefert
// die aktuelle Route-Liste als Traefik-JSON-Schema. KEIN authMiddleware —
// nur erreichbar im internen LAN, und Traefik kennt keinen Auth-Header.
// safeId -> lib/utils.js

async function buildTraefikDynamicConfig() {
  // WICHTIG: leere sections (z.B. middlewares: {}) lassen Traefik file-provider
  // mit "middlewares cannot be a standalone element" abbrechen. Wir fuellen
  // unten und cleanen am Ende.
  const cfg = { http: { routers: {}, services: {}, middlewares: {}, serversTransports: {} }, tcp: { routers: {}, services: {} } };
  // ServersTransport für HTTPS-Backends mit Self-Signed / Mismatched Certs
  // (typisch für interne Services wie Mailcow, NCP etc.). InsecureSkipVerify
  // ist hier sicher weil der Hop Edge-Traefik → Backend über das interne
  // LAN laeuft, kein WAN dazwischen.
  cfg.http.serversTransports['insecure-internal'] = { insecureSkipVerify: true };

  // 1) HTTP-Routes aus isp_reverse_proxy_routes
  const rps = await pool.query(
    `SELECT * FROM isp_reverse_proxy_routes
      WHERE active = true AND COALESCE(protocol,'http') = 'http'
        AND COALESCE(approval_status,'approved') = 'approved'
      ORDER BY id`).catch(() => ({ rows: [] }));
  for (const r of rps.rows) {
    if (!ispHostGueltig(r.hostname) || (r.strip_prefix && !ispPfadGueltig(r.strip_prefix))) { console.warn('[traefik] Route übersprungen, ungültiger Host/Pfad:', r.id); continue; }
    const id = safeId(`rp-${r.id}-${r.hostname}`);
    const svc = id + '-svc';
    cfg.http.routers[id] = {
      rule: `Host(\`${r.hostname}\`)`,
      entryPoints: [r.entry_point || 'websecure'],
      service: svc,
    };
    if (r.ssl !== false) {
      cfg.http.routers[id].tls = { certResolver: r.cert_resolver || 'cf' };
    }
    if (r.strip_prefix) {
      const mw = id + '-strip';
      cfg.http.middlewares[mw] = { stripPrefix: { prefixes: [r.strip_prefix] } };
      cfg.http.routers[id].middlewares = [mw];
    }
    cfg.http.services[svc] = {
      loadBalancer: {
        servers: [{ url: r.backend_url }],
        passHostHeader: r.preserve_host !== false,
      },
    };
    // HTTPS-Backend → insecureSkipVerify damit interne Self-Signed/
    // Mismatched Certs (z.B. Mailcow's eigenes Cert) nicht zum 502 fuehren.
    if (/^https:\/\//i.test(r.backend_url || '')) {
      cfg.http.services[svc].loadBalancer.serversTransport = 'insecure-internal';
    }
  }

  // 1b) HTTP-Redirects aus isp_redirects (301/302/307/308 am Edge)
  const redirs = await pool.query(
    `SELECT * FROM isp_redirects
      WHERE active = true AND COALESCE(approval_status,'approved') = 'approved'
      ORDER BY id`).catch(() => ({ rows: [] }));
  for (const r of redirs.rows) {
    if (!ispHostGueltig(r.source_host) || !ispPfadGueltig(r.source_path || '/')) { console.warn('[traefik] Redirect übersprungen, ungültiger Host/Pfad:', r.id); continue; }
    const id = safeId(`redir-${r.id}-${r.source_host}`);
    const mw = id + '-mw';
    const path = r.source_path || '/';
    // Rule: Host + optional PathPrefix (wenn nicht "/")
    const rule = path === '/' ? `Host(\`${r.source_host}\`)` : `Host(\`${r.source_host}\`) && PathPrefix(\`${path}\`)`;
    // RedirectRegex: ^https?://<host><path>(/.*)? → target_url($1) wenn preserve_path
    const escHost = r.source_host.replace(/\./g, '\\.');
    const escPath = path.replace(/\./g, '\\.');
    const regex = r.preserve_path
      ? `^https?://${escHost}${escPath === '/' ? '' : escPath}(/.*)?$`
      : `^https?://${escHost}.*$`;
    const replacement = r.preserve_path
      ? `${r.target_url.replace(/\/$/, '')}\${1}`
      : r.target_url;
    cfg.http.middlewares[mw] = {
      redirectRegex: { regex, replacement, permanent: (r.http_code === 301 || r.http_code === 308) },
    };
    cfg.http.routers[id] = {
      rule,
      entryPoints: ['websecure'],
      service: 'noop@internal',  // wird durch middleware abgefangen, kein backend nötig
      middlewares: [mw],
      tls: { certResolver: 'cf' },
      priority: 100,  // höher als sonstige routes damit Redirect zuerst greift
    };
  }

  // 1c) TCP-SNI / TCP-RAW aus isp_reverse_proxy_routes
  // protocol='tcp_sni': HostSNI mit TLS-Passthrough (Backend liefert Cert)
  // protocol='tcp_raw': reines TCP-Forward ohne SNI (Backend braucht's nicht)
  const rpsTcp = await pool.query(
    `SELECT * FROM isp_reverse_proxy_routes
      WHERE active = true AND protocol IN ('tcp_sni','tcp_raw')
        AND COALESCE(approval_status,'approved') = 'approved'
      ORDER BY id`).catch(() => ({ rows: [] }));
  for (const r of rpsTcp.rows) {
    if (!ispHostGueltig(r.hostname)) { console.warn('[traefik] TCP-Route übersprungen, ungültiger Host:', r.id); continue; }
    const id = safeId(`rp-${r.id}-${r.hostname}`);
    const svc = id + '-svc';
    // backend_url: erwarteter Form "host:port" (kein scheme); fallback http://
    let addr = r.backend_url || '';
    addr = addr.replace(/^https?:\/\//, '').replace(/\/+$/, '');
    cfg.tcp.routers[id] = {
      rule: r.protocol === 'tcp_sni'
        ? `HostSNI(\`${r.hostname}\`)`
        : `HostSNI(\`*\`)`,  // raw TCP: matches all SNI (entrypoint-spezifisch)
      entryPoints: [r.entry_point || 'websecure'],
      service: svc,
    };
    if (r.protocol === 'tcp_sni') {
      cfg.tcp.routers[id].tls = { passthrough: true };
    }
    cfg.tcp.services[svc] = {
      loadBalancer: { servers: [{ address: addr }] },
    };
  }

  // 2) TCP-SNI-Passthrough für Mail-Relays
  const mrs = await pool.query(
    `SELECT * FROM isp_mail_relays
      WHERE active = true
        AND COALESCE(approval_status,'approved') = 'approved'
        AND (imap_sni_hostname IS NOT NULL OR smtps_sni_hostname IS NOT NULL OR sni_alias IS NOT NULL)
      ORDER BY id`).catch(() => ({ rows: [] }));
  for (const m of mrs.rows) {
    // Namen/Adressen landen woertlich in HostSNI-Regeln — Ungueltiges auslassen.
    if (!mailRelayEintragGueltig(m)) { console.warn('[traefik] Mail-Relay übersprungen, ungültiger Host/Port:', m.id); continue; }
    // Aliasname (z. B. mail.<domain>): IMAPS auf Mailcow, SMTPS auf den
    // SMTPS-Host (PMG ist Eingang fuer alles SMTP; dessen Zertifikat enthaelt
    // den Aliasnamen seit 18.11.2026). Ohne SMTPS-Host wie frueher auf Mailcow.
    if (m.sni_alias && m.imap_host) {
      const ziele = [
        ['imaps', m.imap_host, m.imap_port || 993],
        ['smtps', m.smtps_host || m.imap_host, m.smtps_host ? (m.smtps_port || 465) : 465],
      ];
      for (const [ep, host, port] of ziele) {
        const id = safeId(`${ep}-alias-${m.id}-${m.sni_alias}`);
        const svc = id + '-svc';
        cfg.tcp.routers[id] = {
          rule: `HostSNI(\`${m.sni_alias}\`)`,
          entryPoints: [ep],
          service: svc,
          tls: { passthrough: true },
        };
        cfg.tcp.services[svc] = { loadBalancer: { servers: [{ address: mailRelayAdresse(host, port) }] } };
      }
    }
    if (m.imap_sni_hostname && m.imap_host) {
      const id = safeId(`imaps-${m.id}-${m.imap_sni_hostname}`);
      const svc = id + '-svc';
      cfg.tcp.routers[id] = {
        rule: `HostSNI(\`${m.imap_sni_hostname}\`)`,
        entryPoints: ['imaps'],
        service: svc,
        tls: { passthrough: true },
      };
      cfg.tcp.services[svc] = {
        loadBalancer: { servers: [{ address: mailRelayAdresse(m.imap_host, m.imap_port || 993) }] },
      };
    }
    if (m.smtps_sni_hostname && m.smtps_host) {
      const id = safeId(`smtps-${m.id}-${m.smtps_sni_hostname}`);
      const svc = id + '-svc';
      cfg.tcp.routers[id] = {
        rule: `HostSNI(\`${m.smtps_sni_hostname}\`)`,
        entryPoints: ['smtps'],
        service: svc,
        tls: { passthrough: true },
      };
      cfg.tcp.services[svc] = {
        loadBalancer: { servers: [{ address: mailRelayAdresse(m.smtps_host, m.smtps_port || 465) }] },
      };
    }
  }

  // Cleanup: strip leere sub-objekte damit Traefik-File-Provider nicht
  // über "middlewares cannot be a standalone element" stolpert.
  for (const proto of ['http', 'tcp']) {
    for (const key of Object.keys(cfg[proto])) {
      if (!cfg[proto][key] || Object.keys(cfg[proto][key]).length === 0) {
        delete cfg[proto][key];
      }
    }
    if (Object.keys(cfg[proto]).length === 0) delete cfg[proto];
  }
  return cfg;
}

app.get('/api/traefik/dynamic', async (req, res) => {
  // Shared-Secret statt IP-Allowlist: der frühere "nur intern"-Check
  // vertraute dem ersten X-Forwarded-For-Eintrag, der über die Edge intern
  // ist — von außen umgehbar und leakte die komplette Routing-Topologie inkl.
  // Backend-IPs. Konsument ist ausschließlich traefik-sync.sh (CT245), das
  // den Header X-Traefik-Secret setzt. Fail-closed: ohne korrektes Secret 403
  // (Sync behält dann seine letzte Config — Routing bleibt, Updates stoppen).
  const expected = process.env.TRAEFIK_CONFIG_SECRET || '';
  if (!expected || !geheimnisGleich(req.headers['x-traefik-secret'], expected)) {
    return res.status(403).json({ error: 'forbidden' });
  }
  try {
    const cfg = await buildTraefikDynamicConfig();
    res.json(cfg);
  } catch (err) {
    console.error('[traefik/dynamic]', err.message);
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/isp/dns-info', authMiddleware, (req, res) => {
  res.json(ispResolveTarget());
});

// Endpoint: DNS-Check on-demand
// DynDNS-Endpoint für UniFi / UDM-Pro:
// Format: GET /api/cf-ddns?hostname=public&myip=37.17.232.133
// Auth: HTTP Basic (user:pass via header) — pass = env CF_DDNS_TOKEN
// Update Cloudflare-A-Record für die gegebene Subdomain auf myip
app.get('/api/cf-ddns', async (req, res) => {
  try {
    const expectedToken = process.env.CF_DDNS_TOKEN;
    if (!expectedToken) return res.status(500).send('badconfig');
    const auth = req.headers.authorization || '';
    let providedPass = '';
    if (auth.startsWith('Basic ')) {
      try {
        const decoded = Buffer.from(auth.slice(6), 'base64').toString();
        providedPass = decoded.split(':').slice(1).join(':');
      } catch {}
    } else if (req.query.password) {
      // Altweg fuer DynDNS-Clients ohne Basic-Auth (landet in Zugriffs-Logs).
      providedPass = String(req.query.password);
    }
    if (!geheimnisGleich(providedPass, expectedToken)) return res.status(401).send('badauth');

    const hostname = String(req.query.hostname || '').trim().toLowerCase();
    const myip = String(req.query.myip || req.query.ip || '').trim();
    if (!hostname || !myip) return res.status(400).send('911');
    if (!/^[\d.]+$|^[\da-f:]+$/i.test(myip)) return res.status(400).send('badip');

    const cfToken = process.env.CLOUDFLARE_API_TOKEN;
    const cfZone = process.env.CLOUDFLARE_ZONE_ID || '0b113bed342ed868b4b42c09149ea2b5';
    if (!cfToken) return res.status(500).send('badconfig');

    // Allowlist: erlaubte Hostnames die per DDNS aktualisiert werden dürfen
    const allowlist = (process.env.CF_DDNS_ALLOWLIST || 'public').toLowerCase().split(',').map(s => s.trim());
    const shortName = hostname.replace('.rosenweg4303.ch', '');
    if (!allowlist.includes(shortName) && !allowlist.includes(hostname)) {
      return res.status(403).send('badhost:' + shortName);
    }
    const fqdn = hostname.includes('.') ? hostname : hostname + '.rosenweg4303.ch';

    // Record ID holen
    const isV6 = myip.includes(':');
    const recType = isV6 ? 'AAAA' : 'A';
    const list = await fetch(`https://api.cloudflare.com/client/v4/zones/${cfZone}/dns_records?name=${fqdn}&type=${recType}`, {
      headers: { Authorization: 'Bearer ' + cfToken },
    }).then(r => r.json());
    const existing = list.result?.[0];
    if (existing && existing.content === myip) return res.send('nochg ' + myip);

    if (existing) {
      const up = await fetch(`https://api.cloudflare.com/client/v4/zones/${cfZone}/dns_records/${existing.id}`, {
        method: 'PATCH',
        headers: { Authorization: 'Bearer ' + cfToken, 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: myip, comment: 'DDNS auto-updated ' + new Date().toISOString().slice(0,19) }),
      }).then(r => r.json());
      if (!up.success) { console.error('[ddns] CF patch fail:', up.errors); return res.status(502).send('dnserr'); }
    } else {
      const cr = await fetch(`https://api.cloudflare.com/client/v4/zones/${cfZone}/dns_records`, {
        method: 'POST',
        headers: { Authorization: 'Bearer ' + cfToken, 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: recType, name: fqdn, content: myip, ttl: 300, proxied: false, comment: 'DDNS auto-created' }),
      }).then(r => r.json());
      if (!cr.success) return res.status(502).send('dnserr');
    }
    console.log('[ddns] Updated ' + fqdn + ' → ' + myip);
    res.send('good ' + myip);
  } catch (err) { console.error('[ddns]', err); res.status(500).send('911'); }
});

app.get('/api/isp/check-dns', authMiddleware, async (req, res) => {
  const host = String(req.query.host || '').trim().toLowerCase();
  if (!host) return res.status(400).json({ error: 'host param Pflicht' });
  // Nur gueltige DNS-Namen, begrenzt — sonst ein frei nutzbares DNS-Orakel.
  if (!ispHostGueltig(host)) return res.status(400).json({ error: 'Ungültiger Hostname' });
  if (!rateLimitGuard('isp-check-dns', String(req.user.email || 'anon').toLowerCase(), 30, 10 * 60 * 1000).ok) {
    return res.status(429).json({ error: 'Zu viele Abfragen — bitte später erneut.' });
  }
  const out = await ispCheckDns(host);
  if (!ispIsAdmin(req)) {
    // Der System-Resolver kennt die internen Namen (Split-DNS) — deren Adressen
    // gehen Nicht-Admins nichts an; ebenso wenig die Eintraege unserer Zonen.
    if (out.resolver !== 'oeffentlich') { out.a = null; out.aaaa = null; out.cname = null; out.cname_ziel = null; }
    delete out.cf_records;
  }
  res.json(out);
});

// Endpoint: re-check eines Eintrags (von Customer ausgeloest)
app.post('/api/isp/redirects/:id/recheck-dns', authMiddleware, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const e = await pool.query('SELECT * FROM isp_redirects WHERE id = $1', [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = e.rows[0];
    const isOwner = ispIstBesitzer(req, v);
    if (!isOwner && !ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Owner oder Admin' });
    const check = await ispCheckDns(v.source_host);
    // Freigeben nur aus 'pending_dns' — 'pending_admin' (z.B. *rosenweg*-Namen) bleibt beim Admin.
    // Ueberschneidet sich der Name mit einem fremden Eintrag, geht er an den Admin statt frei.
    const konflikt = check.matches && v.approval_status === 'pending_dns'
      ? await ispHostKonflikt(v.source_host, { ownerEmail: v.owner_email, ausser: { tabelle: 'isp_redirects', id } }) : null;
    const upd = konflikt
      ? { approval_status: 'pending_admin', dns_verified_at: new Date(), last_dns_check_at: new Date(), approval_reason: konflikt }
      : check.matches && v.approval_status === 'pending_dns'
      ? { approval_status: 'approved', dns_verified_at: new Date(), last_dns_check_at: new Date(), active: true, approval_reason: 'DNS verifiziert' }
      : check.matches ? { dns_verified_at: new Date(), last_dns_check_at: new Date() }
      : { last_dns_check_at: new Date() };
    await pool.query(
      `UPDATE isp_redirects SET approval_status = COALESCE($1, approval_status),
         dns_verified_at = COALESCE($2, dns_verified_at), last_dns_check_at = $3,
         active = COALESCE($4, active), approval_reason = COALESCE($5, approval_reason) WHERE id = $6`,
      [upd.approval_status, upd.dns_verified_at, upd.last_dns_check_at, upd.active, upd.approval_reason, id],
    );
    res.json({ ...check, updated: upd });
  } catch (err) { res.status(500).json({ error: fehlerFuerClient(err, 'DNS-Prüfung fehlgeschlagen') }); }
});

// DNS selbst einrichten — nur fuer Namen in unseren eigenen Zonen. Owner
// oder Admin; ein fremder bestehender Eintrag wird nicht ueberschrieben.
async function ispDnsEinrichten(req, res, tabelle, spalte) {
  try {
    const id = parseInt(req.params.id, 10);
    const e = await pool.query(`SELECT * FROM ${tabelle} WHERE id = $1`, [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = e.rows[0];
    const isOwner = ispIstBesitzer(req, v);
    if (!isOwner && !ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Owner oder Admin' });
    const host = v[spalte];
    // Ein DNS-Eintrag in UNSERER Zone ist eine Zusage: Wildcards nie, und fuer
    // Nicht-Admins nur, wenn der Eintrag nicht beim Admin liegt (pending_admin,
    // z.B. *rosenweg*-Namen) und sich nicht mit fremden Eintraegen ueberschneidet.
    if (!ispHostGueltig(host) || String(host).startsWith('*.')) {
      return res.status(400).json({ ok: false, grund: 'Für Wildcard-Namen setzen wir keinen DNS-Eintrag' });
    }
    if (!ispIsAdmin(req)) {
      if (v.approval_status === 'pending_admin' || v.approval_status === 'rejected') {
        return res.status(403).json({ ok: false, grund: 'Der Eintrag wartet auf die Freigabe durch einen Admin' });
      }
      // Vom Admin freigegebene Eintraege: die Zone-Regel ist damit erfuellt, nur echte
      // Ueberschneidungen mit fremden Eintraegen bleiben gesperrt.
      const konflikt = await ispHostKonflikt(host, { ownerEmail: v.owner_email, ausser: { tabelle, id }, ohneZone: v.approval_status === 'approved' });
      if (konflikt) return res.status(409).json({ ok: false, grund: konflikt });
    }
    const gesetzt = await ispCfCnameSetzen(host, req.body?.proxied === true);
    console.log(`[isp] DNS einrichten ${host} durch ${req.user.email}: ${gesetzt.ok ? 'ok' : 'abgelehnt'} — ${gesetzt.grund}`);
    // Direkt nachpruefen: Cloudflare ist sofort wirksam, oeffentliches DNS
    // braucht je nach Zwischenspeicher etwas laenger.
    const check = await ispCheckDns(host).catch(() => null);
    if (check && check.matches) {
      // Reverse-Proxy von Nicht-Admins: nach DNS noch Admin-Freigabe (Backend), siehe POST.
      const ziel = (tabelle === 'isp_reverse_proxy_routes' && !ispIsAdmin(req)) ? 'pending_admin' : 'approved';
      await pool.query(
        `UPDATE ${tabelle} SET approval_status = CASE WHEN approval_status = 'pending_dns' THEN $2 ELSE approval_status END,
           dns_verified_at = NOW(), last_dns_check_at = NOW(),
           active = CASE WHEN approval_status = 'approved' OR (approval_status = 'pending_dns' AND $2 = 'approved') THEN true ELSE active END
         WHERE id = $1`, [id, ziel]).catch(() => {});
    }
    res.json({ ...gesetzt, check });
  } catch (err) { res.status(500).json({ error: fehlerFuerClient(err, 'DNS-Eintrag konnte nicht gesetzt werden') }); }
}
app.post('/api/isp/reverse-proxy/:id/dns-einrichten', authMiddleware, (req, res) =>
  ispDnsEinrichten(req, res, 'isp_reverse_proxy_routes', 'hostname'));
app.post('/api/isp/redirects/:id/dns-einrichten', authMiddleware, (req, res) =>
  ispDnsEinrichten(req, res, 'isp_redirects', 'source_host'));

app.post('/api/isp/reverse-proxy/:id/recheck-dns', authMiddleware, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const e = await pool.query('SELECT * FROM isp_reverse_proxy_routes WHERE id = $1', [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = e.rows[0];
    const isOwner = ispIstBesitzer(req, v);
    if (!isOwner && !ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Owner oder Admin' });
    const check = await ispCheckDns(v.hostname);
    // Aus 'pending_dns' wird bei Nicht-Admins 'pending_admin' (Backend-Pruefung), nie direkt 'approved'.
    const upd = check.matches && v.approval_status === 'pending_dns'
      ? (ispIsAdmin(req)
        ? { approval_status: 'approved', dns_verified_at: new Date(), last_dns_check_at: new Date(), active: true, approval_reason: 'DNS verifiziert' }
        : { approval_status: 'pending_admin', dns_verified_at: new Date(), last_dns_check_at: new Date(), approval_reason: 'DNS ok — Backend wartet auf Admin-Freigabe' })
      : check.matches ? { dns_verified_at: new Date(), last_dns_check_at: new Date() }
      : { last_dns_check_at: new Date() };
    await pool.query(
      `UPDATE isp_reverse_proxy_routes SET approval_status = COALESCE($1, approval_status),
         dns_verified_at = COALESCE($2, dns_verified_at), last_dns_check_at = $3,
         active = COALESCE($4, active), approval_reason = COALESCE($5, approval_reason) WHERE id = $6`,
      [upd.approval_status, upd.dns_verified_at, upd.last_dns_check_at, upd.active, upd.approval_reason, id],
    );
    res.json({ ...check, updated: upd });
  } catch (err) { res.status(500).json({ error: fehlerFuerClient(err, 'DNS-Prüfung fehlgeschlagen') }); }
});

// Liefert UniFi-Switches mit Ports + alle VLAN-Netze fuer Admin-Dropdowns
// im Anschluss-erfassen-Modal. Admin-only, kein Caching (live).
app.get('/api/isp/unifi-options', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Technik/Präsident' });
    const out = { switches: [], vlans: [] };
    try {
      const d = await unifiGet('stat/device');
      out.switches = (d.data || [])
        .filter(x => x.type === 'usw')
        .map(x => ({
          name: x.name,
          model: x.model,
          mac: x.mac,
          ports: (x.port_table || []).map(p => ({
            idx: p.port_idx,
            name: p.name || p.port_name || `Port ${p.port_idx}`,
            media: p.media,
          })),
        }))
        .sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    } catch (e) { out.switches_error = e.message; }
    try {
      const n = await unifiGet('rest/networkconf');
      out.vlans = (n.data || [])
        .filter(x => x.vlan && x.enabled !== false)
        .map(x => ({ vlan: x.vlan, name: x.name, purpose: x.purpose, networkconf_id: x._id }))
        .sort((a, b) => a.vlan - b.vlan);
    } catch (e) { out.vlans_error = e.message; }
    try {
      const p = await unifiGet('rest/portconf');
      out.port_profiles = (p.data || [])
        .map(x => ({ id: x._id, name: x.name, native_networkconf_id: x.native_networkconf_id }))
        .sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    } catch (e) { out.port_profiles_error = e.message; }
    res.json(out);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

