// === VPN-Konten ===
//
// VPN-Backend: kleiner Steuerdienst `wg-control` auf der vpn-wg-LXC
// (CT 113, 100.64.2.34:3001). Erzeugt Peer-Keypair, hängt ihn in wg0 ein,
// macht per-Peer-NAT in das Heim-VLAN des Users und liefert die
// fertige Client-.conf + QR-Code zurück.
const WG_CONTROL_URL   = process.env.WG_CONTROL_URL   || 'http://100.64.2.34:3001';
const WG_CONTROL_TOKEN = process.env.WG_CONTROL_TOKEN || '';

async function wgControl(method, path, body) {
  const r = await fetch(WG_CONTROL_URL + path, {
    method,
    headers: {
      'Authorization': 'Bearer ' + WG_CONTROL_TOKEN,
      ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
    },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  if (!r.ok) {
    const txt = await r.text().catch(() => '');
    const e = new Error(`wg-control ${method} ${path} -> ${r.status}: ${txt}`);
    e.status = r.status >= 500 ? 502 : r.status;
    throw e;
  }
  return r;
}

// Rosenweg-Nr → VLAN (synchron mit /opt/wg-control/server.js)
const VPN_RW_TO_VLAN = {1:19,2:29,4:49,5:59,6:69,8:89,9:99,10:109,12:129,13:139,14:149,16:169,17:179,18:189};
function vpnRwFromBezeichnung(bez) {
  if (!bez) return null;
  let m = bez.match(/^RW(\d+)/i);
  if (m) return parseInt(m[1], 10);
  m = bez.match(/^(\d+)[\.\-]/);
  if (m) return parseInt(m[1], 10);
  m = bez.match(/^(\d{2})(\d{2})$/);
  if (m) { const rw = parseInt(m[1], 10); if (rw >= 10 && rw <= 18) return rw; }
  return null;
}
// Klassifiziert einen Wohnungs-Eintrag in Kategorie + VLAN.
// Reihenfolge bei Default-Pick: wohnung (0) -> hobbyraum (1) -> parkplatz (2)
function classifyVpnEntry(bezeichnung) {
  const b = bezeichnung || '';
  // Hobbyraum: explizit oder mit Hausnummer-Prefix
  if (/hobbyraum/i.test(b)) {
    const rw = vpnRwFromBezeichnung(b);
    return { kind: 'hobbyraum', kindOrder: 1, vlan: (rw && VPN_RW_TO_VLAN[rw]) || null };
  }
  // Parkplatz: P\d+
  if (/^P\d+/i.test(b)) return { kind: 'parkplatz', kindOrder: 2, vlan: 9 };
  // Wohnung: alles mit erkennbarer Hausnummer
  const rw = vpnRwFromBezeichnung(b);
  if (rw && VPN_RW_TO_VLAN[rw]) return { kind: 'wohnung', kindOrder: 0, vlan: VPN_RW_TO_VLAN[rw] };
  return { kind: 'unbekannt', kindOrder: 9, vlan: null };
}

// Einheiten (Wohnung > Hobbyraum > Parkplatz) einer Person mit ihrem Client-VLAN.
// Standard: nur Einheiten, in denen sie WOHNT, ab dem Einzugsdatum (lib/isp-zugang.js,
// Entscheid Stefan 28.11.2026) - Grundlage fuer Haus-WLAN, VPN-Optionen, VPN anlegen,
// Laptop-Tunnel und Netz-Antraege. alleKontakte: jeder aktive Kontakt (nur fuer die
// Technik beim Bearbeiten eines bestehenden Netz-Antrags).
async function getUserVlanOptions(email, { alleKontakte = false } = {}) {
  if (!email) return [];
  const r = await pool.query(
    `SELECT w.id AS wohnung_id, w.bezeichnung, w.stweg
       FROM wohnungen_kontakte wk
       JOIN wohnungen w ON w.id = wk.wohnung_id
       JOIN personen p  ON p.id = wk.person_id
      WHERE ${alleKontakte ? 'wk.archiviert_am IS NULL' : ispZugang.wohntSql('wk', 'w')}
        AND ( LOWER(p.email) = LOWER($1)
              OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(p.emails,'[]'::jsonb)) e
                          WHERE LOWER(e) = LOWER($1)) )`,
    [email],
  );
  const opts = r.rows
    .map(row => ({ ...row, ...classifyVpnEntry(row.bezeichnung) }))
    .filter(o => o.vlan);
  // Dedup: gleiche (kind, vlan, wohnung_id)
  const seen = new Set();
  const dedup = opts.filter(o => {
    const k = `${o.kind}:${o.vlan}:${o.wohnung_id}`;
    if (seen.has(k)) return false; seen.add(k); return true;
  });
  dedup.sort((a, b) => a.kindOrder - b.kindOrder || (a.bezeichnung || '').localeCompare(b.bezeichnung || ''));
  return dedup;
}

async function resolveHomeVlanForEmail(email) {
  const opts = await getUserVlanOptions(email);
  return opts.length > 0 ? opts[0].vlan : null;
}

// Wo liegt der private Schluessel? 'geraet' | 'server' | null (unbekannt, Altbestand).
function vpnSchluesselOrt(v) {
  return v?.schluessel_ort === 'geraet' || v?.schluessel_ort === 'server' ? v.schluessel_ort : null;
}
// Gesperrt (Auszug, Kontoloeschung) oder Schluessel nur auf dem Geraet: keine Konfiguration.
function vpnAbrufSperre(v) {
  if (v?.gesperrt_am) return { status: 410, error: `Dieser VPN-Zugang ist gesperrt (${v.gesperrt_grund || 'kein Wohnsitz mehr'}).` };
  if (vpnSchluesselOrt(v) === 'geraet') return { status: 409, error: 'Der private Schlüssel liegt auf dem Gerät — der Server hat keine Konfiguration und keinen QR-Code.' };
  return null;
}
// Technik/Praesident ruft die Konfiguration einer anderen Person ab -> Protokoll.
async function vpnFremdSichtProtokoll(req, v, was) {
  const eigene = (v.user_email || '').toLowerCase() === (req.user.email || '').toLowerCase();
  if (eigene) return;
  await ispAdminSichtProtokoll(req, 'vpn-konfiguration-angesehen', `VPN #${v.id} · ${v.user_email || '?'}`,
    `${was}${v.bezeichnung ? ' · ' + v.bezeichnung : ''}${v.assigned_ip ? ' · ' + v.assigned_ip : ''}`,
    `Internet (ISP): VPN-${was} einer anderen Person angesehen`);
}

app.get('/api/isp/vpn-accounts', authMiddleware, async (req, res) => {
  try {
    // ?nur=meine: auch Technik/Praesident bekommen nur die eigenen (App "Meine VPN").
    const istAdmin = ispIsAdmin(req);
    const admin = istAdmin && !ispZugang.nurMeine(req.query);
    const email = (req.user.email || '').toLowerCase();
    const r = admin
      ? await pool.query('SELECT * FROM isp_vpn_accounts ORDER BY active DESC, user_email, backend')
      : await pool.query('SELECT * FROM isp_vpn_accounts WHERE LOWER(user_email) = $1 ORDER BY active DESC, backend', [email]);
    let rows = r.rows;
    // last_connect_at wird in der DB nie gefüllt — Live-Handshake aus wg-control überlagern
    if (WG_CONTROL_TOKEN && rows.length) {
      try {
        const wr = await wgControl('GET', '/peers');
        const body = await wr.json();
        const peers = Array.isArray(body) ? body : (body.peers || []);
        const hsMap = new Map();
        for (const p of peers) {
          const hs = p.latest_handshake || null;
          if (p.public_key) hsMap.set('pk:' + p.public_key, hs);
          if (p.id != null) hsMap.set('id:' + String(p.id), hs);
          if (p.name) hsMap.set('nm:' + p.name, hs);
        }
        rows = rows.map(v => {
          const hs = (v.public_key && hsMap.get('pk:' + v.public_key))
            || (v.username && hsMap.get('id:' + String(v.username)))
            || (v.username && hsMap.get('nm:' + v.username)) || null;
          return hs ? { ...v, last_connect_at: hs } : v;
        });
      } catch {}
    }
    rows = rows.map(v => ({ ...v, schluessel: vpnSchluesselOrt(v), gesperrt: !!v.gesperrt_am }));
    res.json({ vpn_accounts: rows, is_admin: istAdmin, nur_meine: istAdmin && !admin });
  } catch (err) { res.status(500).json({ error: fehlerFuerClient(err, 'VPN-Zugänge konnten nicht geladen werden') }); }
});

// Liefert die moeglichen VLAN-Optionen für den User (sortiert nach Wohnung→Hobbyraum→Parkplatz)
app.get('/api/isp/vpn-accounts/options', authMiddleware, async (req, res) => {
  try {
    const target = (req.query.user_email || req.user.email || '').toLowerCase();
    if (!ispIsAdmin(req) && target !== (req.user.email || '').toLowerCase()) {
      return res.status(403).json({ error: 'Du kannst nur eigene Optionen abfragen' });
    }
    const options = await getUserVlanOptions(target);
    res.json({ options, default: options[0]?.vlan || null,
      ...(options.length ? {} : { hinweis: 'VPN ins Hausnetz gibt es nur für Personen, die in einer Wohnung wohnen, ab dem Einzugsdatum.' }) });
  } catch (err) { res.status(500).json({ error: fehlerFuerClient(err, 'VLAN-Optionen konnten nicht geladen werden') }); }
});

// ─── Tunnel für eine Laptop-Station ──────────────────────────────────
//
// Ein Laptop ist die einzige Stationsart, die das Haus verlässt. Damit er
// unterwegs an seine verschlüsselte Datenpartition kommt, braucht er einen
// Tunnel, über den er als Hausgerät hereinkommt — sonst stünde er ausser Haus
// vor verschlossenen Daten.
//
// Angelegt wird er WÄHREND der Einrichtung, mit dem Einrichtungstoken der
// Person, die den Laptop aufstellt. Deren Wohnung bestimmt das VLAN: der
// Tunnel gehört dorthin, wo das Gerät hingehört.
//
// Technik bekommt einen zweiten in VLAN 9. Der steht NICHT automatisch —
// zwei gleichzeitige Standardrouten wären Ärger, und der Verwaltungstunnel
// ist Werkzeug, nicht Lebensader. Im NetworkManager liegt er deshalb mit
// autoconnect=no und wird bei Bedarf umgeschaltet.
//
// Die Peers landen in isp_vpn_accounts wie alle anderen auch — damit sie in
// der ISP-Verwaltung sichtbar sind und dort zurückgezogen werden können. Das
// Zurückziehen ist der zweite Notausschalter neben dem Sperren: ohne Tunnel
// kommt ein verschwundener Laptop nicht mehr als Hausgerät herein.
// Der Tunnel gehoert der ANGEMELDETEN Person, nicht dem Geraet und nicht dem,
// der es aufgestellt hat.
//
// Bis zum 12. August 2026 hing das hier an der Einrichtungssitzung — der
// Laptop bekam das VLAN dessen, der davorstand. Falsch an zwei Stellen: am
// Zeitpunkt und am Traeger. Ein Laptop, den sich zwei teilen, braucht zwei
// Tunnel, und jeder gilt, wenn der Betreffende angemeldet ist.
//
// Deshalb die App-Sitzung: sie kennt die Person. Der Stationstoken gehoert dem
// Geraet und kennt keine.
app.post('/api/stations/:id/tunnel', stationsRouter.appSession, async (req, res) => {
  try {
    if (!WG_CONTROL_TOKEN) return res.status(503).json({ error: 'wg-control nicht konfiguriert (WG_CONTROL_TOKEN fehlt)' });

    const stationId = String(req.params.id || '').trim();
    if (!stationId) return res.status(400).json({ error: 'Stationskennung fehlt' });
    // Gleiches Format wie bei der Registrierung (routes/stations.js); der Name geht
    // in die wg0.conf von wg-control — Zeilenumbrueche wuerden dort Zeilen einschleusen.
    if (!/^[a-z0-9][a-z0-9-]{1,62}$/.test(stationId)) return res.status(400).json({ error: 'Ungültige Stationskennung' });
    // Nur fuer registrierte, nicht gesperrte/zurueckgezogene Stationen — sonst
    // liessen sich unter Fantasie-Kennungen beliebig Peers anlegen.
    // Ein von Hand eingetragener Windows-Rechner oder Chromecast ist keine Station mit Tunnel.
    const station = await pool.query(
      "SELECT 1 FROM stations WHERE id = $1 AND revoked_at IS NULL AND status = 'aktiv' AND role NOT IN ('windows', 'chromecast', 'kiosk')", [stationId]);
    if (!station.rowCount) return res.status(404).json({ error: 'Station unbekannt oder gesperrt' });

    const email = (req.appUser?.email || '').toLowerCase();
    if (!email) {
      return res.status(400).json({
        error: 'Zu diesem Konto ist keine Mailadresse hinterlegt — ohne sie ist die Wohnung nicht zu finden',
      });
    }

    // Jeder Aufruf legt Peers an und belegt Adressen aus dem Vorrat -> begrenzen.
    if (!rateLimitGuard('station-tunnel', email, 10, 60 * 60 * 1000).ok) {
      return res.status(429).json({ error: 'Zu viele Tunnel-Anfragen — bitte später erneut.' });
    }
    const bestand = await pool.query(
      "SELECT COUNT(*)::int AS n FROM isp_vpn_accounts WHERE LOWER(user_email) = $1 AND notizen LIKE 'Station %'", [email]);
    if ((bestand.rows[0]?.n || 0) >= 20) {
      return res.status(429).json({ error: 'Zu viele Stations-Tunnel für dieses Konto — bitte alte zurückziehen.' });
    }

    let gruppen = [];
    try { gruppen = JSON.parse(req.appUser?.groups_json || '[]'); } catch { gruppen = []; }

    const optionen = await getUserVlanOptions(email);
    const wohnungsVlan = optionen[0]?.vlan || null;
    if (!wohnungsVlan) {
      return res.status(400).json({
        error: 'Keine Wohnung in der Objektverwaltung — das VLAN für den Tunnel ist nicht ermittelbar',
      });
    }

    // Was angelegt wird: die Wohnung immer, VLAN 9 nur für technik.
    // Zwei Namen, zwei Aufgaben.
    //
    // 'name' geht an wg-control und muss eindeutig sein — sonst kollidieren
    // zwei Menschen auf demselben Geraet oder dieselbe Person auf zwei
    // Geraeten. 'anzeige' steht im NetworkManager und wird von Menschen
    // gelesen; dort ist 'Rosenweg-VPN' unendlich viel brauchbarer als
    // 'laptop-test-stefanrosenweg'.
    //
    // Dass die Anzeige nicht eindeutig ist, geht in Ordnung: die Station
    // loescht die Verbindungen einer Person beim Abmelden wieder, es ist also
    // immer nur ein Satz da.
    // Der lokale Teil allein ist nicht eindeutig (stefan@a.ch / stefan@b.ch);
    // darum haengt ein kurzer Hash der ganzen Adresse dran.
    const kurz = email.split('@')[0].replace(/[^a-z0-9._-]/gi, '').slice(0, 32);
    const adrHash = crypto.createHash('sha256').update(email).digest('hex').slice(0, 8);
    const basis = `${stationId}-${kurz.slice(0, 16)}-${adrHash}`;
    // altName: Namensschema vor dem Hash — nur zum Abraeumen eigener Altbestaende.
    const gewuenscht = [{ zweck: 'wohnung', vlan: wohnungsVlan, name: basis, altName: `${stationId}-${kurz}`,
                          anzeige: 'Rosenweg-VPN', autoconnect: true }];
    if (isTechnik(gruppen) || isPraesident(gruppen)) {
      gewuenscht.push({ zweck: 'technik', vlan: 9, name: `${basis}-vlan9`, altName: `${stationId}-${kurz}-vlan9`,
                        anzeige: 'Technik-VPN', autoconnect: false });
    }

    // Die Station bringt ihre oeffentlichen Schluessel selbst mit, je Zweck
    // einen. Dann erzeugt wg-control keinen privaten und kennt ihn nie.
    //
    // Warum je ZWECK und nicht je Tunnel: welche Tunnel jemand bekommt,
    // entscheidet sich erst hier — an der Wohnung und an der Gruppe. Die
    // Station kann also nicht wissen, wie viele sie braucht, und legt
    // stattdessen fuer jeden moeglichen Zweck einen bereit. Was nicht
    // gebraucht wird, verfaellt auf dem Geraet.
    //
    // Ohne diese Angabe bleibt alles wie bisher: wg-control erzeugt das Paar
    // selbst. Der ISP-Weg schickt nichts mit und ist davon nicht beruehrt.
    const schluessel = (req.body && typeof req.body.schluessel === 'object' && req.body.schluessel) || {};

    const tunnel = [];
    for (const wunsch of gewuenscht) {
      // D-3: nur unbedenkliche Zeichen in den wg-control-Namen.
      if (!/^[\w .@-]{1,80}$/.test(wunsch.name)) return res.status(400).json({ error: 'Ungültiger Tunnelname' });
      // Ein zweiter Einrichtungslauf soll keine Peer-Leichen hinterlassen —
      // aber nur EIGENE abraeumen (gleicher Name eines anderen Kontos bleibt).
      const alt = await pool.query(
        `SELECT id, username FROM isp_vpn_accounts
          WHERE bezeichnung IN ($1, $2) AND active = true AND LOWER(user_email) = $3 AND notizen LIKE $4 || ', VLAN %'`,
        [wunsch.name, wunsch.altName, email, `Station ${stationId}`],
      );
      for (const row of alt.rows) {
        await wgControl('DELETE', `/peers/${row.username}`).catch(() => {});
        // Loeschen, nicht auf inaktiv setzen: In dieser Spalte treffen sonst
        // zwei Bedeutungen aufeinander. Auf dem ISP-Weg heisst active=false
        // "beantragt, noch nicht freigeschaltet"; hier hiesse es "war mal da,
        // ist weg". Das NOC zaehlt die Spalte als "VPN pending" und zeigte
        // darum neun offene Antraege an, die Grabsteine abgeraeumter
        // Laptop-Tunnel waren. Der Peer bei wg-control ist eben geloescht
        // worden — die Zeile beschreibt einen Zugang, den es nicht mehr gibt.
        await pool.query('DELETE FROM isp_vpn_accounts WHERE id = $1', [row.id]);
      }

      // Nur das Hausnetz durch den Tunnel, kein Standardweg.
      //
      // Ein Laptop ausser Haus soll sein Internet weiter direkt haben — alles
      // durch den Tunnel zu schicken waere langsamer, faellt bei jedem
      // Unterbruch des Tunnels ganz aus, und niemand hat darum gebeten.
      // 100.64.0.0/16 deckt alle Hausnetze (100.64.<VLAN>.0/24).
      //
      // wg-control setzt ohne diese Angabe weiterhin 0.0.0.0/0, ::/0 — der
      // ISP-Weg (POST /api/isp/vpn-accounts) uebergibt sie nicht und bleibt
      // damit unveraendert. Am 12. August 2026 an beiden Wegen gemessen.
      const antwort = await wgControl('POST', '/peers', {
        name: wunsch.name, email, vlan: wunsch.vlan,
        allowed_ips: '100.64.0.0/16',
        ...(schluessel[wunsch.zweck] ? { public_key: String(schluessel[wunsch.zweck]) } : {}),
      });
      const peer = await antwort.json();
      await pool.query(
        `INSERT INTO isp_vpn_accounts (user_email, backend, username, public_key, assigned_ip,
                                       config_path, active, notizen, bezeichnung, schluessel_ort, wohnsitz_gesehen_am)
         VALUES ($1, 'wireguard', $2, $3, $4, $5, true, $6, $7, $8, CASE WHEN $9::boolean THEN NOW() END)`,
        [email, peer.id, peer.public_key, peer.assigned_ip, `wg-control/${peer.id}`,
          `Station ${stationId}, VLAN ${wunsch.vlan}`, wunsch.name, schluessel[wunsch.zweck] ? 'geraet' : 'server',
          wunsch.zweck === 'wohnung'],
      );
      tunnel.push({
        // Was die Station in den NetworkManager schreibt: der lesbare Name.
        name: wunsch.anzeige,
        // Wie der Peer bei wg-control heisst — fuer das Zurueckziehen.
        peer: wunsch.name,
        // Zu welchem der mitgeschickten Schluessel die Konfiguration passt.
        // Ohne das koennte die Station den privaten Teil nicht zuordnen.
        zweck: wunsch.zweck,
        vlan: wunsch.vlan,
        autoconnect: wunsch.autoconnect,
        adresse: peer.assigned_ip,
        config: peer.config,
      });
    }

    console.log(`[stations] Tunnel für '${stationId}': ${tunnel.map(t => `VLAN ${t.vlan}`).join(', ')}`);
    res.json({ tunnel });
  } catch (err) {
    console.error('[stations-tunnel]', err.message);
    // Fehlertext von wg-control/DB nicht an die Station weiterreichen (steht im Log).
    res.status(err.status || 500).json({ error: 'Tunnel konnte nicht eingerichtet werden' });
  }
});

// ─── Tunnel zurückziehen, wenn sich jemand abmeldet ──────────────────
//
// Der Tunnel gehört der Person. Also geht er, wenn sie geht — und zwar an
// BEIDEN Enden. Auf dem Laptop löscht das der Abmeldehaken; hier verschwindet
// der Peer.
//
// Warum das nötig ist, obwohl der private Schlüssel neuerdings auf dem Gerät
// bleibt: ein Zugang, der niemandem mehr gehört, soll auch nicht bestehen. Er
// belegt eine Adresse aus dem Vorrat, taucht in jeder Übersicht auf und lädt
// dazu ein, ihn irgendwann wiederzuverwenden.
//
// Beglaubigt wird das mit dem STATIONSTOKEN, nicht mit einer App-Sitzung. Beim
// Abmelden ist niemand mehr da, den man nach einem Passwort fragen könnte. Ein
// Gerät darf abräumen, was es selbst bekommen hat — und nur das: jeder Name
// muss mit der eigenen Stationskennung beginnen, sonst wird er abgelehnt.
app.delete('/api/stations/:id/tunnel', stationsRouter.stationAuth, async (req, res) => {
  try {
    if (!WG_CONTROL_TOKEN) return res.status(503).json({ error: 'wg-control nicht konfiguriert' });

    const stationId = String(req.params.id || '').trim();
    if (!stationId) return res.status(400).json({ error: 'Stationskennung fehlt' });

    const namen = Array.isArray(req.body?.peers) ? req.body.peers.map(String) : [];
    if (!namen.length) return res.json({ entfernt: [], abgelehnt: [] });

    const entfernt = [];
    const abgelehnt = [];

    for (const name of namen.slice(0, 20)) {
      // Die Station darf nur ihre eigenen zurückziehen. Ohne diese Prüfung
      // könnte ein Gerät mit gültigem Token die Zugänge aller anderen löschen.
      if (name !== stationId && !name.startsWith(`${stationId}-`)) {
        abgelehnt.push(name);
        continue;
      }
      // Der Praefix allein reicht nicht: Station 'laptop' traefe sonst auch die
      // Tunnel von 'laptop-test'. Darum zusaetzlich die beim Anlegen vermerkte
      // Station in notizen ("Station <id>, VLAN <n>") exakt pruefen.
      const treffer = await pool.query(
        "SELECT id, username FROM isp_vpn_accounts WHERE bezeichnung = $1 AND active = true AND notizen LIKE $2 || ', VLAN %'",
        [name, `Station ${stationId}`],
      );
      for (const row of treffer.rows) {
        await wgControl('DELETE', `/peers/${row.username}`).catch(() => {});
        // Loeschen, nicht auf inaktiv setzen: In dieser Spalte treffen sonst
        // zwei Bedeutungen aufeinander. Auf dem ISP-Weg heisst active=false
        // "beantragt, noch nicht freigeschaltet"; hier hiesse es "war mal da,
        // ist weg". Das NOC zaehlt die Spalte als "VPN pending" und zeigte
        // darum neun offene Antraege an, die Grabsteine abgeraeumter
        // Laptop-Tunnel waren. Der Peer bei wg-control ist eben geloescht
        // worden — die Zeile beschreibt einen Zugang, den es nicht mehr gibt.
        await pool.query('DELETE FROM isp_vpn_accounts WHERE id = $1', [row.id]);
        entfernt.push(name);
      }
    }

    if (abgelehnt.length) {
      console.warn(`[stations-tunnel] '${stationId}' wollte fremde Peers löschen: ${abgelehnt.join(', ')}`);
    }
    console.log(`[stations] Tunnel zurückgezogen für '${stationId}': ${entfernt.join(', ') || 'nichts'}`);
    res.json({ entfernt, abgelehnt });
  } catch (err) {
    console.error('[stations-tunnel-delete]', err.message);
    res.status(err.status || 500).json({ error: err.message });
  }
});

