// Letzter Fehler-Handler (S1-18): Fehler aus Routen (next(err), Multer, Router) ohne
// Stacktrace beantworten — Express zeigt ihn sonst ausserhalb von NODE_ENV=production.
app.use((err, req, res, next) => {
  if (res.headersSent) return next(err);
  const status = Number.isInteger(err?.status) && err.status >= 400 && err.status < 500 ? err.status : 500;
  if (status === 500) console.error('[fehler]', req.method, req.path, err?.message);
  res.status(status).json({ error: status === 500 ? 'Interner Fehler' : status === 413 ? 'Anfrage zu gross' : 'Ungültige Anfrage' });
});

initDB()
  .then(() => {
    server = app.listen(PORT, () => {
      console.log(`Rosenweg API running on port ${PORT}`);
      // Start Waschküche cron jobs
      startWaschCron();
      // Start IMAP polling for verteiler emails
      startImapPoll();
      // Start connection logging (FPÜV)
      startConnectionPolling();
      // SSH: GitHub-Schluessel periodisch abgleichen
      startSshGithubAbgleich();
      // Salzvorrat: stündlich prüfen, ob ein Lager nachbestellt werden muss
      salz.ensureSchema().then(() => salz.starteSalzCron(activeIntervals))
        .catch(e => console.error('[salz] Schema:', e.message));
      // Sicherungen: laufende PC-Sicherungen alle 20 s nachführen (auch ohne offene Seite)
      sicherungen.ensureSchema().then(() => sicherungen.starteNachfuehren(activeIntervals))
        .catch(e => console.error('[sicherungen] Schema:', e.message));
      // Android-Dauertest: Tabelle, und alle 15 min prüfen, ob CT 149 noch Läufe schickt
      androidDauertest.starten(activeIntervals);
      // Mitgelieferte Dokumente (Beispielmappe) in die Ablage, siehe lib/ablage.js
      setTimeout(() => require('./lib/ablage').ablageAbgleichen(), 20 * 1000);
      // Cleanup expired sessions every hour
      activeIntervals.push(setInterval(cleanupExpiredSessions, 60 * 60 * 1000));
      setTimeout(cleanupExpiredSessions, 30 * 1000); // first cleanup after 30s
      // Wartungs-Notification-Cron (1min)
      activeIntervals.push(setInterval(maintProcessScheduledNotifications, 60 * 1000));
      // Throttle-Flush: gepufferte Sammelmeldungen versenden sobald deren
      // 30-Min-Fenster abgelaufen ist (1min granularitaet).
      activeIntervals.push(setInterval(maintFlushNotifyPending, 60 * 1000));
      // UniFi-Geraete-State-Watcher: Network + Protect + Access + Controller
      setTimeout(maintPollUnifiDevices, 30 * 1000);
      setTimeout(maintPollUnifiProtect, 35 * 1000);
      setTimeout(maintPollUnifiAccess,  40 * 1000);
      setTimeout(maintPollControllers,  45 * 1000);
      activeIntervals.push(setInterval(maintPollUnifiDevices, 60 * 1000));
      activeIntervals.push(setInterval(maintPollUnifiProtect, 60 * 1000));
      activeIntervals.push(setInterval(maintPollUnifiAccess,  60 * 1000));
      activeIntervals.push(setInterval(maintPollControllers,  60 * 1000));
      console.log('[Maint] notification cron + unifi (network+protect+access+controllers) watcher gestartet');
    });
  })
  .catch((err) => {
    console.error('Failed to initialize database:', err);
    process.exit(1);
  });

// Graceful shutdown
let shuttingDown = false;
async function gracefulShutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`\n${signal} received. Shutting down gracefully...`);

  // Stop accepting new requests
  if (server) server.close(() => console.log('HTTP server closed'));

  // Clear all intervals
  activeIntervals.forEach(id => clearInterval(id));
  deletionInterval?.stop?.();

  // Close database pools
  try {
    await pool.end();
    await energyPool.end();
    console.log('Database pools closed');
  } catch (err) {
    console.error('Error closing database pools:', err.message);
  }

  // Force exit after 10s
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000).unref();

  process.exit(0);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Prevent crashes from unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason?.message || reason);
});
